select ac_cargar_unidad($ac${"slug":"oceanos-1","rama":"agua_azul","orden":1,"nivel":1,"titulo_es":"El planeta azul","bajada_es":"Siete de cada diez metros cuadrados del planeta están cubiertos de océano. Cómo el mar regula el clima, qué vida guarda y cómo se conecta con los ríos.","objetivos_es":["Dimensionar el océano y su papel en el planeta","Explicar cómo el océano regula el clima absorbiendo calor y CO₂","Describir la red de vida marina y el Mar Argentino","Reconocer los grandes ríos argentinos y su fauna","Valorar las costas y los estuarios como ambientes de transición"],"repasa":["tronco-1","agua-1"],"requiere_tronco":1,"fuentes":["ipcc-ar6-syr","global-carbon-budget","noaa-acidificacion","pampa-azul","inidep","ramsar","parques-nacionales"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"oceanos-1.s1","orden":1,"tipo":"leccion","titulo_es":"Un planeta de agua","bajada_es":"Cuánto océano hay, qué tan profundo es y por qué el Mar Argentino es tan especial.","minutos":10,"pasos":[{"slug":"oceanos-1.s1.p1","orden":1,"grupo":"oceanos-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Siete de cada diez","cuerpo":["El océano cubre alrededor del 71 % de la superficie de la Tierra y guarda cerca del 97 % de toda el agua del planeta. Su profundidad promedio es de unos 3.700 metros, y en las fosas más profundas supera los 10.000 metros.","Aunque lo llamemos con muchos nombres —Atlántico, Pacífico, Índico, Austral, Ártico—, en realidad es un solo océano conectado, que hace circular agua, calor y nutrientes por todo el planeta."],"destacado":{"valor":"≈ 71 %","texto":"de la superficie de la Tierra está cubierta por el océano."}},"solucion":{}},{"slug":"oceanos-1.s1.p2","orden":2,"grupo":"oceanos-1.s1.p2","tipo":"estimar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la superficie de la Tierra está cubierto por el océano.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":71,"banda":"lineal","explicacion":"Alrededor del 71 %. Por eso, visto desde el espacio, es un planeta azul."}},{"slug":"oceanos-1.s1.p3","orden":3,"grupo":"oceanos-1.s1.p3","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas profundidades de menor a mayor.","items":[{"id":"i1","texto":"Una pileta olímpica"},{"id":"i2","texto":"La plataforma continental argentina"},{"id":"i3","texto":"La profundidad promedio del océano"},{"id":"i4","texto":"Las fosas más profundas"}],"extremos":["Menor","Mayor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El océano es mucho más profundo de lo que imaginamos, y casi todo su volumen está en la oscuridad.","valores":{"i1":"unos 2 metros","i2":"menos de 200 metros","i3":"unos 3.700 metros","i4":"más de 10.000 metros"}}},{"slug":"oceanos-1.s1.p4","orden":4,"grupo":"oceanos-1.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El Mar Argentino","cuerpo":["Frente a la costa argentina se extiende una de las plataformas continentales más anchas del mundo: un fondo marino poco profundo, de menos de 200 metros, que en algunas latitudes se aleja cientos de kilómetros de la costa. Más allá, el fondo cae abruptamente en el talud.","En el Mar Argentino se encuentran dos corrientes: la de Malvinas, fría y rica en nutrientes, que viene del sur, y la de Brasil, cálida, que viene del norte. Su encuentro y el borde del talud forman zonas de enorme productividad biológica."]},"solucion":{}},{"slug":"oceanos-1.s1.p5","orden":5,"grupo":"oceanos-1.s1.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada elemento del Mar Argentino con su característica.","izquierda":[{"id":"a1","texto":"Plataforma continental"},{"id":"a2","texto":"Talud"},{"id":"a3","texto":"Corriente de Malvinas"},{"id":"a4","texto":"Corriente de Brasil"}],"derecha":[{"id":"b1","texto":"Fondo poco profundo que se aleja mucho de la costa"},{"id":"b2","texto":"Borde donde el fondo cae abruptamente"},{"id":"b3","texto":"Agua fría y rica en nutrientes del sur"},{"id":"b4","texto":"Agua cálida del norte"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Un mar con una geografía y unas corrientes que lo hacen muy productivo."}},{"slug":"oceanos-1.s1.p6","orden":6,"grupo":"oceanos-1.s1.p6","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El océano es en realidad un solo cuerpo de agua conectado, aunque tenga varios nombres.","razones":[{"id":"r1","texto":"Porque todos están conectados y el agua circula entre ellos"},{"id":"r2","texto":"Porque los océanos están separados por muros de tierra"},{"id":"r3","texto":"Porque cada océano tiene un agua distinta que no se mezcla"}]},"solucion":{"valor":true,"explicacion":"Todos los océanos están conectados y el agua circula entre ellos. Los nombres son divisiones útiles, no barreras.","clave":["r1"]}},{"slug":"oceanos-1.s1.p7","orden":7,"grupo":"oceanos-1.s1.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el encuentro de corrientes hace productivo al Mar Argentino.","items":[{"id":"i1","texto":"La corriente fría de Malvinas trae nutrientes"},{"id":"i2","texto":"Se encuentra con aguas cálidas y el borde del talud"},{"id":"i3","texto":"Los nutrientes suben a la superficie iluminada"},{"id":"i4","texto":"El fitoplancton crece en grandes cantidades"},{"id":"i5","texto":"Hay alimento para peces, aves y mamíferos marinos"},{"id":"i6","texto":"Las corrientes calientan el mar y matan el plancton"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Nutrientes más luz: la receta de la vida en el mar."}},{"slug":"oceanos-1.s1.p8","orden":8,"grupo":"oceanos-1.s1.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace especial al Mar Argentino? Marcá todo.","opciones":[{"id":"o1","texto":"Una plataforma continental muy ancha"},{"id":"o2","texto":"El encuentro de corrientes frías y cálidas"},{"id":"o3","texto":"Zonas de enorme productividad como el frente del talud"},{"id":"o4","texto":"Gran abundancia de aves y mamíferos marinos"},{"id":"o5","texto":"Que es el mar más profundo del mundo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"No es el más profundo: al contrario, gran parte es plataforma poco profunda, muy rica en vida."}},{"slug":"oceanos-1.s1.p9","orden":9,"grupo":"oceanos-1.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La superficie de la Tierra es de unos 510 millones de km². Si el océano cubre el 71 %, ¿cuántos millones de km² de océano hay? Redondeá al entero.","unidad":"millones de km²","decimales":0},"solucion":{"valor":362,"tolerancia":2,"explicacion":"510 × 71 ÷ 100 ≈ 362 millones de km². Más de cien veces la superficie de Argentina continental."}},{"slug":"oceanos-1.s1.p9.v2","orden":9,"grupo":"oceanos-1.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La superficie de la Tierra es de unos 510 millones de km². Si el océano cubre el 70 %, ¿cuántos millones de km² de océano hay? Redondeá al entero.","unidad":"millones de km²","decimales":0},"solucion":{"valor":357,"tolerancia":2,"explicacion":"510 × 70 ÷ 100 ≈ 357 millones de km². Más de cien veces la superficie de Argentina continental."}},{"slug":"oceanos-1.s1.p9.v3","orden":9,"grupo":"oceanos-1.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La superficie de la Tierra es de unos 510 millones de km². Si el océano cubre el 72 %, ¿cuántos millones de km² de océano hay? Redondeá al entero.","unidad":"millones de km²","decimales":0},"solucion":{"valor":367,"tolerancia":2,"explicacion":"510 × 72 ÷ 100 ≈ 367 millones de km². Más de cien veces la superficie de Argentina continental."}},{"slug":"oceanos-1.s1.p10","orden":10,"grupo":"oceanos-1.s1.p10","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La mayor parte del agua del planeta está en el océano.","razones":[{"id":"r1","texto":"Porque guarda cerca del 97 % del agua del planeta"},{"id":"r2","texto":"Porque la mayor parte del agua está en los ríos"},{"id":"r3","texto":"Porque la mayor parte está en las nubes"}]},"solucion":{"valor":true,"explicacion":"El océano guarda cerca del 97 % de toda el agua de la Tierra. El agua dulce es una parte chica, como viste en la rama de Agua.","clave":["r1"]}},{"slug":"oceanos-1.s1.p11","orden":11,"grupo":"oceanos-1.s1.p11","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá la profundidad promedio del océano.","min":10,"max":20000,"paso":1,"unidad":"metros","escala":"log"},"solucion":{"valor":3700,"banda":"log","explicacion":"Unos 3.700 metros: más de cincuenta veces la altura del Obelisco porteño."}},{"slug":"oceanos-1.s1.p12","orden":12,"grupo":"oceanos-1.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El océano cubre alrededor del 71 % de la superficie del planeta."},{"id":"s2","texto":"El océano tiene en promedio unos 100 metros de profundidad."},{"id":"s3","texto":"En el Mar Argentino se encuentran corrientes frías y cálidas."},{"id":"s4","texto":"La plataforma continental argentina es de las más angostas del mundo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer el mar empieza por dimensionarlo.","por_opcion":{"s2":"La profundidad promedio es de unos 3.700 metros.","s4":"Es una de las más anchas del mundo."}}},{"slug":"oceanos-1.s1.p13","orden":13,"grupo":"oceanos-1.s1.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El océano cubre cerca del {{0}} % del planeta; frente a Argentina hay una plataforma continental muy {{1}}; y allí se encuentran la corriente de Malvinas y la de {{2}}.","banco":[{"id":"w1","texto":"71"},{"id":"w2","texto":"ancha"},{"id":"w3","texto":"Brasil"},{"id":"w4","texto":"30"},{"id":"w5","texto":"angosta"},{"id":"w6","texto":"Humboldt"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos básicos del planeta azul y del Mar Argentino."}}]},{"slug":"oceanos-1.s2","orden":2,"tipo":"leccion","titulo_es":"El océano regula el clima","bajada_es":"Calor, CO₂ y corrientes: cómo el mar amortigua el cambio climático, y a qué costo.","minutos":11,"pasos":[{"slug":"oceanos-1.s2.p1","orden":1,"grupo":"oceanos-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una esponja de calor","cuerpo":["El agua necesita mucha energía para calentarse, y el océano es enorme. Por eso ha absorbido la gran mayoría del calor extra que atrapan los gases de efecto invernadero: según el IPCC, alrededor del 90 % del calentamiento acumulado del sistema climático en las últimas décadas se fue al océano.","Eso amortigua el calentamiento del aire, pero calienta el mar: sube el nivel del agua (el agua caliente ocupa más lugar), se blanquean los corales y cambian las zonas donde viven los peces."],"destacado":{"valor":"≈ 90 %","texto":"del calor extra acumulado por el cambio climático fue absorbido por el océano, según el IPCC."}},"solucion":{}},{"slug":"oceanos-1.s2.p2","orden":2,"grupo":"oceanos-1.s2.p2","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje del calor extra acumulado por el cambio climático absorbió el océano.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":90,"banda":"lineal","explicacion":"Alrededor del 90 %. Sin el océano, el aire se habría calentado muchísimo más."}},{"slug":"oceanos-1.s2.p3","orden":3,"grupo":"oceanos-1.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un sumidero de CO₂","cuerpo":["El océano también absorbe CO₂ del aire: alrededor de un cuarto de las emisiones de CO₂ de las actividades humanas cada año, según el Global Carbon Project. Parte se disuelve en el agua y parte la usa el fitoplancton en la fotosíntesis.","Ese servicio tiene un costo: el CO₂ disuelto vuelve el agua más ácida, lo que dificulta a corales, moluscos y algunos organismos del plancton formar sus caparazones. Es la acidificación del océano."]},"solucion":{}},{"slug":"oceanos-1.s2.p4","orden":4,"grupo":"oceanos-1.s2.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la acidificación del océano.","items":[{"id":"i1","texto":"Las personas emiten CO₂ al quemar combustibles fósiles"},{"id":"i2","texto":"El océano absorbe una parte"},{"id":"i3","texto":"El CO₂ disuelto forma ácido carbónico"},{"id":"i4","texto":"El agua se vuelve más ácida"},{"id":"i5","texto":"Les cuesta más a moluscos y corales formar sus caparazones"},{"id":"i6","texto":"El CO₂ se transforma en sal marina"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El mismo servicio que nos ayuda —absorber CO₂— daña la química del mar."}},{"slug":"oceanos-1.s2.p5","orden":5,"grupo":"oceanos-1.s2.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada efecto con su causa.","izquierda":[{"id":"a1","texto":"Suba del nivel del mar"},{"id":"a2","texto":"Acidificación"},{"id":"a3","texto":"Blanqueamiento de corales"},{"id":"a4","texto":"Peces que cambian de zona"}],"derecha":[{"id":"b1","texto":"El agua se expande al calentarse y se derriten hielos"},{"id":"b2","texto":"El océano absorbe CO₂"},{"id":"b3","texto":"El agua demasiado caliente estresa a los corales"},{"id":"b4","texto":"Buscan aguas con la temperatura que necesitan"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El océano amortigua el cambio climático, pero lo sufre."}},{"slug":"oceanos-1.s2.p6","orden":6,"grupo":"oceanos-1.s2.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el océano absorbe CO₂, emitir más no tiene consecuencias.","razones":[{"id":"r1","texto":"Porque absorbe solo una parte y se acidifica al hacerlo"},{"id":"r2","texto":"Porque el océano absorbe todo el CO₂ sin efectos"},{"id":"r3","texto":"Porque el CO₂ no llega nunca al mar"}]},"solucion":{"valor":false,"explicacion":"Absorbe solo una parte, y al hacerlo se acidifica y se calienta. El resto se acumula en la atmósfera.","clave":["r1"]}},{"slug":"oceanos-1.s2.p7","orden":7,"grupo":"oceanos-1.s2.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la humanidad emite unos 40 mil millones de toneladas de CO₂ por año y el océano absorbe alrededor de un cuarto, ¿cuántos miles de millones de toneladas absorbe?","unidad":"miles de millones de t","decimales":1},"solucion":{"valor":10,"tolerancia":0.2,"explicacion":"40 ÷ 4 = 10. Un servicio enorme que, a la vez, acidifica el agua."}},{"slug":"oceanos-1.s2.p7.v2","orden":7,"grupo":"oceanos-1.s2.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la humanidad emite unos 38 mil millones de toneladas de CO₂ por año y el océano absorbe alrededor de un cuarto, ¿cuántos miles de millones de toneladas absorbe?","unidad":"miles de millones de t","decimales":1},"solucion":{"valor":9.5,"tolerancia":0.19,"explicacion":"38 ÷ 4 = 9,5. Un servicio enorme que, a la vez, acidifica el agua."}},{"slug":"oceanos-1.s2.p7.v3","orden":7,"grupo":"oceanos-1.s2.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la humanidad emite unos 36 mil millones de toneladas de CO₂ por año y el océano absorbe alrededor de un cuarto, ¿cuántos miles de millones de toneladas absorbe?","unidad":"miles de millones de t","decimales":1},"solucion":{"valor":9,"tolerancia":0.18,"explicacion":"36 ÷ 4 = 9. Un servicio enorme que, a la vez, acidifica el agua."}},{"slug":"oceanos-1.s2.p8","orden":8,"grupo":"oceanos-1.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Corrientes que mueven el clima","cuerpo":["Las corrientes oceánicas llevan calor de los trópicos hacia los polos y agua fría de vuelta. Por eso algunas regiones tienen climas más templados o más fríos de lo que les correspondería por su latitud. Por ejemplo, la corriente fría de Malvinas contribuye a que la costa patagónica sea fresca incluso en verano."]},"solucion":{}},{"slug":"oceanos-1.s2.p9","orden":9,"grupo":"oceanos-1.s2.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esto es un servicio que el océano presta al clima o un efecto del cambio climático sobre el océano?","grupos":[{"id":"g1","nombre":"Servicio al clima"},{"id":"g2","nombre":"Efecto sobre el océano"}],"items":[{"id":"i1","texto":"Absorber calor"},{"id":"i2","texto":"Acidificación"},{"id":"i3","texto":"Absorber CO₂"},{"id":"i4","texto":"Suba del nivel del mar"},{"id":"i5","texto":"Llevar calor de los trópicos a los polos"},{"id":"i6","texto":"Olas de calor marinas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El océano da y recibe: amortigua el cambio climático y sufre sus consecuencias."}},{"slug":"oceanos-1.s2.p10","orden":10,"grupo":"oceanos-1.s2.p10","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué sube el nivel del mar con el calentamiento global?","opciones":[{"id":"o1","texto":"Por el agua que se expande y el hielo de tierra"},{"id":"o2","texto":"Porque llueve más sobre el océano que antes"},{"id":"o3","texto":"Porque se derrite el hielo que ya flota en el mar"},{"id":"o4","texto":"Porque los ríos traen más arena al mar"}]},"solucion":{"clave":["o1"],"explicacion":"Expansión térmica y hielo de tierra que se derrite: las dos causas principales.","por_opcion":{"o3":"El hielo que ya flota casi no sube el nivel al derretirse; lo que suma es el agua caliente y el hielo de tierra."}}},{"slug":"oceanos-1.s2.p11","orden":11,"grupo":"oceanos-1.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el nivel del mar sube unos 4 mm por año, ¿cuántos centímetros sube en 30 años, a ese ritmo constante?","unidad":"cm","decimales":1},"solucion":{"valor":12,"tolerancia":0.24,"explicacion":"4 × 30 = 120 mm, que son 12 cm. Y el ritmo se está acelerando, así que es una estimación baja."}},{"slug":"oceanos-1.s2.p11.v2","orden":11,"grupo":"oceanos-1.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el nivel del mar sube unos 3 mm por año, ¿cuántos centímetros sube en 20 años, a ese ritmo constante?","unidad":"cm","decimales":1},"solucion":{"valor":6,"tolerancia":0.12,"explicacion":"3 × 20 = 60 mm, que son 6 cm. Y el ritmo se está acelerando, así que es una estimación baja."}},{"slug":"oceanos-1.s2.p11.v3","orden":11,"grupo":"oceanos-1.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el nivel del mar sube unos 5 mm por año, ¿cuántos centímetros sube en 50 años, a ese ritmo constante?","unidad":"cm","decimales":1},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"5 × 50 = 250 mm, que son 25 cm. Y el ritmo se está acelerando, así que es una estimación baja."}},{"slug":"oceanos-1.s2.p12","orden":12,"grupo":"oceanos-1.s2.p12","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El hielo que ya flota en el mar, al derretirse, casi no sube el nivel del mar.","razones":[{"id":"r1","texto":"Porque ya desplazaba su peso en agua al flotar"},{"id":"r2","texto":"Porque el hielo flotante no se derrite nunca"},{"id":"r3","texto":"Porque el agua de deshielo se evapora al instante"}]},"solucion":{"valor":true,"explicacion":"El hielo flotante ya desplaza su peso en agua. Lo que sube el nivel es el hielo de tierra que se derrite y el agua que se expande al calentarse.","clave":["r1"]}},{"slug":"oceanos-1.s2.p13","orden":13,"grupo":"oceanos-1.s2.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El océano absorbió la mayor parte del calor extra del cambio climático."},{"id":"s2","texto":"El océano absorbe todo el CO₂ que emitimos."},{"id":"s3","texto":"La acidificación afecta a organismos con caparazón."},{"id":"s4","texto":"El hielo que ya flota en el mar es la causa principal de la suba del nivel del mar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El océano es aliado del clima, pero no tiene capacidad infinita.","por_opcion":{"s2":"Absorbe alrededor de un cuarto; el resto se acumula en el aire o lo absorben los ecosistemas terrestres.","s4":"Las causas principales son la expansión del agua caliente y el hielo de tierra que se derrite."}}},{"slug":"oceanos-1.s2.p14","orden":14,"grupo":"oceanos-1.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El océano absorbió cerca del {{0}} % del calor extra; absorbe alrededor de un {{1}} del CO₂ emitido; y por eso se {{2}}.","banco":[{"id":"w1","texto":"90"},{"id":"w2","texto":"cuarto"},{"id":"w3","texto":"acidifica"},{"id":"w4","texto":"10"},{"id":"w5","texto":"décimo"},{"id":"w6","texto":"endulza"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre el océano y el clima, resumidas en una línea."}}]},{"slug":"oceanos-1.s3","orden":3,"tipo":"leccion","titulo_es":"La vida en el mar","bajada_es":"Del plancton a las ballenas: la red de vida marina y la fauna del Mar Argentino.","minutos":11,"pasos":[{"slug":"oceanos-1.s3.p1","orden":1,"grupo":"oceanos-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo empieza por el plancton","cuerpo":["La base de casi toda la vida marina es el fitoplancton: algas microscópicas que hacen fotosíntesis cerca de la superficie. Lo comen pequeños animales del zooplancton, como el krill; a ellos, peces chicos; y después, peces grandes, aves, lobos marinos y ballenas.","Como viste en otras ramas, el fitoplancton además produce alrededor de la mitad del oxígeno del planeta."]},"solucion":{}},{"slug":"oceanos-1.s3.p2","orden":2,"grupo":"oceanos-1.s3.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená esta cadena alimentaria marina, de la base hacia arriba.","items":[{"id":"i1","texto":"Fitoplancton"},{"id":"i2","texto":"Zooplancton (krill)"},{"id":"i3","texto":"Anchoíta"},{"id":"i4","texto":"Merluza"},{"id":"i5","texto":"Lobo marino"}],"extremos":["Base","Arriba"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Energía del sol capturada por el plancton, que sube escalón por escalón."}},{"slug":"oceanos-1.s3.p3","orden":3,"grupo":"oceanos-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Fauna del Mar Argentino","cuerpo":["El Mar Argentino y su costa son hogar de pingüinos de Magallanes (con colonias enormes como la de Punta Tombo), lobos y elefantes marinos, delfines, orcas, albatros y petreles, y la ballena franca austral, que cada año llega a las aguas de Península Valdés para aparearse y tener sus crías.","La ballena franca austral fue declarada Monumento Natural Nacional en 1984."]},"solucion":{}},{"slug":"oceanos-1.s3.p4","orden":4,"grupo":"oceanos-1.s3.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada animal con un lugar o dato del Mar Argentino.","izquierda":[{"id":"a1","texto":"Ballena franca austral"},{"id":"a2","texto":"Pingüino de Magallanes"},{"id":"a3","texto":"Elefante marino"},{"id":"a4","texto":"Albatros"}],"derecha":[{"id":"b1","texto":"Llega a Península Valdés para tener sus crías"},{"id":"b2","texto":"Grandes colonias en la costa patagónica"},{"id":"b3","texto":"Colonias en Península Valdés"},{"id":"b4","texto":"Recorre enormes distancias sobre el mar abierto"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Un mar con una fauna que atrae a investigadores y visitantes de todo el mundo."}},{"slug":"oceanos-1.s3.p5","orden":5,"grupo":"oceanos-1.s3.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La ballena franca austral es Monumento Natural Nacional en Argentina.","razones":[{"id":"r1","texto":"Porque fue declarada Monumento Natural Nacional en 1984"},{"id":"r2","texto":"Porque las ballenas no llegan a Argentina"},{"id":"r3","texto":"Porque solo los árboles pueden ser monumentos naturales"}]},"solucion":{"valor":true,"explicacion":"Fue declarada así en 1984. Cada año llega a Península Valdés, donde se la puede observar desde la costa y en avistajes regulados.","clave":["r1"]}},{"slug":"oceanos-1.s3.p6","orden":6,"grupo":"oceanos-1.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Migraciones marinas","cuerpo":["Muchos animales del mar hacen grandes viajes. Los pingüinos de Magallanes, después de la temporada de cría en la Patagonia, migran hacia el norte, hasta el sur de Brasil, siguiendo a sus presas. Las ballenas francas viajan entre zonas de alimentación en aguas frías y zonas de cría más protegidas.","Por eso proteger solo una parte de su recorrido no alcanza: hace falta cooperación entre países y cuidar todo el camino."]},"solucion":{}},{"slug":"oceanos-1.s3.p7","orden":7,"grupo":"oceanos-1.s3.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué la pesca de anchoíta afecta a los pingüinos.","items":[{"id":"i1","texto":"Se pesca mucha anchoíta cerca de una colonia"},{"id":"i2","texto":"Los pingüinos encuentran menos alimento"},{"id":"i3","texto":"Tienen que nadar más lejos para comer"},{"id":"i4","texto":"Alimentan peor a sus pichones"},{"id":"i5","texto":"Sobreviven menos pichones"},{"id":"i6","texto":"Los pingüinos cambian a comer algas"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La red marina conecta la pesca con la vida de las aves. Pescar sin mirar la red afecta a todo."}},{"slug":"oceanos-1.s3.p8","orden":8,"grupo":"oceanos-1.s3.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es parte del plancton o no?","grupos":[{"id":"g1","nombre":"Plancton"},{"id":"g2","nombre":"No es plancton"}],"items":[{"id":"i1","texto":"Algas microscópicas"},{"id":"i2","texto":"Ballena franca"},{"id":"i3","texto":"Krill"},{"id":"i4","texto":"Pingüino"},{"id":"i5","texto":"Larvas de peces"},{"id":"i6","texto":"Merluza adulta"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El plancton son los organismos que flotan a la deriva, casi todos diminutos. Las ballenas, en cambio, comen plancton."}},{"slug":"oceanos-1.s3.p9","orden":9,"grupo":"oceanos-1.s3.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué animales viven en el Mar Argentino o en su costa? Marcá todos.","opciones":[{"id":"o1","texto":"Pingüino de Magallanes"},{"id":"o2","texto":"Lobo marino de un pelo"},{"id":"o3","texto":"Orca"},{"id":"o4","texto":"Ballena franca austral"},{"id":"o5","texto":"Oso polar"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El oso polar vive en el Ártico, en el hemisferio norte."}},{"slug":"oceanos-1.s3.p10","orden":10,"grupo":"oceanos-1.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una colonia tiene 200.000 nidos de pingüinos y cada nido es de una pareja, ¿cuántos pingüinos adultos hay?","unidad":"pingüinos","decimales":0},"solucion":{"valor":400000,"tolerancia":8000,"explicacion":"200.000 × 2 = 400.000 adultos, sin contar pichones. Las colonias patagónicas están entre las más grandes de esta especie."}},{"slug":"oceanos-1.s3.p10.v2","orden":10,"grupo":"oceanos-1.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una colonia tiene 150.000 nidos de pingüinos y cada nido es de una pareja, ¿cuántos pingüinos adultos hay?","unidad":"pingüinos","decimales":0},"solucion":{"valor":300000,"tolerancia":6000,"explicacion":"150.000 × 2 = 300.000 adultos, sin contar pichones. Las colonias patagónicas están entre las más grandes de esta especie."}},{"slug":"oceanos-1.s3.p10.v3","orden":10,"grupo":"oceanos-1.s3.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una colonia tiene 250.000 nidos de pingüinos y cada nido es de una pareja, ¿cuántos pingüinos adultos hay?","unidad":"pingüinos","decimales":0},"solucion":{"valor":500000,"tolerancia":10000,"explicacion":"250.000 × 2 = 500.000 adultos, sin contar pichones. Las colonias patagónicas están entre las más grandes de esta especie."}},{"slug":"oceanos-1.s3.p11","orden":11,"grupo":"oceanos-1.s3.p11","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos seres del Mar Argentino de más chico a más grande.","items":[{"id":"i1","texto":"Fitoplancton"},{"id":"i2","texto":"Krill"},{"id":"i3","texto":"Anchoíta"},{"id":"i4","texto":"Pingüino de Magallanes"},{"id":"i5","texto":"Ballena franca austral"}],"extremos":["Más chico","Más grande"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Lo curioso: la ballena franca se alimenta de los más chicos de la lista, filtrando zooplancton.","valores":{"i1":"microscópico","i2":"unos centímetros","i3":"unos 15 centímetros","i4":"unos 70 centímetros","i5":"más de 12 metros"}}},{"slug":"oceanos-1.s3.p12","orden":12,"grupo":"oceanos-1.s3.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la ballena franca austral llega cada año a Península Valdés?","opciones":[{"id":"o1","texto":"Para aparearse y tener sus crías en aguas protegidas"},{"id":"o2","texto":"Porque allí encuentra agua dulce para beber"},{"id":"o3","texto":"Porque la atraen los barcos turísticos"},{"id":"o4","texto":"Porque allí hiberna durante todo el verano"}]},"solucion":{"clave":["o1"],"explicacion":"Los golfos de Península Valdés ofrecen aguas tranquilas y protegidas para las crías.","por_opcion":{"o3":"Llega desde mucho antes de que existiera el turismo: busca golfos protegidos para criar."}}},{"slug":"oceanos-1.s3.p13","orden":13,"grupo":"oceanos-1.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta descripción y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El fitoplancton es la base de la red marina."},{"id":"s2","texto":"Las ballenas francas viven todo el año en el mismo lugar sin moverse."},{"id":"s3","texto":"Los pingüinos de Magallanes crían en la costa patagónica."},{"id":"s4","texto":"Pescar anchoíta no afecta a ningún otro animal."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La vida marina es una red: cada hilo sostiene a otros.","por_opcion":{"s2":"Migran entre zonas de alimentación y de cría.","s4":"La anchoíta es alimento de pingüinos, lobos marinos y peces grandes."}}},{"slug":"oceanos-1.s3.p14","orden":14,"grupo":"oceanos-1.s3.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La base de la red marina es el {{0}}; la ballena franca austral llega a Península {{1}}; y los pingüinos de Magallanes {{2}} hacia el norte en invierno.","banco":[{"id":"w1","texto":"fitoplancton"},{"id":"w2","texto":"Valdés"},{"id":"w3","texto":"migran"},{"id":"w4","texto":"petróleo"},{"id":"w5","texto":"Mitre"},{"id":"w6","texto":"hibernan"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos sobre la vida del Mar Argentino."}}]},{"slug":"oceanos-1.s4","orden":4,"tipo":"leccion","titulo_es":"Los grandes ríos","bajada_es":"La Cuenca del Plata, el Paraná, el sábalo y los peces migradores: los ríos como arterias del continente.","minutos":11,"pasos":[{"slug":"oceanos-1.s4.p1","orden":1,"grupo":"oceanos-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La Cuenca del Plata","cuerpo":["La Cuenca del Plata es la segunda más grande de América del Sur, después de la del Amazonas: reúne las aguas de los ríos Paraná, Paraguay, Uruguay y sus afluentes, en un territorio de unos 3 millones de km² que abarca parte de Argentina, Brasil, Paraguay, Bolivia y Uruguay. Desemboca en el Río de la Plata, uno de los estuarios más anchos del mundo.","En su recorrido hay selvas, humedales, ciudades, represas, puertos y algunas de las zonas agrícolas más productivas del mundo."],"destacado":{"valor":"≈ 3 millones km²","texto":"abarca la Cuenca del Plata, la segunda más grande de América del Sur."}},"solucion":{}},{"slug":"oceanos-1.s4.p2","orden":2,"grupo":"oceanos-1.s4.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué países comparten la Cuenca del Plata? Marcá todos.","opciones":[{"id":"o1","texto":"Argentina"},{"id":"o2","texto":"Brasil"},{"id":"o3","texto":"Paraguay"},{"id":"o4","texto":"Uruguay"},{"id":"o5","texto":"Chile"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"También Bolivia. Chile, en cambio, está del otro lado de la cordillera."}},{"slug":"oceanos-1.s4.p3","orden":3,"grupo":"oceanos-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Peces que viajan","cuerpo":["En el Paraná viven peces migradores, como el sábalo, el dorado, el surubí y el patí, que recorren cientos de kilómetros para reproducirse y alimentarse. El sábalo come el barro rico en materia orgánica del fondo (es un pez detritívoro) y es una de las especies más abundantes del río: es alimento de muchos otros peces, como el dorado, y de aves.","Por eso el sábalo es una especie clave de la red del Paraná. Su sobrepesca, por ejemplo para exportación, preocupa a científicos y pescadores."]},"solucion":{}},{"slug":"oceanos-1.s4.p4","orden":4,"grupo":"oceanos-1.s4.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué la sobrepesca de sábalo puede afectar al dorado.","items":[{"id":"i1","texto":"Se pesca mucho sábalo para exportar"},{"id":"i2","texto":"Baja la población de sábalo"},{"id":"i3","texto":"El dorado encuentra menos presas"},{"id":"i4","texto":"La población de dorado también baja"},{"id":"i5","texto":"El dorado empieza a comer barro en lugar de sábalo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El sábalo sostiene a buena parte de la red del río. Es una especie clave, como viste en la rama de Animales."}},{"slug":"oceanos-1.s4.p5","orden":5,"grupo":"oceanos-1.s4.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada pez del Paraná con su característica.","izquierda":[{"id":"a1","texto":"Sábalo"},{"id":"a2","texto":"Dorado"},{"id":"a3","texto":"Surubí"}],"derecha":[{"id":"b1","texto":"Come el barro orgánico del fondo y es muy abundante"},{"id":"b2","texto":"Gran depredador, muy buscado en la pesca deportiva"},{"id":"b3","texto":"Pez de cuero de gran tamaño"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Tres peces emblemáticos de uno de los grandes ríos del mundo."}},{"slug":"oceanos-1.s4.p6","orden":6,"grupo":"oceanos-1.s4.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las represas no afectan a los peces que migran por el río.","razones":[{"id":"r1","texto":"Porque pueden cortar las rutas migratorias"},{"id":"r2","texto":"Porque los peces saltan cualquier represa"},{"id":"r3","texto":"Porque los peces del Paraná no migran"}]},"solucion":{"valor":false,"explicacion":"Las represas pueden cortar las rutas migratorias. Algunas tienen escaleras o sistemas de transferencia de peces, pero no siempre funcionan bien.","clave":["r1"]}},{"slug":"oceanos-1.s4.p7","orden":7,"grupo":"oceanos-1.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los ríos patagónicos y de montaña","cuerpo":["Los ríos patagónicos, como el Negro, el Limay, el Chubut o el Santa Cruz, nacen en la cordillera y dependen de la nieve y los glaciares. Tienen aguas frías y claras, y en ellos se introdujeron truchas y salmones exóticos para la pesca deportiva, que compiten con peces nativos como la perca y el puyén."]},"solucion":{}},{"slug":"oceanos-1.s4.p8","orden":8,"grupo":"oceanos-1.s4.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un río de la Cuenca del Plata o un río patagónico?","grupos":[{"id":"g1","nombre":"Cuenca del Plata"},{"id":"g2","nombre":"Patagónico"}],"items":[{"id":"i1","texto":"Paraná"},{"id":"i2","texto":"Limay"},{"id":"i3","texto":"Uruguay"},{"id":"i4","texto":"Chubut"},{"id":"i5","texto":"Paraguay"},{"id":"i6","texto":"Santa Cruz"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Dos mundos fluviales: grandes ríos de llanura cálida y ríos fríos de montaña."}},{"slug":"oceanos-1.s4.p9","orden":9,"grupo":"oceanos-1.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sábalo migra 300 km río arriba a unos 15 km por día. ¿Cuántos días tarda?","unidad":"días","decimales":1},"solucion":{"valor":20,"tolerancia":0.4,"explicacion":"300 ÷ 15 = 20 días. Durante todo ese recorrido necesita que el río esté conectado y limpio."}},{"slug":"oceanos-1.s4.p9.v2","orden":9,"grupo":"oceanos-1.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sábalo migra 500 km río arriba a unos 20 km por día. ¿Cuántos días tarda?","unidad":"días","decimales":1},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"500 ÷ 20 = 25 días. Durante todo ese recorrido necesita que el río esté conectado y limpio."}},{"slug":"oceanos-1.s4.p9.v3","orden":9,"grupo":"oceanos-1.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sábalo migra 800 km río arriba a unos 25 km por día. ¿Cuántos días tarda?","unidad":"días","decimales":1},"solucion":{"valor":32,"tolerancia":0.64,"explicacion":"800 ÷ 25 = 32 días. Durante todo ese recorrido necesita que el río esté conectado y limpio."}},{"slug":"oceanos-1.s4.p10","orden":10,"grupo":"oceanos-1.s4.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el sábalo es una especie clave en el Paraná?","opciones":[{"id":"o1","texto":"Porque es muy abundante y alimenta a muchos"},{"id":"o2","texto":"Porque es el pez más grande de todo el río"},{"id":"o3","texto":"Porque es una especie exótica invasora en el río"},{"id":"o4","texto":"Porque ningún otro animal del río lo come"}]},"solucion":{"clave":["o1"],"explicacion":"Muchas especies dependen de él. Si baja, se resiente toda la red.","por_opcion":{"o3":"Es nativo del Paraná y es la base de buena parte de su red."}}},{"slug":"oceanos-1.s4.p11","orden":11,"grupo":"oceanos-1.s4.p11","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá la superficie de la Cuenca del Plata.","min":0.1,"max":20,"paso":0.1,"unidad":"millones de km²","escala":"lineal"},"solucion":{"valor":3,"banda":"lineal","explicacion":"Unos 3 millones de km²: más que toda la Argentina continental."}},{"slug":"oceanos-1.s4.p12","orden":12,"grupo":"oceanos-1.s4.p12","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estos ríos de norte a sur.","items":[{"id":"i1","texto":"Río Paraguay"},{"id":"i2","texto":"Río Paraná a la altura de Rosario"},{"id":"i3","texto":"Río Colorado"},{"id":"i4","texto":"Río Negro"},{"id":"i5","texto":"Río Santa Cruz"}],"extremos":["Norte","Sur"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Del subtrópico húmedo a la Patagonia austral: ríos muy distintos en un mismo país."}},{"slug":"oceanos-1.s4.p13","orden":13,"grupo":"oceanos-1.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La Cuenca del Plata es la segunda más grande de América del Sur."},{"id":"s2","texto":"El sábalo es un pez exótico traído de Europa."},{"id":"s3","texto":"El dorado se alimenta de otros peces, como el sábalo."},{"id":"s4","texto":"Las truchas son nativas de los ríos patagónicos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer los ríos es conocer su fauna nativa y lo que la amenaza.","por_opcion":{"s2":"Es un pez nativo, clave en la red del Paraná.","s4":"Fueron introducidas para la pesca deportiva."}}},{"slug":"oceanos-1.s4.p14","orden":14,"grupo":"oceanos-1.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La Cuenca del {{0}} es la segunda más grande de América del Sur; el {{1}} es clave en la red del Paraná; y las truchas de la Patagonia son {{2}}.","banco":[{"id":"w1","texto":"Plata"},{"id":"w2","texto":"sábalo"},{"id":"w3","texto":"exóticas"},{"id":"w4","texto":"Amazonas"},{"id":"w5","texto":"dorado"},{"id":"w6","texto":"nativas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre los grandes ríos argentinos."}}]},{"slug":"oceanos-1.s5","orden":5,"tipo":"leccion","titulo_es":"Costas y estuarios","bajada_es":"Donde el río se encuentra con el mar: el Río de la Plata, las marismas y las dunas.","minutos":11,"pasos":[{"slug":"oceanos-1.s5.p1","orden":1,"grupo":"oceanos-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ambientes de transición","cuerpo":["Las costas son zonas de transición entre la tierra y el mar. Un estuario es el lugar donde un río desemboca en el mar y el agua dulce se mezcla con la salada, como en el Río de la Plata. Las marismas son humedales costeros que se inundan con las mareas, y las dunas son acumulaciones de arena que el viento forma detrás de las playas.","Son ambientes muy productivos: muchos peces se crían en estuarios y marismas, y muchas aves migratorias se alimentan en ellos."]},"solucion":{}},{"slug":"oceanos-1.s5.p2","orden":2,"grupo":"oceanos-1.s5.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ambiente costero con su descripción.","izquierda":[{"id":"a1","texto":"Estuario"},{"id":"a2","texto":"Marisma"},{"id":"a3","texto":"Duna"},{"id":"a4","texto":"Playa"}],"derecha":[{"id":"b1","texto":"Donde el agua dulce del río se mezcla con la salada"},{"id":"b2","texto":"Humedal costero que se inunda con las mareas"},{"id":"b3","texto":"Acumulación de arena formada por el viento"},{"id":"b4","texto":"Franja de arena o canto rodado junto al mar"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro ambientes que forman un sistema costero conectado."}},{"slug":"oceanos-1.s5.p3","orden":3,"grupo":"oceanos-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El Río de la Plata y Samborombón","cuerpo":["El Río de la Plata es uno de los estuarios más anchos del mundo: en su desembocadura mide unos 200 kilómetros de costa a costa. En su orilla sur, la Bahía Samborombón es un enorme humedal de marismas y cangrejales, reconocido como sitio Ramsar de importancia internacional, donde se refugia el venado de las pampas y descansan aves migratorias."]},"solucion":{}},{"slug":"oceanos-1.s5.p4","orden":4,"grupo":"oceanos-1.s5.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La Bahía Samborombón es un humedal de importancia internacional reconocido por la Convención de Ramsar.","razones":[{"id":"r1","texto":"Porque fue reconocida como sitio Ramsar por su valor para aves y fauna"},{"id":"r2","texto":"Porque es una zona industrial del puerto"},{"id":"r3","texto":"Porque es un desierto sin agua"}]},"solucion":{"valor":true,"explicacion":"Es un sitio Ramsar: un humedal costero clave para aves migratorias y para el venado de las pampas.","clave":["r1"]}},{"slug":"oceanos-1.s5.p5","orden":5,"grupo":"oceanos-1.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dunas y erosión costera","cuerpo":["Las dunas protegen la costa: guardan arena que las tormentas mueven entre la playa y la duna, y frenan el viento y el mar. Cuando se construye sobre ellas, se las aplana o se planta vegetación que las fija de más, la playa pierde su reserva de arena y la erosión avanza.","En muchas localidades de la costa bonaerense, la urbanización sobre las dunas contribuyó a la pérdida de playas."]},"solucion":{}},{"slug":"oceanos-1.s5.p6","orden":6,"grupo":"oceanos-1.s5.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo construir sobre las dunas puede hacer perder la playa.","items":[{"id":"i1","texto":"Se construye sobre las dunas frente al mar"},{"id":"i2","texto":"Se pierde la reserva de arena de la costa"},{"id":"i3","texto":"Las tormentas se llevan arena que no se repone"},{"id":"i4","texto":"La playa se achica año tras año"},{"id":"i5","texto":"Las construcciones quedan expuestas al mar"},{"id":"i6","texto":"Las construcciones generan arena nueva"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Las dunas son un sistema de defensa natural. Destruirlas deja la costa expuesta."}},{"slug":"oceanos-1.s5.p7","orden":7,"grupo":"oceanos-1.s5.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción protege la costa o la daña?","grupos":[{"id":"g1","nombre":"La protege"},{"id":"g2","nombre":"La daña"}],"items":[{"id":"i1","texto":"Pasarelas elevadas para cruzar las dunas"},{"id":"i2","texto":"Aplanar dunas para hacer estacionamientos"},{"id":"i3","texto":"Conservar la vegetación nativa de las dunas"},{"id":"i4","texto":"Circular con vehículos sobre las dunas"},{"id":"i5","texto":"Construir lejos de la primera línea de dunas"},{"id":"i6","texto":"Extraer arena de la playa para construir"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Cuidar las dunas es, en definitiva, cuidar la playa y el pueblo."}},{"slug":"oceanos-1.s5.p8","orden":8,"grupo":"oceanos-1.s5.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué servicios prestan los ambientes costeros? Marcá todos.","opciones":[{"id":"o1","texto":"Criaderos de peces"},{"id":"o2","texto":"Alimento para aves migratorias"},{"id":"o3","texto":"Protección contra tormentas"},{"id":"o4","texto":"Filtrar el agua que llega al mar"},{"id":"o5","texto":"Producir petróleo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Estuarios, marismas y dunas trabajan gratis para la pesca, las aves y las personas."}},{"slug":"oceanos-1.s5.p9","orden":9,"grupo":"oceanos-1.s5.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un balneario, las tormentas se llevan la playa. ¿Qué medida atiende mejor la causa a largo plazo?","opciones":[{"id":"o1","texto":"Recuperar y proteger las dunas"},{"id":"o2","texto":"Construir más edificios en la primera línea"},{"id":"o3","texto":"Traer arena en camiones una vez"},{"id":"o4","texto":"Pavimentar la playa para que no se vuele"}]},"solucion":{"clave":["o1"],"explicacion":"Las soluciones basadas en la naturaleza, como recuperar dunas, atacan la causa y se mantienen solas.","por_opcion":{"o3":"Ayuda un tiempo, pero si no se recuperan las dunas, la erosión sigue."}}},{"slug":"oceanos-1.s5.p10","orden":10,"grupo":"oceanos-1.s5.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una playa pierde 2 metros de ancho por año por erosión. ¿Cuántos metros pierde en 10 años?","unidad":"metros","decimales":0},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"2 × 10 = 20 metros. Un ritmo que parece chico por año, pero que en una generación puede hacer desaparecer una playa."}},{"slug":"oceanos-1.s5.p10.v2","orden":10,"grupo":"oceanos-1.s5.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una playa pierde 1,5 metros de ancho por año por erosión. ¿Cuántos metros pierde en 20 años?","unidad":"metros","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"1,5 × 20 = 30 metros. Un ritmo que parece chico por año, pero que en una generación puede hacer desaparecer una playa."}},{"slug":"oceanos-1.s5.p10.v3","orden":10,"grupo":"oceanos-1.s5.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una playa pierde 3 metros de ancho por año por erosión. ¿Cuántos metros pierde en 15 años?","unidad":"metros","decimales":0},"solucion":{"valor":45,"tolerancia":0.9,"explicacion":"3 × 15 = 45 metros. Un ritmo que parece chico por año, pero que en una generación puede hacer desaparecer una playa."}},{"slug":"oceanos-1.s5.p11","orden":11,"grupo":"oceanos-1.s5.p11","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos kilómetros de ancho tiene el Río de la Plata en su desembocadura.","min":1,"max":1000,"paso":1,"unidad":"km","escala":"log"},"solucion":{"valor":200,"banda":"log","explicacion":"Unos 200 kilómetros: por eso, desde la orilla, parece un mar. Es uno de los estuarios más anchos del mundo."}},{"slug":"oceanos-1.s5.p12","orden":12,"grupo":"oceanos-1.s5.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los estuarios son ambientes pobres en vida porque mezclan agua dulce y salada.","razones":[{"id":"r1","texto":"Porque reciben nutrientes y son criaderos de peces"},{"id":"r2","texto":"Porque el agua mezclada no permite la vida"},{"id":"r3","texto":"Porque en los estuarios no hay luz"}]},"solucion":{"valor":false,"explicacion":"Son de los ambientes más productivos: reciben nutrientes de los ríos y del mar, y muchos peces se crían en ellos.","clave":["r1"]}},{"slug":"oceanos-1.s5.p13","orden":13,"grupo":"oceanos-1.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este proyecto municipal y marcá lo que daña la costa.","segmentos":[{"id":"s1","texto":"Pondremos pasarelas elevadas para cruzar las dunas."},{"id":"s2","texto":"Aplanaremos las dunas para ampliar el estacionamiento."},{"id":"s3","texto":"Protegeremos la vegetación nativa costera."},{"id":"s4","texto":"Permitiremos circular con cuatriciclos sobre las dunas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La costa es un sistema frágil. Cuidarlo es cuidar la playa y los pueblos costeros.","por_opcion":{"s2":"Sin dunas, la playa pierde su reserva de arena y se erosiona.","s4":"Destruyen la vegetación y desestabilizan las dunas."}}},{"slug":"oceanos-1.s5.p14","orden":14,"grupo":"oceanos-1.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Donde un río se mezcla con el mar hay un {{0}}; las {{1}} protegen la costa; y la Bahía Samborombón es un sitio {{2}}.","banco":[{"id":"w1","texto":"estuario"},{"id":"w2","texto":"dunas"},{"id":"w3","texto":"Ramsar"},{"id":"w4","texto":"delta"},{"id":"w5","texto":"rocas"},{"id":"w6","texto":"industrial"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre las costas y sus ambientes de transición."}}]},{"slug":"oceanos-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: el planeta azul","bajada_es":"Océano, clima, vida marina, ríos y costas, mezclados.","minutos":8,"pasos":[{"slug":"oceanos-1.s6.p1","orden":1,"grupo":"oceanos-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «El planeta azul». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"oceanos-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la colonia y la costa","bajada_es":"Un pueblo patagónico quiere promover el turismo cerca de una colonia de pingüinos. Evaluá el plan con lo que aprendiste.","minutos":10,"pasos":[{"slug":"oceanos-1.s7.p1","orden":1,"grupo":"oceanos-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El plan","cuerpo":["Un pueblo de la costa patagónica tiene cerca una colonia de pingüinos de Magallanes con unas 50.000 parejas. El municipio quiere más turismo: propone un camino de ripio hasta la colonia, un estacionamiento sobre las dunas, paseos en cuatriciclo por la playa y permitir a los visitantes acercarse a los nidos para sacar fotos.","Frente a la costa, barcos pesqueros capturan anchoíta, el principal alimento de los pingüinos en la zona."]},"solucion":{}},{"slug":"oceanos-1.s7.p2","orden":2,"grupo":"oceanos-1.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos pingüinos adultos hay en la colonia, si cada pareja son dos?","unidad":"pingüinos","decimales":0,"contexto":"50.000 parejas de pingüinos de Magallanes."},"solucion":{"valor":100000,"tolerancia":2000,"explicacion":"50.000 × 2 = 100.000 pingüinos adultos, sin contar pichones: una colonia muy grande y sensible."}},{"slug":"oceanos-1.s7.p3","orden":3,"grupo":"oceanos-1.s7.p3","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué partes del plan pueden dañar la colonia o la costa? Marcá todas.","opciones":[{"id":"o1","texto":"Estacionamiento sobre las dunas"},{"id":"o2","texto":"Cuatriciclos en la playa"},{"id":"o3","texto":"Acercarse a los nidos para las fotos"},{"id":"o4","texto":"La pesca intensa de anchoíta cerca de la colonia"},{"id":"o5","texto":"Un centro de visitantes lejos de las dunas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Casi todo el plan original daña. Un centro de visitantes bien ubicado, en cambio, puede educar y ordenar el turismo."}},{"slug":"oceanos-1.s7.p4","orden":4,"grupo":"oceanos-1.s7.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es una alternativa mejor para visitar la colonia?","opciones":[{"id":"o1","texto":"Senderos marcados y pasarelas a distancia de los nidos"},{"id":"o2","texto":"Dejar que cada visitante camine libremente entre los nidos"},{"id":"o3","texto":"Prohibir para siempre cualquier visita"},{"id":"o4","texto":"Llevar a los pingüinos a un recinto cerca del pueblo"}]},"solucion":{"clave":["o1"],"explicacion":"El turismo ordenado protege a la colonia y permite que la gente la conozca.","por_opcion":{"o3":"Puede ser necesario en algunos lugares, pero el turismo ordenado también genera conciencia y recursos."}}},{"slug":"oceanos-1.s7.p5","orden":5,"grupo":"oceanos-1.s7.p5","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el plan original podría afectar la colonia.","items":[{"id":"i1","texto":"Aumentan los visitantes y los cuatriciclos"},{"id":"i2","texto":"Se pisan nidos y se asusta a los adultos"},{"id":"i3","texto":"Algunos pingüinos abandonan sus nidos"},{"id":"i4","texto":"Mueren huevos y pichones"},{"id":"i5","texto":"La colonia se reduce con los años"},{"id":"i6","texto":"Los pingüinos se acostumbran y crían más"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El disturbio humano en la época de cría es una de las amenazas para las colonias."}},{"slug":"oceanos-1.s7.p6","orden":6,"grupo":"oceanos-1.s7.p6","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas medidas por prioridad, de la primera a la última.","items":[{"id":"i1","texto":"Impedir el acceso a los nidos y a las dunas"},{"id":"i2","texto":"Senderos y pasarelas a distancia"},{"id":"i3","texto":"Acordar zonas sin pesca de anchoíta cerca de la colonia"},{"id":"i4","texto":"Centro de visitantes y guías del pueblo"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero evitar el daño; después ordenar, proteger el alimento y aprovechar el turismo con cuidado.","valores":{"i1":"evita daños inmediatos","i2":"ordena el turismo","i3":"protege el alimento","i4":"educa y genera trabajo"}}},{"slug":"oceanos-1.s7.p7","orden":7,"grupo":"oceanos-1.s7.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá los argumentos que se escuchan en el pueblo.","grupos":[{"id":"g1","nombre":"Con fundamento"},{"id":"g2","nombre":"Sin fundamento"}],"items":[{"id":"i1","texto":"Sin anchoíta, los pingüinos no pueden alimentar a sus pichones"},{"id":"i2","texto":"Los pingüinos no sienten a las personas"},{"id":"i3","texto":"Las dunas protegen la playa de las tormentas"},{"id":"i4","texto":"Las dunas son solo arena inútil"},{"id":"i5","texto":"El turismo ordenado puede generar trabajo sin dañar la colonia"},{"id":"i6","texto":"Con 100.000 pingüinos, perder algunos nidos no importa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Decidir con datos y con la red de vida en mente."}},{"slug":"oceanos-1.s7.p8","orden":8,"grupo":"oceanos-1.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El municipio reescribe su plan. Marcá lo que todavía no conviene.","segmentos":[{"id":"s1","texto":"Senderos marcados y pasarelas a distancia de los nidos."},{"id":"s2","texto":"El estacionamiento se hará igual sobre las dunas, porque es más barato."},{"id":"s3","texto":"Guías del pueblo acompañarán las visitas."},{"id":"s4","texto":"Los cuatriciclos podrán circular por la playa fuera de la temporada de cría."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan protege la colonia, la costa y el alimento, y aprovecha el turismo con reglas claras.","por_opcion":{"s2":"Destruir dunas pone en riesgo la playa y el ambiente costero.","s4":"Igual dañan dunas y vegetación, y la playa es usada por otras especies."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"oceanos-2","rama":"agua_azul","orden":2,"nivel":1,"titulo_es":"Pesca y alimentos del agua","bajada_es":"Los peces se renuevan, pero no a cualquier ritmo. Cuánto se puede pescar, qué se pesca sin querer, qué reglas ordenan el mar y cómo elegir qué comer.","objetivos_es":["Distinguir la pesca de captura de la acuicultura y conocer las pesquerías argentinas","Explicar la sobrepesca y el rendimiento máximo sostenible","Reconocer la captura incidental y las formas de reducirla","Describir las reglas que ordenan la pesca y el problema de la pesca ilegal","Aplicar criterios para elegir pescados y mariscos"],"repasa":["oceanos-1","tronco-1","comunidad-1"],"requiere_tronco":1,"fuentes":["fao-pesca-sofia","inidep","milla-201","pampa-azul","vida-silvestre"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"oceanos-2.s1","orden":1,"tipo":"leccion","titulo_es":"Del mar al plato","bajada_es":"Pesca de captura y acuicultura, las pesquerías argentinas y cuánto pescado comemos.","minutos":11,"pasos":[{"slug":"oceanos-2.s1.p1","orden":1,"grupo":"oceanos-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dos formas de producir","cuerpo":["Los alimentos del agua se obtienen de dos formas: la pesca de captura, que saca peces, crustáceos y moluscos silvestres del mar, los ríos y los lagos; y la acuicultura, que los cría en estanques, jaulas o piletas.","Según la FAO, en 2022 la acuicultura superó por primera vez a la pesca de captura en la producción mundial de animales acuáticos. Cada persona del mundo consume en promedio más de 20 kg de alimentos acuáticos por año."],"destacado":{"valor":"> 20 kg","texto":"de alimentos acuáticos por persona por año se consumen en promedio en el mundo, según la FAO."}},"solucion":{}},{"slug":"oceanos-2.s1.p2","orden":2,"grupo":"oceanos-2.s1.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es pesca de captura o acuicultura?","grupos":[{"id":"g1","nombre":"Pesca de captura"},{"id":"g2","nombre":"Acuicultura"}],"items":[{"id":"i1","texto":"Un barco que pesca merluza en el Mar Argentino"},{"id":"i2","texto":"Truchas criadas en jaulas en un embalse patagónico"},{"id":"i3","texto":"Un pescador artesanal de sábalo en el Paraná"},{"id":"i4","texto":"Pacú criado en estanques en el noreste"},{"id":"i5","texto":"La pesca de calamar con luces de noche"},{"id":"i6","texto":"Mejillones cultivados en cuerdas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Dos sistemas con impactos distintos que conviene conocer."}},{"slug":"oceanos-2.s1.p3","orden":3,"grupo":"oceanos-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las pesquerías argentinas","cuerpo":["Argentina tiene una de las industrias pesqueras más importantes de América Latina. Las especies principales son el langostino patagónico, la merluza común (merluza hubbsi) y el calamar. La mayor parte de lo que se pesca se exporta.","Mientras tanto, en Argentina se come mucho menos pescado que el promedio mundial. El INIDEP, el instituto nacional de investigación pesquera, estudia las poblaciones para recomendar cuánto se puede pescar."]},"solucion":{}},{"slug":"oceanos-2.s1.p4","orden":4,"grupo":"oceanos-2.s1.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada especie con una característica de su pesquería.","izquierda":[{"id":"a1","texto":"Langostino patagónico"},{"id":"a2","texto":"Merluza común"},{"id":"a3","texto":"Calamar"},{"id":"a4","texto":"Sábalo"}],"derecha":[{"id":"b1","texto":"Una de las principales exportaciones pesqueras"},{"id":"b2","texto":"Pez blanco clave del Mar Argentino"},{"id":"b3","texto":"Se pesca de noche atrayéndolo con luces"},{"id":"b4","texto":"Pesca en el río Paraná"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Las pesquerías argentinas son muy diversas: del mar abierto al río."}},{"slug":"oceanos-2.s1.p5","orden":5,"grupo":"oceanos-2.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La mayor parte del pescado que se captura en Argentina se consume dentro del país.","razones":[{"id":"r1","texto":"Porque la mayor parte de la captura se exporta"},{"id":"r2","texto":"Porque en Argentina no se pesca"},{"id":"r3","texto":"Porque el pescado argentino no se puede exportar"}]},"solucion":{"valor":false,"explicacion":"La mayor parte se exporta. En Argentina se consume mucho menos pescado por persona que el promedio mundial.","clave":["r1"]}},{"slug":"oceanos-2.s1.p6","orden":6,"grupo":"oceanos-2.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en el mundo se consumen unos 20,7 kg de alimentos acuáticos por persona por año y en un país 6 kg, ¿cuántas veces más se consume en el promedio mundial? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3.5,"tolerancia":0.1,"explicacion":"20,7 ÷ 6 ≈ 3,5 veces. Un país con mucho mar puede comer muy poco pescado."}},{"slug":"oceanos-2.s1.p6.v2","orden":6,"grupo":"oceanos-2.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en el mundo se consumen unos 20,7 kg de alimentos acuáticos por persona por año y en un país 5 kg, ¿cuántas veces más se consume en el promedio mundial? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":4.1,"tolerancia":0.1,"explicacion":"20,7 ÷ 5 ≈ 4,1 veces. Un país con mucho mar puede comer muy poco pescado."}},{"slug":"oceanos-2.s1.p6.v3","orden":6,"grupo":"oceanos-2.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en el mundo se consumen unos 20,7 kg de alimentos acuáticos por persona por año y en un país 7 kg, ¿cuántas veces más se consume en el promedio mundial? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3,"tolerancia":0.1,"explicacion":"20,7 ÷ 7 ≈ 3 veces. Un país con mucho mar puede comer muy poco pescado."}},{"slug":"oceanos-2.s1.p7","orden":7,"grupo":"oceanos-2.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La acuicultura: ventajas y problemas","cuerpo":["La acuicultura puede producir alimento con menos presión sobre las poblaciones silvestres. Pero también tiene problemas: algunos peces criados comen harina de pescado hecha con peces silvestres; los desechos de las jaulas pueden contaminar el agua; y los peces que escapan pueden volverse invasores.","Los moluscos que filtran el agua, como mejillones y ostras, no necesitan alimento agregado y suelen tener bajo impacto."]},"solucion":{}},{"slug":"oceanos-2.s1.p8","orden":8,"grupo":"oceanos-2.s1.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué problemas puede tener la acuicultura mal manejada? Marcá todos.","opciones":[{"id":"o1","texto":"Contaminación del agua por desechos"},{"id":"o2","texto":"Escapes de especies exóticas"},{"id":"o3","texto":"Uso de harina hecha con peces silvestres"},{"id":"o4","texto":"Enfermedades que pasan a peces silvestres"},{"id":"o5","texto":"Que los peces criados no se pueden comer"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Bien manejada puede ser una gran aliada; mal manejada, traslada los problemas."}},{"slug":"oceanos-2.s1.p9","orden":9,"grupo":"oceanos-2.s1.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué algunos peces de criadero dependen de peces silvestres.","items":[{"id":"i1","texto":"Se crían peces carnívoros, como el salmón"},{"id":"i2","texto":"Necesitan alimento con proteína de pescado"},{"id":"i3","texto":"Se fabrica harina con peces silvestres chicos"},{"id":"i4","texto":"Se pescan más peces chicos en el mar"},{"id":"i5","texto":"Los peces de criadero se alimentan solos de algas"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"No toda acuicultura alivia la presión sobre el mar. Depende de qué se cría y cómo se alimenta."}},{"slug":"oceanos-2.s1.p10","orden":10,"grupo":"oceanos-2.s1.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál de estas producciones acuícolas suele tener menor impacto?","opciones":[{"id":"o1","texto":"Cultivo de mejillones en cuerdas"},{"id":"o2","texto":"Jaulas de salmón alimentado con harina de pescado"},{"id":"o3","texto":"Estanques de camarones en manglares talados"},{"id":"o4","texto":"Truchas en un lago con alimento en exceso"}]},"solucion":{"clave":["o1"],"explicacion":"Los mejillones filtran el agua y no necesitan alimento agregado.","por_opcion":{"o3":"Talar manglares para estanques es uno de los impactos más graves de la acuicultura."}}},{"slug":"oceanos-2.s1.p11","orden":11,"grupo":"oceanos-2.s1.p11","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué institución estudia las poblaciones de peces del Mar Argentino y recomienda cuánto se puede pescar?","opciones":[{"id":"o1","texto":"El INIDEP"},{"id":"o2","texto":"La Dirección Nacional de Vialidad"},{"id":"o3","texto":"El Banco Central"},{"id":"o4","texto":"El Servicio Meteorológico"}]},"solucion":{"clave":["o1"],"explicacion":"El Instituto Nacional de Investigación y Desarrollo Pesquero aporta la base científica para las decisiones de pesca.","por_opcion":{"o3":"No es su función: la investigación pesquera la hace el INIDEP."}}},{"slug":"oceanos-2.s1.p12","orden":12,"grupo":"oceanos-2.s1.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En 2022, la acuicultura superó por primera vez a la pesca de captura en la producción mundial de animales acuáticos.","razones":[{"id":"r1","texto":"Porque así lo informó la FAO para 2022"},{"id":"r2","texto":"Porque la acuicultura no existe en el mundo"},{"id":"r3","texto":"Porque la pesca de captura es siempre mayor"}]},"solucion":{"valor":true,"explicacion":"Así lo informó la FAO. Es un cambio histórico en cómo se producen los alimentos del agua.","clave":["r1"]}},{"slug":"oceanos-2.s1.p13","orden":13,"grupo":"oceanos-2.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La acuicultura ya produce más animales acuáticos que la pesca de captura."},{"id":"s2","texto":"Toda la acuicultura alivia la presión sobre los peces silvestres."},{"id":"s3","texto":"El langostino es una de las principales exportaciones pesqueras argentinas."},{"id":"s4","texto":"En Argentina se come más pescado que el promedio mundial."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer de dónde viene el pescado es el primer paso para elegir bien.","por_opcion":{"s2":"Algunos peces de criadero comen harina de peces silvestres.","s4":"Se come bastante menos que el promedio mundial."}}},{"slug":"oceanos-2.s1.p14","orden":14,"grupo":"oceanos-2.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Criar peces o mariscos se llama {{0}}; las principales pesquerías del Mar Argentino son el langostino, la {{1}} y el {{2}}.","banco":[{"id":"w1","texto":"acuicultura"},{"id":"w2","texto":"merluza"},{"id":"w3","texto":"calamar"},{"id":"w4","texto":"agricultura"},{"id":"w5","texto":"trucha"},{"id":"w6","texto":"atún"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las dos formas de producir y las pesquerías principales."}}]},{"slug":"oceanos-2.s2","orden":2,"tipo":"leccion","titulo_es":"Cuánto se puede pescar","bajada_es":"Rendimiento máximo sostenible, sobrepesca y el caso de la merluza argentina.","minutos":11,"pasos":[{"slug":"oceanos-2.s2.p1","orden":1,"grupo":"oceanos-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un recurso renovable, con límites","cuerpo":["Los peces se reproducen, así que son un recurso renovable. Pero, como viste en el tronco, lo renovable se agota si se usa más rápido de lo que se repone. Si se pescan muchos adultos, quedan pocos para reproducirse, y la población baja.","El rendimiento máximo sostenible es la mayor cantidad que se puede pescar año tras año sin que la población disminuya. Pescar por encima de ese límite es sobrepesca."]},"solucion":{}},{"slug":"oceanos-2.s2.p2","orden":2,"grupo":"oceanos-2.s2.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la sobrepesca.","items":[{"id":"i1","texto":"Se pesca más de lo que la población repone"},{"id":"i2","texto":"Quedan menos adultos para reproducirse"},{"id":"i3","texto":"Nacen menos peces"},{"id":"i4","texto":"La población baja año tras año"},{"id":"i5","texto":"Las capturas caen y la pesquería puede colapsar"},{"id":"i6","texto":"Cuantos más se pescan, más se reproducen"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La tragedia de los comunes en el mar: ganar hoy a costa de perder mañana."}},{"slug":"oceanos-2.s2.p3","orden":3,"grupo":"oceanos-2.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación mundial","cuerpo":["Según la FAO, en 2021 alrededor del 38 % de las poblaciones de peces del mundo evaluadas estaban sobreexplotadas, y alrededor del 62 % se pescaba dentro de límites biológicamente sostenibles. La proporción de poblaciones sobreexplotadas creció durante décadas.","Las pesquerías bien gestionadas, con ciencia y controles, muestran que es posible recuperar poblaciones."],"datos":{"tipo":"barras","titulo":"Poblaciones de peces del mundo evaluadas por la FAO (2021)","unidad":"%","filas":[{"etiqueta":"Dentro de límites sostenibles","valor":62},{"etiqueta":"Sobreexplotadas","valor":38}],"nota":"FAO, El estado mundial de la pesca y la acuicultura 2024."}},"solucion":{}},{"slug":"oceanos-2.s2.p4","orden":4,"grupo":"oceanos-2.s2.p4","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las poblaciones de peces evaluadas por la FAO estaban sobreexplotadas en 2021.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":38,"banda":"lineal","explicacion":"Alrededor del 38 %. Más de un tercio de las poblaciones se pesca por encima de lo que pueden reponer."}},{"slug":"oceanos-2.s2.p5","orden":5,"grupo":"oceanos-2.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso de la merluza argentina","cuerpo":["A fines de la década de 1990, la merluza común del Mar Argentino sufrió una fuerte sobrepesca: se capturaba mucho más de lo recomendado por los científicos y la población de adultos cayó mucho. Se declaró la emergencia pesquera y se tomaron medidas: cierre de zonas de cría, límites de captura y, más adelante, cuotas por empresa.","Con el tiempo, la población mostró señales de recuperación. El caso muestra que la ciencia y las reglas pueden revertir la sobrepesca, aunque cuesta y requiere controles."]},"solucion":{}},{"slug":"oceanos-2.s2.p6","orden":6,"grupo":"oceanos-2.s2.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená lo que pasó con la merluza argentina.","items":[{"id":"i1","texto":"Se pesca muy por encima de lo recomendado"},{"id":"i2","texto":"La población de adultos cae fuertemente"},{"id":"i3","texto":"Se declara la emergencia pesquera"},{"id":"i4","texto":"Se cierran zonas de cría y se fijan límites"},{"id":"i5","texto":"La población muestra señales de recuperación"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un ciclo de crisis y recuperación que deja lecciones para otras pesquerías."}},{"slug":"oceanos-2.s2.p7","orden":7,"grupo":"oceanos-2.s2.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población de peces de 1.000 mil toneladas crece un 10 % por año si no se pesca. Si se pescan 150 mil toneladas por año, ¿cuántas mil toneladas quedan después de un año?","unidad":"mil toneladas","decimales":0},"solucion":{"valor":950,"tolerancia":19,"explicacion":"Crece 100 y se pescan 150: 1.000 + 100 − 150 = 950. Se pesca más de lo que crece: la población baja."}},{"slug":"oceanos-2.s2.p7.v2","orden":7,"grupo":"oceanos-2.s2.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población de peces de 500 mil toneladas crece un 20 % por año si no se pesca. Si se pescan 80 mil toneladas por año, ¿cuántas mil toneladas quedan después de un año?","unidad":"mil toneladas","decimales":0},"solucion":{"valor":520,"tolerancia":10.4,"explicacion":"Crece 100 y se pescan 80: 500 + 100 − 80 = 520. Se pesca menos de lo que crece: la población se mantiene o sube."}},{"slug":"oceanos-2.s2.p7.v3","orden":7,"grupo":"oceanos-2.s2.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una población de peces de 2.000 mil toneladas crece un 15 % por año si no se pesca. Si se pescan 250 mil toneladas por año, ¿cuántas mil toneladas quedan después de un año?","unidad":"mil toneladas","decimales":0},"solucion":{"valor":2050,"tolerancia":41,"explicacion":"Crece 300 y se pescan 250: 2.000 + 300 − 250 = 2.050. Se pesca menos de lo que crece: la población se mantiene o sube."}},{"slug":"oceanos-2.s2.p8","orden":8,"grupo":"oceanos-2.s2.p8","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un recurso es renovable, se puede pescar la cantidad que se quiera.","razones":[{"id":"r1","texto":"Porque se renueva a un ritmo que no se puede superar"},{"id":"r2","texto":"Porque los peces no se reproducen"},{"id":"r3","texto":"Porque los recursos renovables son infinitos"}]},"solucion":{"valor":false,"explicacion":"Se renueva a un ritmo. Si se pesca más rápido de lo que se repone, la población baja y puede colapsar.","clave":["r1"]}},{"slug":"oceanos-2.s2.p9","orden":9,"grupo":"oceanos-2.s2.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Rendimiento máximo sostenible"},{"id":"a2","texto":"Sobrepesca"},{"id":"a3","texto":"Población sobreexplotada"},{"id":"a4","texto":"Recuperación"}],"derecha":[{"id":"b1","texto":"Lo máximo que se puede pescar sin que la población baje"},{"id":"b2","texto":"Pescar más de lo que la población repone"},{"id":"b3","texto":"Población reducida por pescar de más"},{"id":"b4","texto":"La población vuelve a crecer al bajar la presión"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro conceptos para leer cualquier noticia sobre pesca."}},{"slug":"oceanos-2.s2.p10","orden":10,"grupo":"oceanos-2.s2.p10","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta situación indica sobrepesca o una pesquería sana?","grupos":[{"id":"g1","nombre":"Posible sobrepesca"},{"id":"g2","nombre":"Pesquería sana"}],"items":[{"id":"i1","texto":"Cada año se pescan peces más chicos"},{"id":"i2","texto":"Las capturas se mantienen con el mismo esfuerzo"},{"id":"i3","texto":"Hay que ir más lejos para capturar lo mismo"},{"id":"i4","texto":"Hay peces de todas las tallas"},{"id":"i5","texto":"Las capturas caen aunque se pesque más tiempo"},{"id":"i6","texto":"La población se mantiene según los estudios científicos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las señales de sobrepesca aparecen antes del colapso: saber leerlas permite actuar a tiempo."}},{"slug":"oceanos-2.s2.p11","orden":11,"grupo":"oceanos-2.s2.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas se tomaron frente a la crisis de la merluza argentina? Marcá todas.","opciones":[{"id":"o1","texto":"Cierre de zonas de cría"},{"id":"o2","texto":"Límites de captura"},{"id":"o3","texto":"Cuotas por empresa"},{"id":"o4","texto":"Duplicar la flota pesquera"},{"id":"o5","texto":"Eliminar los controles en los puertos"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Reglas basadas en la ciencia, y controles para que se cumplan."}},{"slug":"oceanos-2.s2.p12","orden":12,"grupo":"oceanos-2.s2.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una pesquería, cada año los peces capturados son más chicos. ¿Qué puede indicar?","opciones":[{"id":"o1","texto":"Una posible sobrepesca"},{"id":"o2","texto":"Que los peces se alimentan mejor"},{"id":"o3","texto":"Que el agua está más limpia"},{"id":"o4","texto":"Que las redes son nuevas"}]},"solucion":{"clave":["o1"],"explicacion":"Si se pescan los adultos más rápido de lo que crecen, quedan peces cada vez más jóvenes y chicos.","por_opcion":{"o3":"El tamaño de captura no depende de eso: cuando faltan adultos grandes, suele haber sobrepesca."}}},{"slug":"oceanos-2.s2.p13","orden":13,"grupo":"oceanos-2.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los peces son un recurso renovable."},{"id":"s2","texto":"Por eso nunca se pueden agotar."},{"id":"s3","texto":"La merluza argentina sufrió sobrepesca a fines de los noventa."},{"id":"s4","texto":"Una población sobreexplotada nunca puede recuperarse."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La sobrepesca tiene solución, pero requiere ciencia, reglas y controles.","por_opcion":{"s2":"Se agotan si se pescan más rápido de lo que se reponen.","s4":"Con reglas y controles, muchas poblaciones se recuperan."}}},{"slug":"oceanos-2.s2.p14","orden":14,"grupo":"oceanos-2.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Pescar más de lo que la población repone es {{0}}; lo máximo que se puede pescar sin que baje es el rendimiento máximo {{1}}.","banco":[{"id":"w1","texto":"sobrepesca"},{"id":"w2","texto":"sostenible"},{"id":"w3","texto":"acuicultura"},{"id":"w4","texto":"infinito"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Los dos conceptos centrales de la gestión pesquera."}}]},{"slug":"oceanos-2.s3","orden":3,"tipo":"leccion","titulo_es":"Lo que se pesca sin querer","bajada_es":"Captura incidental y descarte: aves, tortugas, delfines y peces juveniles, y cómo evitarlos.","minutos":11,"pasos":[{"slug":"oceanos-2.s3.p1","orden":1,"grupo":"oceanos-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Captura incidental","cuerpo":["La captura incidental es todo lo que queda atrapado en las redes o anzuelos sin ser la especie buscada: peces de otras especies, peces juveniles, tortugas marinas, delfines, lobos marinos, tiburones y aves. Muchas veces se tira de vuelta al mar muerta o moribunda: eso se llama descarte.","En algunas pesquerías de arrastre, como la de langostino, el descarte de juveniles de merluza fue un problema importante estudiado en Argentina."]},"solucion":{}},{"slug":"oceanos-2.s3.p2","orden":2,"grupo":"oceanos-2.s3.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué puede quedar atrapado como captura incidental? Marcá todo.","opciones":[{"id":"o1","texto":"Aves marinas como albatros"},{"id":"o2","texto":"Tortugas marinas"},{"id":"o3","texto":"Delfines"},{"id":"o4","texto":"Peces juveniles de otras especies"},{"id":"o5","texto":"Solo la especie buscada"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La captura incidental afecta a muchas especies que no son el objetivo de la pesca."}},{"slug":"oceanos-2.s3.p3","orden":3,"grupo":"oceanos-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Albatros y anzuelos","cuerpo":["En la pesca con palangre (líneas larguísimas con miles de anzuelos con carnada), los albatros y petreles se lanzan a comer la carnada mientras se cala la línea y quedan enganchados. Varias especies de albatros están amenazadas en buena parte por esta causa.","Hay soluciones simples y baratas: líneas espantapájaros que ahuyentan a las aves, calar de noche, cuando las aves están menos activas, y agregar pesos para que los anzuelos se hundan rápido."]},"solucion":{}},{"slug":"oceanos-2.s3.p4","orden":4,"grupo":"oceanos-2.s3.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una línea espantapájaros protege a los albatros.","items":[{"id":"i1","texto":"El barco cala la línea con anzuelos y carnada"},{"id":"i2","texto":"Una línea con cintas flota detrás del barco"},{"id":"i3","texto":"Las cintas espantan a las aves de la zona de los anzuelos"},{"id":"i4","texto":"Los anzuelos se hunden sin que las aves lleguen"},{"id":"i5","texto":"Menos albatros mueren enganchados"},{"id":"i6","texto":"La línea atrae más albatros para que coman"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una solución barata con un efecto enorme sobre especies amenazadas."}},{"slug":"oceanos-2.s3.p5","orden":5,"grupo":"oceanos-2.s3.p5","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con una solución.","izquierda":[{"id":"a1","texto":"Albatros enganchados en palangres"},{"id":"a2","texto":"Tortugas en redes de arrastre"},{"id":"a3","texto":"Juveniles de merluza en la pesca de langostino"},{"id":"a4","texto":"Delfines en redes"}],"derecha":[{"id":"b1","texto":"Líneas espantapájaros y calado nocturno"},{"id":"b2","texto":"Dispositivos excluidores de tortugas"},{"id":"b3","texto":"Dispositivos de selectividad en las redes"},{"id":"b4","texto":"Alarmas acústicas y cambios de zona"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Casi todos los problemas de captura incidental tienen soluciones técnicas conocidas."}},{"slug":"oceanos-2.s3.p6","orden":6,"grupo":"oceanos-2.s3.p6","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La captura incidental es un problema sin solución.","razones":[{"id":"r1","texto":"Porque existen soluciones técnicas probadas"},{"id":"r2","texto":"Porque los animales se escapan solos siempre"},{"id":"r3","texto":"Porque la captura incidental no existe"}]},"solucion":{"valor":false,"explicacion":"Hay soluciones probadas: líneas espantapájaros, dispositivos excluidores, redes selectivas y cierres de zonas o temporadas.","clave":["r1"]}},{"slug":"oceanos-2.s3.p7","orden":7,"grupo":"oceanos-2.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Redes más selectivas","cuerpo":["Una red selectiva deja escapar a los peces demasiado chicos o a las especies que no se buscan: por ejemplo, con mallas de mayor tamaño o con rejillas que separan a los juveniles. Pescar con artes selectivas reduce el descarte y protege a los peces que todavía no se reprodujeron."]},"solucion":{}},{"slug":"oceanos-2.s3.p8","orden":8,"grupo":"oceanos-2.s3.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica reduce la captura incidental o la aumenta?","grupos":[{"id":"g1","nombre":"La reduce"},{"id":"g2","nombre":"La aumenta"}],"items":[{"id":"i1","texto":"Usar mallas más grandes"},{"id":"i2","texto":"Redes con malla muy fina"},{"id":"i3","texto":"Instalar líneas espantapájaros"},{"id":"i4","texto":"Calar de día con muchas aves alrededor"},{"id":"i5","texto":"Evitar zonas de cría en temporada"},{"id":"i6","texto":"Pescar en zonas de concentración de juveniles"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las decisiones de cómo, cuándo y dónde se pesca cambian mucho lo que se captura sin querer."}},{"slug":"oceanos-2.s3.p9","orden":9,"grupo":"oceanos-2.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barco captura 100 toneladas en total y el 30 % es descarte. ¿Cuántas toneladas se tiran al mar?","unidad":"toneladas","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"100 × 30 ÷ 100 = 30 t descartadas. Vida marina que se pierde sin alimentar a nadie."}},{"slug":"oceanos-2.s3.p9.v2","orden":9,"grupo":"oceanos-2.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barco captura 200 toneladas en total y el 25 % es descarte. ¿Cuántas toneladas se tiran al mar?","unidad":"toneladas","decimales":0},"solucion":{"valor":50,"tolerancia":1,"explicacion":"200 × 25 ÷ 100 = 50 t descartadas. Vida marina que se pierde sin alimentar a nadie."}},{"slug":"oceanos-2.s3.p9.v3","orden":9,"grupo":"oceanos-2.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barco captura 150 toneladas en total y el 40 % es descarte. ¿Cuántas toneladas se tiran al mar?","unidad":"toneladas","decimales":0},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"150 × 40 ÷ 100 = 60 t descartadas. Vida marina que se pierde sin alimentar a nadie."}},{"slug":"oceanos-2.s3.p10","orden":10,"grupo":"oceanos-2.s3.p10","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene dejar escapar a los peces juveniles?","opciones":[{"id":"o1","texto":"Porque todavía no se reprodujeron"},{"id":"o2","texto":"Porque tienen muy mal sabor al cocinarlos"},{"id":"o3","texto":"Porque siempre son de otra especie distinta"},{"id":"o4","texto":"Porque pesan demasiado para las redes"}]},"solucion":{"clave":["o1"],"explicacion":"Pescar juveniles es pescar el futuro de la población.","por_opcion":{"o3":"Pueden ser de la misma especie buscada: el punto es que todavía no se reprodujeron."}}},{"slug":"oceanos-2.s3.p11","orden":11,"grupo":"oceanos-2.s3.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Calar los palangres de noche puede reducir la captura de aves marinas.","razones":[{"id":"r1","texto":"Porque de noche muchas aves están menos activas"},{"id":"r2","texto":"Porque de noche no hay peces"},{"id":"r3","texto":"Porque las aves duermen dentro del barco"}]},"solucion":{"valor":true,"explicacion":"De noche, muchas aves marinas están menos activas y es menos probable que se lancen a la carnada.","clave":["r1"]}},{"slug":"oceanos-2.s3.p12","orden":12,"grupo":"oceanos-2.s3.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un barco palangrero quiere reducir la muerte de albatros con poco costo. ¿Qué conviene?","opciones":[{"id":"o1","texto":"Líneas espantapájaros y calado nocturno"},{"id":"o2","texto":"Dejar de usar carnada en los anzuelos"},{"id":"o3","texto":"Pescar más cerca de las colonias de aves"},{"id":"o4","texto":"Tirar restos de pescado al agua mientras se cala"}]},"solucion":{"clave":["o1"],"explicacion":"Medidas baratas y probadas que salvan miles de aves por año donde se aplican.","por_opcion":{"o3":"Aumentaría el riesgo: habría más aves alrededor."}}},{"slug":"oceanos-2.s3.p13","orden":13,"grupo":"oceanos-2.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los albatros pueden quedar enganchados en los palangres."},{"id":"s2","texto":"El descarte no afecta a la población porque los peces vuelven al mar."},{"id":"s3","texto":"Las líneas espantapájaros reducen la mortalidad de aves."},{"id":"s4","texto":"Las mallas más finas hacen más selectiva la pesca."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo que se pesca sin querer también cuenta.","por_opcion":{"s2":"Muchos vuelven muertos o moribundos.","s4":"Las mallas más grandes dejan escapar a los chicos; las finas capturan más juveniles."}}},{"slug":"oceanos-2.s3.p14","orden":14,"grupo":"oceanos-2.s3.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Lo que queda atrapado sin ser la especie buscada es captura {{0}}; lo que se tira de vuelta al mar es el {{1}}.","banco":[{"id":"w1","texto":"incidental"},{"id":"w2","texto":"descarte"},{"id":"w3","texto":"principal"},{"id":"w4","texto":"reciclaje"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos conceptos para entender el costo oculto de la pesca."}}]},{"slug":"oceanos-2.s4","orden":4,"tipo":"leccion","titulo_es":"Las reglas del mar","bajada_es":"Tallas mínimas, vedas, cuotas, zonas cerradas y la pesca ilegal en la milla 201.","minutos":11,"pasos":[{"slug":"oceanos-2.s4.p1","orden":1,"grupo":"oceanos-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Herramientas de gestión","cuerpo":["Para que la pesca sea sostenible se usan varias reglas: tallas mínimas (no se pueden quedar peces más chicos que cierto tamaño); vedas (temporadas o zonas donde no se puede pescar, por ejemplo durante la reproducción); cuotas (límites de captura por año, por barco o por empresa); y áreas marinas protegidas, donde la pesca está restringida.","Las recomendaciones científicas, como las del INIDEP en Argentina, sirven de base para fijar estas reglas."]},"solucion":{}},{"slug":"oceanos-2.s4.p2","orden":2,"grupo":"oceanos-2.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada regla con su objetivo.","izquierda":[{"id":"a1","texto":"Talla mínima"},{"id":"a2","texto":"Veda"},{"id":"a3","texto":"Cuota"},{"id":"a4","texto":"Área marina protegida"}],"derecha":[{"id":"b1","texto":"Que los peces se reproduzcan antes de ser pescados"},{"id":"b2","texto":"Proteger la reproducción o las zonas de cría"},{"id":"b3","texto":"Limitar cuánto se pesca en total"},{"id":"b4","texto":"Dar refugio a las especies y sus hábitats"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro reglas que se complementan para que la pesca dure."}},{"slug":"oceanos-2.s4.p3","orden":3,"grupo":"oceanos-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La zona económica exclusiva","cuerpo":["Cada país costero tiene derechos sobre los recursos del mar hasta las 200 millas náuticas de su costa: es su zona económica exclusiva. Argentina regula la pesca en su zona y controla a los barcos que operan en ella.","Justo afuera, en la llamada \"milla 201\", operan flotas extranjeras —sobre todo de calamar— en aguas internacionales. Algunas ingresan ilegalmente a la zona argentina. Se controlan con patrullas y con seguimiento satelital de los barcos."]},"solucion":{}},{"slug":"oceanos-2.s4.p4","orden":4,"grupo":"oceanos-2.s4.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En la \"milla 201\" se aplican las mismas reglas de pesca que dentro de la zona económica exclusiva argentina.","razones":[{"id":"r1","texto":"Porque está fuera de la zona económica exclusiva argentina"},{"id":"r2","texto":"Porque la milla 201 es un puerto argentino"},{"id":"r3","texto":"Porque allí está prohibida toda pesca"}]},"solucion":{"valor":false,"explicacion":"Es aguas internacionales, fuera de la jurisdicción argentina. Allí operan flotas extranjeras, algunas de las cuales entran ilegalmente a la zona argentina.","clave":["r1"]}},{"slug":"oceanos-2.s4.p5","orden":5,"grupo":"oceanos-2.s4.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué la pesca ilegal afecta a todos.","items":[{"id":"i1","texto":"Barcos ilegales pescan sin respetar cuotas ni vedas"},{"id":"i2","texto":"Se captura más de lo que las poblaciones reponen"},{"id":"i3","texto":"Las poblaciones bajan"},{"id":"i4","texto":"Los pescadores que cumplen las reglas capturan menos"},{"id":"i5","texto":"Se pierden trabajo, alimento y biodiversidad"},{"id":"i6","texto":"La pesca ilegal hace crecer las poblaciones"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La pesca ilegal perjudica a los ecosistemas y también a quienes pescan legalmente."}},{"slug":"oceanos-2.s4.p6","orden":6,"grupo":"oceanos-2.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una milla náutica equivale a 1,852 km. ¿A cuántos kilómetros de la costa llega una zona económica exclusiva de 200 millas? Redondeá al entero.","unidad":"km","decimales":0},"solucion":{"valor":370,"tolerancia":1,"explicacion":"200 × 1,852 ≈ 370 km. Un territorio marino enorme que hay que controlar."}},{"slug":"oceanos-2.s4.p7","orden":7,"grupo":"oceanos-2.s4.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una regla de gestión pesquera o una práctica ilegal?","grupos":[{"id":"g1","nombre":"Regla de gestión"},{"id":"g2","nombre":"Práctica ilegal"}],"items":[{"id":"i1","texto":"Cerrar una zona de cría durante la reproducción"},{"id":"i2","texto":"Pescar dentro de la zona económica exclusiva sin permiso"},{"id":"i3","texto":"Fijar una cuota anual de captura"},{"id":"i4","texto":"Apagar el sistema de seguimiento para esconderse"},{"id":"i5","texto":"Exigir un sistema de seguimiento satelital a los barcos"},{"id":"i6","texto":"Descargar capturas sin declarar"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las reglas funcionan si hay controles. La pesca ilegal busca justamente evadirlos."}},{"slug":"oceanos-2.s4.p8","orden":8,"grupo":"oceanos-2.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Áreas marinas protegidas","cuerpo":["Las áreas marinas protegidas funcionan como refugios: allí los peces crecen, se reproducen y \"desbordan\" hacia las zonas cercanas, donde se puede pescar. Argentina creó áreas marinas protegidas como Namuncurá-Banco Burdwood y Yaganes, en el sur del Mar Argentino."]},"solucion":{}},{"slug":"oceanos-2.s4.p9","orden":9,"grupo":"oceanos-2.s4.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué un área marina protegida puede beneficiar también a la pesca?","opciones":[{"id":"o1","texto":"Porque los peces crecen allí y se desbordan a zonas vecinas"},{"id":"o2","texto":"Porque en el área protegida se pesca sin límites"},{"id":"o3","texto":"Porque los peces no pueden salir del área"},{"id":"o4","texto":"Porque atrae barcos pesqueros de otros países"}]},"solucion":{"clave":["o1"],"explicacion":"Un refugio bien ubicado funciona como una \"cuenta de ahorro\" de peces.","por_opcion":{"o3":"Justamente salen: los que crecen protegidos llegan a zonas donde se puede pescar."}}},{"slug":"oceanos-2.s4.p10","orden":10,"grupo":"oceanos-2.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a controlar la pesca ilegal? Marcá todo.","opciones":[{"id":"o1","texto":"Seguimiento satelital de los barcos"},{"id":"o2","texto":"Patrullas en el mar"},{"id":"o3","texto":"Cooperación entre países"},{"id":"o4","texto":"Controles en los puertos donde se descarga"},{"id":"o5","texto":"Eliminar las cuotas de captura"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Vigilar en el mar, en los puertos y desde el espacio, y cooperar entre países."}},{"slug":"oceanos-2.s4.p11","orden":11,"grupo":"oceanos-2.s4.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas zonas del mar desde la costa hacia afuera.","items":[{"id":"i1","texto":"Mar territorial"},{"id":"i2","texto":"Zona contigua"},{"id":"i3","texto":"Zona económica exclusiva"},{"id":"i4","texto":"Aguas internacionales"}],"extremos":["Más cerca de la costa","Más lejos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Distintos derechos según la distancia a la costa. La pesca se regula sobre todo en la zona económica exclusiva.","valores":{"i1":"hasta las 12 millas","i2":"hasta las 24 millas","i3":"hasta las 200 millas","i4":"desde la milla 201"}}},{"slug":"oceanos-2.s4.p12","orden":12,"grupo":"oceanos-2.s4.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El seguimiento satelital permite saber dónde está un barco pesquero en cada momento.","razones":[{"id":"r1","texto":"Porque los barcos transmiten su posición"},{"id":"r2","texto":"Porque los satélites no ven el mar"},{"id":"r3","texto":"Porque los barcos no pueden moverse de noche"}]},"solucion":{"valor":true,"explicacion":"Los barcos llevan equipos que transmiten su posición. Si lo apagan en zonas sospechosas, es una señal de alerta.","clave":["r1"]}},{"slug":"oceanos-2.s4.p13","orden":13,"grupo":"oceanos-2.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Argentina tiene derechos sobre la pesca hasta las 200 millas."},{"id":"s2","texto":"Las vedas buscan que se pesque más durante la reproducción."},{"id":"s3","texto":"Algunos barcos extranjeros entran ilegalmente a la zona argentina."},{"id":"s4","texto":"Las áreas marinas protegidas perjudican siempre a los pescadores."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las reglas del mar protegen a los peces y, a largo plazo, a quienes viven de ellos.","por_opcion":{"s2":"Las vedas protegen la reproducción, prohibiendo o limitando la pesca.","s4":"Pueden beneficiarlos, porque los peces crecen allí y se desbordan a zonas vecinas."}}},{"slug":"oceanos-2.s4.p14","orden":14,"grupo":"oceanos-2.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un país tiene derechos sobre la pesca hasta las {{0}} millas; afuera, en la milla {{1}}, operan flotas extranjeras; y una {{2}} protege la reproducción.","banco":[{"id":"w1","texto":"200"},{"id":"w2","texto":"201"},{"id":"w3","texto":"veda"},{"id":"w4","texto":"12"},{"id":"w5","texto":"50"},{"id":"w6","texto":"cuota"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos del ordenamiento pesquero."}}]},{"slug":"oceanos-2.s5","orden":5,"tipo":"leccion","titulo_es":"Qué pescado elegir","bajada_es":"Variedad de especies, tallas, temporadas, origen y sellos: cómo elegir pescado y mariscos con menos impacto.","minutos":12,"pasos":[{"slug":"oceanos-2.s5.p1","orden":1,"grupo":"oceanos-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Diversificar","cuerpo":["Cuando todo el mundo quiere las mismas dos o tres especies, la presión sobre ellas crece. Comer una mayor variedad de especies —pescados menos conocidos que se capturan en buen estado, como la anchoíta, la caballa, la pescadilla o la corvina— reparte la presión.","Los pescados chicos, como la anchoíta y la sardina, además, suelen estar más abajo en la red trófica, crecen rápido y son muy nutritivos."]},"solucion":{}},{"slug":"oceanos-2.s5.p2","orden":2,"grupo":"oceanos-2.s5.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué práctica reparte la presión sobre las especies más pescadas?","opciones":[{"id":"o1","texto":"Comer una variedad mayor de especies"},{"id":"o2","texto":"Comer siempre la misma especie más conocida"},{"id":"o3","texto":"Comer solo langostinos importados"},{"id":"o4","texto":"Comprar el pescado más grande de la pescadería"}]},"solucion":{"clave":["o1"],"explicacion":"La variedad es una forma simple de cuidar las poblaciones.","por_opcion":{"o3":"Concentrar el consumo en una especie aumenta la presión sobre ella."}}},{"slug":"oceanos-2.s5.p3","orden":3,"grupo":"oceanos-2.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Talla y temporada","cuerpo":["Comprar pescado de talla adecuada evita alentar la captura de juveniles. Respetar las temporadas —no comprar especies en veda— también ayuda. En los ríos, por ejemplo, hay temporadas de veda para proteger la reproducción de especies como el dorado o el surubí."]},"solucion":{}},{"slug":"oceanos-2.s5.p4","orden":4,"grupo":"oceanos-2.s5.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta elección de compra ayuda a la pesca sostenible o no?","grupos":[{"id":"g1","nombre":"Ayuda"},{"id":"g2","nombre":"No ayuda"}],"items":[{"id":"i1","texto":"Elegir especies poco conocidas pero abundantes"},{"id":"i2","texto":"Pedir filetes de peces juveniles"},{"id":"i3","texto":"Preguntar el origen del pescado"},{"id":"i4","texto":"Comprar especies en veda"},{"id":"i5","texto":"Respetar las vedas de los ríos"},{"id":"i6","texto":"Elegir siempre la misma especie sobreexplotada"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Cada compra envía una señal hacia atrás en la cadena, hasta el barco."}},{"slug":"oceanos-2.s5.p5","orden":5,"grupo":"oceanos-2.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Origen y sellos","cuerpo":["Saber de dónde viene un pescado y cómo se pescó ayuda a elegir. Algunos pescados tienen sellos de certificación, como el de pesca sostenible del Marine Stewardship Council (MSC), otorgado por certificadoras independientes a pesquerías que cumplen un estándar. Para la acuicultura existen otros sellos.","Como viste en la rama de Consumo, un sello vale si es independiente y verificable."]},"solucion":{}},{"slug":"oceanos-2.s5.p6","orden":6,"grupo":"oceanos-2.s5.p6","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene preguntar al comprar pescado? Marcá todo.","opciones":[{"id":"o1","texto":"¿Qué especie es?"},{"id":"o2","texto":"¿De dónde viene?"},{"id":"o3","texto":"¿Cómo se pescó o se crió?"},{"id":"o4","texto":"¿Está en veda?"},{"id":"o5","texto":"¿Tiene el envase más colorido?"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cuatro preguntas que convierten una compra en una decisión informada."}},{"slug":"oceanos-2.s5.p7","orden":7,"grupo":"oceanos-2.s5.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un sello de pesca sostenible vale lo mismo lo otorgue quien lo otorgue.","razones":[{"id":"r1","texto":"Porque importa que sea independiente y verificable"},{"id":"r2","texto":"Porque todos los sellos son oficiales"},{"id":"r3","texto":"Porque los sellos no existen en la pesca"}]},"solucion":{"valor":false,"explicacion":"Vale si lo otorga una certificadora independiente con un estándar público y verificable. Si lo pone la propia marca, es una autodeclaración.","clave":["r1"]}},{"slug":"oceanos-2.s5.p8","orden":8,"grupo":"oceanos-2.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Pescado y huella","cuerpo":["Comparado con la carne vacuna, la mayoría de los pescados capturados en pesquerías bien gestionadas tienen una huella de carbono mucho menor por kilo de proteína, como viste en la rama de Alimentación. Pero hay excepciones: el langostino de criadero en zonas donde se talaron manglares, o especies pescadas con barcos que gastan muchísimo combustible, pueden tener huellas altas."]},"solucion":{}},{"slug":"oceanos-2.s5.p9","orden":9,"grupo":"oceanos-2.s5.p9","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas opciones de pescado por su impacto típico, de menor a mayor.","items":[{"id":"i1","texto":"Mejillones cultivados en cuerdas"},{"id":"i2","texto":"Anchoíta de una pesquería bien gestionada"},{"id":"i3","texto":"Merluza de una pesquería con cuotas y controles"},{"id":"i4","texto":"Langostino de criadero en manglares talados"}],"extremos":["Menor impacto","Mayor impacto"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El impacto depende de la especie y, sobre todo, de cómo se produce.","valores":{"i1":"muy bajo","i2":"bajo","i3":"moderado","i4":"alto"}}},{"slug":"oceanos-2.s5.p10","orden":10,"grupo":"oceanos-2.s5.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada pregunta con por qué importa.","izquierda":[{"id":"a1","texto":"¿Qué especie es?"},{"id":"a2","texto":"¿Qué talla tiene?"},{"id":"a3","texto":"¿Está en veda?"},{"id":"a4","texto":"¿Tiene un sello independiente?"}],"derecha":[{"id":"b1","texto":"Algunas están sobreexplotadas y otras no"},{"id":"b2","texto":"Evita alentar la captura de juveniles"},{"id":"b3","texto":"Protege la reproducción"},{"id":"b4","texto":"Indica una pesquería evaluada"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada pregunta apunta a un aspecto distinto de la sostenibilidad."}},{"slug":"oceanos-2.s5.p11","orden":11,"grupo":"oceanos-2.s5.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia come 2 kg de merluza por mes. Si reparte ese consumo entre 4 especies distintas por igual, ¿cuántos kg de merluza come por mes?","unidad":"kg","decimales":2},"solucion":{"valor":0.5,"tolerancia":0.02,"explicacion":"2 ÷ 4 ≈ 0,5 kg. Diversificar reparte la presión entre varias especies."}},{"slug":"oceanos-2.s5.p11.v2","orden":11,"grupo":"oceanos-2.s5.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia come 3 kg de merluza por mes. Si reparte ese consumo entre 3 especies distintas por igual, ¿cuántos kg de merluza come por mes?","unidad":"kg","decimales":2},"solucion":{"valor":1,"tolerancia":0.02,"explicacion":"3 ÷ 3 ≈ 1 kg. Diversificar reparte la presión entre varias especies."}},{"slug":"oceanos-2.s5.p11.v3","orden":11,"grupo":"oceanos-2.s5.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia come 1 kg de merluza por mes. Si reparte ese consumo entre 5 especies distintas por igual, ¿cuántos kg de merluza come por mes?","unidad":"kg","decimales":2},"solucion":{"valor":0.2,"tolerancia":0.02,"explicacion":"1 ÷ 5 ≈ 0,2 kg. Diversificar reparte la presión entre varias especies."}},{"slug":"oceanos-2.s5.p12","orden":12,"grupo":"oceanos-2.s5.p12","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos kilos de alimentos acuáticos por persona por año se consumen en promedio en el mundo.","min":1,"max":100,"paso":1,"unidad":"kg","escala":"log"},"solucion":{"valor":20.7,"banda":"log","explicacion":"Unos 20,7 kg según la FAO para 2022. En Argentina, bastante menos."}},{"slug":"oceanos-2.s5.p13","orden":13,"grupo":"oceanos-2.s5.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los pescados chicos, como la anchoíta, suelen ser una buena opción?","opciones":[{"id":"o1","texto":"Crecen rápido, abundan y están abajo en la red"},{"id":"o2","texto":"Porque son los más caros de la pescadería"},{"id":"o3","texto":"Porque no tienen nutrientes"},{"id":"o4","texto":"Porque vienen siempre de otros países"}]},"solucion":{"clave":["o1"],"explicacion":"Especies de crecimiento rápido y abundantes, pescadas con buena gestión, tienen menor impacto.","por_opcion":{"o3":"Al contrario: son muy nutritivos."}}},{"slug":"oceanos-2.s5.p14","orden":14,"grupo":"oceanos-2.s5.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos de una pescadería y marcá los equivocados.","segmentos":[{"id":"s1","texto":"Probá especies menos conocidas, como la caballa o la corvina."},{"id":"s2","texto":"Los peces más chiquitos son los más sostenibles, aunque sean juveniles."},{"id":"s3","texto":"Preguntá de dónde viene el pescado."},{"id":"s4","texto":"Cualquier sello en el paquete garantiza pesca sostenible."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Comprar pescado con criterio es parte de cuidar el mar.","por_opcion":{"s2":"Los juveniles no se reprodujeron: comprarlos alienta pescar el futuro.","s4":"Hay que verificar que sea independiente y verificable."}}},{"slug":"oceanos-2.s5.p15","orden":15,"grupo":"oceanos-2.s5.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Comer más {{0}} de especies reparte la presión; conviene no comprar peces {{1}}; y un sello vale si es {{2}}.","banco":[{"id":"w1","texto":"variedad"},{"id":"w2","texto":"juveniles"},{"id":"w3","texto":"independiente"},{"id":"w4","texto":"cantidad"},{"id":"w5","texto":"grandes"},{"id":"w6","texto":"colorido"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres criterios para elegir pescado con menos impacto."}}]},{"slug":"oceanos-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: pesca y alimentos del agua","bajada_es":"Captura y acuicultura, sobrepesca, captura incidental, reglas y elección, mezclados.","minutos":8,"pasos":[{"slug":"oceanos-2.s6.p1","orden":1,"grupo":"oceanos-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Pesca y alimentos del agua». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"oceanos-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la pescadería del puerto","bajada_es":"Una pescadería de un puerto patagónico quiere ofrecer pescado más sostenible. Con los datos, armá su plan.","minutos":10,"pasos":[{"slug":"oceanos-2.s7.p1","orden":1,"grupo":"oceanos-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La pescadería","cuerpo":["La pescadería vende 1.000 kg de pescado por semana: 700 kg de merluza, 200 kg de langostino y 100 kg de otras especies. Parte de la merluza que recibe son ejemplares chicos. Los clientes casi siempre piden merluza. Un proveedor ofrece anchoíta y caballa de pesquerías en buen estado, y mejillones de cultivo.","Los estudios del instituto de investigación indican que la merluza de la zona está cerca de su límite de captura sostenible."]},"solucion":{}},{"slug":"oceanos-2.s7.p2","orden":2,"grupo":"oceanos-2.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Qué porcentaje de las ventas es merluza?","unidad":"%","decimales":0,"contexto":"700 kg de merluza sobre 1.000 kg vendidos por semana."},"solucion":{"valor":70,"tolerancia":1.4000000000000001,"explicacion":"700 ÷ 1.000 × 100 = 70 %. Casi todo el consumo se concentra en una especie cerca de su límite."}},{"slug":"oceanos-2.s7.p3","orden":3,"grupo":"oceanos-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la pescadería reemplaza el 30 % de la merluza por anchoíta, caballa y mejillones, ¿cuántos kg de merluza vende por semana?","unidad":"kg","decimales":3},"solucion":{"valor":489.99999999999994,"tolerancia":9.799999999999999,"explicacion":"700 × 0,7 = 489.99999999999994 kg de merluza. La presión sobre la especie baja sin reducir las ventas totales."}},{"slug":"oceanos-2.s7.p3.v2","orden":3,"grupo":"oceanos-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la pescadería reemplaza el 40 % de la merluza por anchoíta, caballa y mejillones, ¿cuántos kg de merluza vende por semana?","unidad":"kg","decimales":0},"solucion":{"valor":420,"tolerancia":8.4,"explicacion":"700 × 0,6 = 420 kg de merluza. La presión sobre la especie baja sin reducir las ventas totales."}},{"slug":"oceanos-2.s7.p3.v3","orden":3,"grupo":"oceanos-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la pescadería reemplaza el 20 % de la merluza por anchoíta, caballa y mejillones, ¿cuántos kg de merluza vende por semana?","unidad":"kg","decimales":0},"solucion":{"valor":560,"tolerancia":11.200000000000001,"explicacion":"700 × 0,8 = 560 kg de merluza. La presión sobre la especie baja sin reducir las ventas totales."}},{"slug":"oceanos-2.s7.p4","orden":4,"grupo":"oceanos-2.s7.p4","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas conviene tomar? Marcá todas.","opciones":[{"id":"o1","texto":"No comprar merluza por debajo de la talla mínima"},{"id":"o2","texto":"Ofrecer anchoíta, caballa y mejillones"},{"id":"o3","texto":"Explicar a los clientes por qué conviene variar"},{"id":"o4","texto":"Pedir al proveedor información sobre el origen"},{"id":"o5","texto":"Comprar más merluza chica porque es más barata"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Talla, variedad, información y trazabilidad: un plan completo."}},{"slug":"oceanos-2.s7.p5","orden":5,"grupo":"oceanos-2.s7.p5","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Los clientes siguen pidiendo merluza. ¿Qué estrategia tiene más chances de cambiar sus hábitos?","opciones":[{"id":"o1","texto":"Degustaciones y recetas con las especies nuevas"},{"id":"o2","texto":"Dejar de vender merluza de golpe sin explicar nada"},{"id":"o3","texto":"Subir mucho el precio de todas las especies"},{"id":"o4","texto":"No decir nada y esperar que cambien solos"}]},"solucion":{"clave":["o1"],"explicacion":"Hacerlo fácil y atractivo: probar, aprender a cocinarlo y ver que otros lo eligen.","por_opcion":{"o3":"Puede alejar a los clientes sin ofrecer alternativas atractivas."}}},{"slug":"oceanos-2.s7.p6","orden":6,"grupo":"oceanos-2.s7.p6","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la pescadería puede ayudar a la merluza.","items":[{"id":"i1","texto":"La pescadería ofrece más variedad y explica por qué"},{"id":"i2","texto":"Los clientes prueban otras especies"},{"id":"i3","texto":"Se vende menos merluza"},{"id":"i4","texto":"La pescadería compra menos merluza y rechaza las chicas"},{"id":"i5","texto":"Baja la presión sobre la población de merluza"},{"id":"i6","texto":"La merluza se reproduce más porque se vende en otra pescadería"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una decisión comercial chica que empuja en la dirección correcta, junto con las reglas de pesca."}},{"slug":"oceanos-2.s7.p7","orden":7,"grupo":"oceanos-2.s7.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá los argumentos que se escuchan en el puerto.","grupos":[{"id":"g1","nombre":"Con fundamento"},{"id":"g2","nombre":"Sin fundamento"}],"items":[{"id":"i1","texto":"La merluza está cerca de su límite de captura"},{"id":"i2","texto":"Los peces chicos son los más sostenibles"},{"id":"i3","texto":"La anchoíta es abundante y muy nutritiva"},{"id":"i4","texto":"El mar es infinito"},{"id":"i5","texto":"Los mejillones de cultivo tienen bajo impacto"},{"id":"i6","texto":"Si una especie se acaba, se cambia por otra y listo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Decidir con datos del instituto y con la red marina en mente."}},{"slug":"oceanos-2.s7.p8","orden":8,"grupo":"oceanos-2.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La pescadería escribe su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Solo compraremos merluza por encima de la talla mínima."},{"id":"s2","texto":"Venderemos juveniles de merluza a mitad de precio para no desperdiciarlos."},{"id":"s3","texto":"Ofreceremos degustaciones de caballa y anchoíta."},{"id":"s4","texto":"Como vendemos poco, lo que hagamos no cambia nada."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan cuida la especie, informa a los clientes y se sostiene en el tiempo.","por_opcion":{"s2":"Alienta a seguir pescando juveniles; mejor rechazarlos en la compra.","s4":"Cada comprador suma, y el ejemplo puede contagiar a otras pescaderías."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"oceanos-3","rama":"agua_azul","orden":3,"nivel":2,"titulo_es":"Ríos y mares contaminados","bajada_es":"Cloacas, fertilizantes, plásticos, mercurio y petróleo: cómo llega la contaminación del continente al agua, qué efectos tiene y cómo se limpia y se previene.","objetivos_es":["Distinguir fuentes puntuales y difusas de contaminación del agua","Explicar la eutrofización y la formación de zonas muertas","Analizar el recorrido del plástico desde la ciudad hasta el mar","Explicar la bioacumulación y la biomagnificación de contaminantes","Evaluar medidas de tratamiento, prevención y recuperación de ríos y costas"],"repasa":["oceanos-1","agua-3","residuos-4","oceanos-2"],"requiere_tronco":2,"fuentes":["un-water-aguas-residuales","diaz-rosenberg-2008","oecd-plasticos","unep-plasticos","minamata","acumar","aysa","vida-silvestre"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"oceanos-3.s1","orden":1,"tipo":"leccion","titulo_es":"De dónde viene","bajada_es":"Caños que se ven y escurrimientos que no: las fuentes de la contaminación del agua.","minutos":11,"pasos":[{"slug":"oceanos-3.s1.p1","orden":1,"grupo":"oceanos-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Casi todo viene de tierra","cuerpo":["La mayor parte de la contaminación que llega a los mares se origina en tierra firme: cloacas, industrias, campos, calles y basurales. Los ríos la transportan hasta las costas. Por eso, cuidar el mar empieza muy lejos de la playa: en cada ciudad y en cada campo de la cuenca."]},"solucion":{}},{"slug":"oceanos-3.s1.p2","orden":2,"grupo":"oceanos-3.s1.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Puntual y difusa","cuerpo":["La contaminación puntual sale de un lugar identificable, como el caño de una fábrica o una cloaca que desemboca en un río: se puede medir y controlar en ese punto. La contaminación difusa viene de muchos lugares a la vez, como los fertilizantes que la lluvia arrastra desde miles de campos, el aceite y la basura de las calles o los desechos de animales: es mucho más difícil de controlar."]},"solucion":{}},{"slug":"oceanos-3.s1.p3","orden":3,"grupo":"oceanos-3.s1.p3","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es contaminación puntual o difusa?","grupos":[{"id":"g1","nombre":"Puntual"},{"id":"g2","nombre":"Difusa"}],"items":[{"id":"i1","texto":"El caño de efluentes de una curtiembre"},{"id":"i2","texto":"Fertilizante arrastrado por la lluvia desde muchos campos"},{"id":"i3","texto":"La descarga de una cloaca sin tratar"},{"id":"i4","texto":"Aceite y basura que la lluvia lleva desde las calles"},{"id":"i5","texto":"El desagüe de una planta industrial"},{"id":"i6","texto":"Estiércol de corrales dispersos en una cuenca"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Lo puntual se controla en el caño; lo difuso, cambiando prácticas en todo el territorio."}},{"slug":"oceanos-3.s1.p4","orden":4,"grupo":"oceanos-3.s1.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la contaminación difusa es más difícil de controlar?","opciones":[{"id":"o1","texto":"Viene de muchos lugares a la vez"},{"id":"o2","texto":"Porque es menos dañina que la puntual"},{"id":"o3","texto":"Porque solo ocurre en el mar abierto"},{"id":"o4","texto":"Porque la ley no la permite medir"}]},"solucion":{"clave":["o1"],"explicacion":"No hay un punto donde poner un filtro: hay que cambiar prácticas en muchos lugares.","por_opcion":{"o3":"Ocurre en toda la cuenca, empezando en tierra."}}},{"slug":"oceanos-3.s1.p5","orden":5,"grupo":"oceanos-3.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las aguas residuales","cuerpo":["Una de las principales fuentes es el agua residual de las casas y las industrias. Según ONU-Agua, en 2022 solo el 56 % de las aguas residuales domésticas del mundo se trataba de forma segura: el resto llegaba a ríos, lagos y mares con distinto grado de tratamiento o sin ninguno. Lo viste en la unidad del desagüe al río: tratar las cloacas es una de las inversiones ambientales y sanitarias más importantes."],"destacado":{"valor":"56 %","texto":"de las aguas residuales domésticas del mundo se trató de forma segura en 2022, según ONU-Agua."}},"solucion":{}},{"slug":"oceanos-3.s1.p6","orden":6,"grupo":"oceanos-3.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una región genera 100 millones de metros cúbicos de aguas residuales por año y se trata de forma segura el 56 %, ¿cuántos millones de metros cúbicos no se tratan de forma segura?","unidad":"millones de m³","decimales":1,"contexto":"100 millones de m³; 56 % tratado de forma segura."},"solucion":{"valor":44,"tolerancia":0.1,"explicacion":"El 44 % no se trata de forma segura: 100 × 0,44 = 44 millones de m³ por año que llegan al agua con poco o ningún tratamiento."}},{"slug":"oceanos-3.s1.p6.v2","orden":6,"grupo":"oceanos-3.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una región genera 250 millones de metros cúbicos de aguas residuales por año y se trata de forma segura el 56 %, ¿cuántos millones de metros cúbicos no se tratan de forma segura?","unidad":"millones de m³","decimales":1,"contexto":"250 millones de m³; 56 % tratado de forma segura."},"solucion":{"valor":110,"tolerancia":0.1,"explicacion":"El 44 % no se trata de forma segura: 250 × 0,44 = 110 millones de m³ por año que llegan al agua con poco o ningún tratamiento."}},{"slug":"oceanos-3.s1.p6.v3","orden":6,"grupo":"oceanos-3.s1.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una región genera 40 millones de metros cúbicos de aguas residuales por año y se trata de forma segura el 56 %, ¿cuántos millones de metros cúbicos no se tratan de forma segura?","unidad":"millones de m³","decimales":1,"contexto":"40 millones de m³; 56 % tratado de forma segura."},"solucion":{"valor":17.6,"tolerancia":0.1,"explicacion":"El 44 % no se trata de forma segura: 40 × 0,44 = 17,6 millones de m³ por año que llegan al agua con poco o ningún tratamiento."}},{"slug":"oceanos-3.s1.p7","orden":7,"grupo":"oceanos-3.s1.p7","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de la contaminación de una ciudad hasta el mar.","items":[{"id":"i1","texto":"Las cloacas y los desagües de la ciudad descargan en un arroyo"},{"id":"i2","texto":"El arroyo desemboca en un río grande"},{"id":"i3","texto":"El río transporta los contaminantes aguas abajo"},{"id":"i4","texto":"Llegan al estuario y a la costa"},{"id":"i5","texto":"Se dispersan en el mar"},{"id":"i6","texto":"Los contaminantes desaparecen al llegar al río"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una cuenca conecta todo: lo que se tira en la ciudad puede terminar en el mar."}},{"slug":"oceanos-3.s1.p8","orden":8,"grupo":"oceanos-3.s1.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué actividades generan contaminación difusa? Marcá todas.","opciones":[{"id":"o1","texto":"Aplicar fertilizantes en miles de campos"},{"id":"o2","texto":"El escurrimiento de las calles cuando llueve"},{"id":"o3","texto":"Tirar basura en la vía pública"},{"id":"o4","texto":"El caño de efluentes de una fábrica"},{"id":"o5","texto":"La descarga de una planta cloacal"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Las fuentes difusas suman muchas pequeñas descargas; las puntuales salen de un solo lugar."}},{"slug":"oceanos-3.s1.p9","orden":9,"grupo":"oceanos-3.s1.p9","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una ciudad está lejos del mar, lo que tira por sus desagües no puede afectarlo.","razones":[{"id":"r1","texto":"Porque los ríos conectan el interior con el mar"},{"id":"r2","texto":"Porque los desagües no llevan contaminantes"},{"id":"r3","texto":"Porque el mar no recibe agua de los ríos"}]},"solucion":{"valor":false,"explicacion":"Los ríos conectan las ciudades del interior con el mar. Una cuenca como la del Plata lleva hasta el océano lo que se descarga a miles de kilómetros.","clave":["r1"]}},{"slug":"oceanos-3.s1.p10","orden":10,"grupo":"oceanos-3.s1.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada fuente con su tipo de contaminante principal.","izquierda":[{"id":"a1","texto":"Cloacas sin tratar"},{"id":"a2","texto":"Campos con fertilizantes"},{"id":"a3","texto":"Curtiembres"},{"id":"a4","texto":"Calles de la ciudad"}],"derecha":[{"id":"b1","texto":"Materia orgánica y bacterias"},{"id":"b2","texto":"Nitrógeno y fósforo"},{"id":"b3","texto":"Cromo y otros químicos"},{"id":"b4","texto":"Basura, aceites y metales"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada fuente aporta contaminantes distintos, que piden soluciones distintas."}},{"slug":"oceanos-3.s1.p11","orden":11,"grupo":"oceanos-3.s1.p11","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de las aguas residuales domésticas del mundo se trató de forma segura en 2022, según ONU-Agua.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":56,"banda":"lineal","explicacion":"Alrededor del 56 %. Casi la mitad de las aguas residuales domésticas del mundo no recibe un tratamiento seguro."}},{"slug":"oceanos-3.s1.p12","orden":12,"grupo":"oceanos-3.s1.p12","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una fábrica y cien campos contaminan el mismo arroyo. ¿Qué fuente es más fácil de controlar?","opciones":[{"id":"o1","texto":"La fábrica, porque descarga por un solo punto"},{"id":"o2","texto":"Los cien campos, porque son más"},{"id":"o3","texto":"Ninguna de las dos se puede controlar"},{"id":"o4","texto":"Las dos por igual y con la misma herramienta"}]},"solucion":{"clave":["o1"],"explicacion":"En la fábrica se mide y se trata en el caño; en los campos hay que cambiar prácticas en cada lote.","por_opcion":{"o3":"Las dos se pueden controlar, pero con herramientas distintas."}}},{"slug":"oceanos-3.s1.p13","orden":13,"grupo":"oceanos-3.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Buena parte de la contaminación del mar viene de tierra firme."},{"id":"s2","texto":"La contaminación difusa sale siempre de un único caño."},{"id":"s3","texto":"Tratar las cloacas es clave para proteger ríos y mares."},{"id":"s4","texto":"En el mundo se trata de forma segura casi toda el agua residual."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Saber de dónde viene la contaminación es el primer paso para frenarla.","por_opcion":{"s2":"Es la puntual la que sale de un punto; la difusa viene de muchos lugares.","s4":"En 2022, solo alrededor del 56 %."}}},{"slug":"oceanos-3.s1.p14","orden":14,"grupo":"oceanos-3.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La contaminación que sale de un caño identificable es {{0}}; la que viene de muchos lugares a la vez es {{1}}; y en 2022 se trató de forma segura el {{2}} % de las aguas residuales domésticas del mundo.","banco":[{"id":"w1","texto":"puntual"},{"id":"w2","texto":"difusa"},{"id":"w3","texto":"56"},{"id":"w4","texto":"secreta"},{"id":"w5","texto":"marina"},{"id":"w6","texto":"96"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas clave sobre las fuentes de contaminación del agua."}}]},{"slug":"oceanos-3.s2","orden":2,"tipo":"leccion","titulo_es":"Demasiados nutrientes","bajada_es":"Nitrógeno, fósforo, floraciones de algas y zonas muertas sin oxígeno.","minutos":12,"pasos":[{"slug":"oceanos-3.s2.p1","orden":1,"grupo":"oceanos-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Eutrofización","cuerpo":["El nitrógeno y el fósforo son nutrientes: las plantas los necesitan. Pero cuando llegan en exceso al agua —desde fertilizantes, estiércol y cloacas—, alimentan un crecimiento explosivo de algas y cianobacterias. Cuando esas algas mueren, las bacterias que las descomponen consumen el oxígeno del agua. Este proceso se llama eutrofización, y puede matar peces y otros organismos que necesitan oxígeno."]},"solucion":{}},{"slug":"oceanos-3.s2.p2","orden":2,"grupo":"oceanos-3.s2.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la eutrofización.","items":[{"id":"i1","texto":"Llegan al agua nitrógeno y fósforo en exceso"},{"id":"i2","texto":"Las algas y cianobacterias crecen de forma explosiva"},{"id":"i3","texto":"Las algas mueren y se hunden"},{"id":"i4","texto":"Las bacterias las descomponen y consumen oxígeno"},{"id":"i5","texto":"El agua se queda sin oxígeno y mueren peces"},{"id":"i6","texto":"Las algas producen tanto oxígeno que el agua se satura"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un exceso de algo bueno termina asfixiando la vida del agua."}},{"slug":"oceanos-3.s2.p3","orden":3,"grupo":"oceanos-3.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Zonas muertas","cuerpo":["En algunas costas, la eutrofización crea zonas muertas: áreas con tan poco oxígeno que casi nada puede vivir en el fondo. Un estudio publicado en Science en 2008 contó más de 400 zonas muertas costeras en el mundo, y su número venía creciendo desde los años 60. Una de las más grandes se forma cada verano en el Golfo de México, frente a la desembocadura del río Misisipi, que drena la región agrícola más grande de Estados Unidos."],"destacado":{"valor":"> 400","texto":"zonas muertas costeras había en el mundo según un estudio publicado en Science en 2008."}},"solucion":{}},{"slug":"oceanos-3.s2.p4","orden":4,"grupo":"oceanos-3.s2.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué se forma cada verano una gran zona muerta frente a la desembocadura del Misisipi?","opciones":[{"id":"o1","texto":"El río trae fertilizantes de una enorme región agrícola"},{"id":"o2","texto":"Porque el agua del golfo es demasiado fría en verano"},{"id":"o3","texto":"Porque hay demasiados peces que consumen el oxígeno"},{"id":"o4","texto":"Porque allí no llegan ríos"}]},"solucion":{"clave":["o1"],"explicacion":"Lo que se aplica en millones de hectáreas de campo termina, en parte, en el mar.","por_opcion":{"o3":"El oxígeno lo consumen las bacterias que descomponen algas."}}},{"slug":"oceanos-3.s2.p5","orden":5,"grupo":"oceanos-3.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cianobacterias en casa","cuerpo":["En Argentina, en veranos cálidos aparecen floraciones de cianobacterias en el Río de la Plata, en embalses y en lagunas: el agua se pone verde y puede formar una capa espesa. Algunas cianobacterias producen toxinas que pueden causar irritación en la piel, problemas digestivos o daños más graves. Por eso, cuando hay floraciones, las autoridades recomiendan no bañarse y evitar que chicos y mascotas tengan contacto con el agua."]},"solucion":{}},{"slug":"oceanos-3.s2.p6","orden":6,"grupo":"oceanos-3.s2.p6","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene hacer si una playa de río tiene una floración de cianobacterias? Marcá todo.","opciones":[{"id":"o1","texto":"No bañarse"},{"id":"o2","texto":"Evitar que las mascotas beban o se metan al agua"},{"id":"o3","texto":"Seguir las recomendaciones de las autoridades"},{"id":"o4","texto":"Bañarse igual si el agua está calentita"},{"id":"o5","texto":"Usar el agua verde para cocinar"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Las floraciones pueden producir toxinas: la precaución es simple y efectiva."}},{"slug":"oceanos-3.s2.p7","orden":7,"grupo":"oceanos-3.s2.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta condición favorece o reduce las floraciones de cianobacterias?","grupos":[{"id":"g1","nombre":"Las favorece"},{"id":"g2","nombre":"Las reduce"}],"items":[{"id":"i1","texto":"Agua cálida y quieta"},{"id":"i2","texto":"Menos nutrientes que llegan desde la cuenca"},{"id":"i3","texto":"Mucho fósforo y nitrógeno en el agua"},{"id":"i4","texto":"Agua que circula y se renueva"},{"id":"i5","texto":"Días de sol intenso y sin viento"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"El calentamiento y los nutrientes se combinan: por eso las floraciones pueden volverse más frecuentes."}},{"slug":"oceanos-3.s2.p8","orden":8,"grupo":"oceanos-3.s2.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una laguna, el oxígeno disuelto baja de 8 a 2 miligramos por litro después de una floración. ¿En qué porcentaje bajó? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"De 8 a 2 mg/L de oxígeno."},"solucion":{"valor":75,"tolerancia":1,"explicacion":"(8 − 2) ÷ 8 × 100 ≈ 75 %. Con menos de 2 a 3 mg/L, muchos peces no pueden sobrevivir."}},{"slug":"oceanos-3.s2.p8.v2","orden":8,"grupo":"oceanos-3.s2.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una laguna, el oxígeno disuelto baja de 7 a 3 miligramos por litro después de una floración. ¿En qué porcentaje bajó? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"De 7 a 3 mg/L de oxígeno."},"solucion":{"valor":57,"tolerancia":1,"explicacion":"(7 − 3) ÷ 7 × 100 ≈ 57 %. Con menos de 2 a 3 mg/L, muchos peces no pueden sobrevivir."}},{"slug":"oceanos-3.s2.p8.v3","orden":8,"grupo":"oceanos-3.s2.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una laguna, el oxígeno disuelto baja de 9 a 1 miligramos por litro después de una floración. ¿En qué porcentaje bajó? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"De 9 a 1 mg/L de oxígeno."},"solucion":{"valor":89,"tolerancia":1,"explicacion":"(9 − 1) ÷ 9 × 100 ≈ 89 %. Con menos de 2 a 3 mg/L, muchos peces no pueden sobrevivir."}},{"slug":"oceanos-3.s2.p9","orden":9,"grupo":"oceanos-3.s2.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo se reduce","cuerpo":["Para reducir la eutrofización hay que cortar los nutrientes en su origen: tratar las cloacas con etapas que remuevan nitrógeno y fósforo; aplicar fertilizantes en la dosis y el momento justos; dejar franjas de vegetación junto a los arroyos que retengan el escurrimiento; y conservar humedales, que funcionan como filtros naturales."]},"solucion":{}},{"slug":"oceanos-3.s2.p10","orden":10,"grupo":"oceanos-3.s2.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada medida con cómo reduce los nutrientes.","izquierda":[{"id":"a1","texto":"Tratamiento avanzado de cloacas"},{"id":"a2","texto":"Fertilización ajustada"},{"id":"a3","texto":"Franjas de vegetación junto a arroyos"},{"id":"a4","texto":"Humedales conservados"}],"derecha":[{"id":"b1","texto":"Remueve nitrógeno y fósforo antes de descargar"},{"id":"b2","texto":"Menos sobrante que la lluvia pueda arrastrar"},{"id":"b3","texto":"Retienen el escurrimiento de los campos"},{"id":"b4","texto":"Filtran nutrientes de forma natural"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Las soluciones combinan tecnología, buenas prácticas y naturaleza."}},{"slug":"oceanos-3.s2.p11","orden":11,"grupo":"oceanos-3.s2.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el nitrógeno y el fósforo son nutrientes, cuanto más llegue al agua, mejor para la vida acuática.","razones":[{"id":"r1","texto":"Porque en exceso provocan falta de oxígeno"},{"id":"r2","texto":"Porque las plantas acuáticas no usan nutrientes"},{"id":"r3","texto":"Porque los peces se alimentan de fertilizantes"}]},"solucion":{"valor":false,"explicacion":"En exceso provocan floraciones de algas que, al descomponerse, agotan el oxígeno y matan peces.","clave":["r1"]}},{"slug":"oceanos-3.s2.p12","orden":12,"grupo":"oceanos-3.s2.p12","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas zonas muertas costeras había en el mundo según el estudio publicado en Science en 2008.","min":1,"max":100000,"paso":1,"unidad":"zonas","escala":"log"},"solucion":{"valor":400,"banda":"log","explicacion":"Más de 400, y su número venía creciendo desde los años 60 por el aumento de nutrientes que llegan desde tierra."}},{"slug":"oceanos-3.s2.p13","orden":13,"grupo":"oceanos-3.s2.p13","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos niveles de oxígeno disuelto en el agua, del más saludable al menos saludable para los peces.","items":[{"id":"i1","texto":"8 mg/L"},{"id":"i2","texto":"5 mg/L"},{"id":"i3","texto":"3 mg/L"},{"id":"i4","texto":"1 mg/L"}],"extremos":["Más saludable","Menos saludable"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Por debajo de 2 o 3 mg/L, la mayoría de los peces no puede sobrevivir.","valores":{"i1":"muy bueno","i2":"aceptable para muchos peces","i3":"estresante","i4":"casi sin vida"}}},{"slug":"oceanos-3.s2.p14","orden":14,"grupo":"oceanos-3.s2.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este cartel en una playa y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Hoy hay floración de cianobacterias: no se recomienda bañarse."},{"id":"s2","texto":"Si el agua está verde, es más limpia y saludable."},{"id":"s3","texto":"Mantené a tus mascotas lejos del agua."},{"id":"s4","texto":"Las floraciones aparecen sobre todo con agua fría."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Saber leer las señales del agua protege la salud.","por_opcion":{"s2":"El color verde puede indicar una floración potencialmente tóxica.","s4":"Son más frecuentes con agua cálida, quieta y con muchos nutrientes."}}},{"slug":"oceanos-3.s2.p15","orden":15,"grupo":"oceanos-3.s2.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El exceso de nutrientes que causa algas y falta de oxígeno se llama {{0}}; las áreas del mar casi sin oxígeno son zonas {{1}}; y los humedales funcionan como {{2}} naturales.","banco":[{"id":"w1","texto":"eutrofización"},{"id":"w2","texto":"muertas"},{"id":"w3","texto":"filtros"},{"id":"w4","texto":"oxigenación"},{"id":"w5","texto":"vivas"},{"id":"w6","texto":"fuentes"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para entender el problema de los nutrientes."}}]},{"slug":"oceanos-3.s3","orden":3,"tipo":"leccion","titulo_es":"Plástico en el agua","bajada_es":"Del tacho a la costa: cuánto plástico llega a ríos y mares, qué forma toma y qué se encuentra en las playas.","minutos":11,"pasos":[{"slug":"oceanos-3.s3.p1","orden":1,"grupo":"oceanos-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto llega","cuerpo":["Según la OCDE, en 2019 unas 6,1 millones de toneladas de plástico llegaron a ríos, lagos y mares, y de eso alrededor de 1,7 millones de toneladas alcanzaron los océanos. Los ríos funcionan como cintas transportadoras: acumulan plástico durante años y lo van liberando al mar, sobre todo en las crecidas. Lo viste en la unidad del plástico: una parte muy grande de los residuos plásticos del mundo se gestiona mal."]},"solucion":{}},{"slug":"oceanos-3.s3.p2","orden":2,"grupo":"oceanos-3.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si 6,1 millones de toneladas de plástico llegaron a ambientes acuáticos y 1,7 millones alcanzaron el océano, ¿qué porcentaje llegó al océano? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"1.7 de 6.1 millones de toneladas."},"solucion":{"valor":28,"tolerancia":1,"explicacion":"1,7 ÷ 6,1 × 100 ≈ 28 %. El resto queda, por ahora, en ríos y lagos: una reserva que seguirá llegando al mar."}},{"slug":"oceanos-3.s3.p2.v2","orden":2,"grupo":"oceanos-3.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"De 6,1 millones de toneladas de plástico que llegaron al agua en 2019, 1,7 millones alcanzaron el océano. ¿Qué porcentaje es? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"1.7 de 6.1 millones de toneladas."},"solucion":{"valor":28,"tolerancia":1,"explicacion":"1,7 ÷ 6,1 × 100 ≈ 28 %. El resto queda, por ahora, en ríos y lagos: una reserva que seguirá llegando al mar."}},{"slug":"oceanos-3.s3.p2.v3","orden":2,"grupo":"oceanos-3.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Qué porcentaje de los 6,1 millones de toneladas de plástico que llegaron a ríos, lagos y mares alcanzó el océano, si fueron 1,7 millones? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"1.7 de 6.1 millones de toneladas."},"solucion":{"valor":28,"tolerancia":1,"explicacion":"1,7 ÷ 6,1 × 100 ≈ 28 %. El resto queda, por ahora, en ríos y lagos: una reserva que seguirá llegando al mar."}},{"slug":"oceanos-3.s3.p3","orden":3,"grupo":"oceanos-3.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Microplásticos y redes fantasma","cuerpo":["En el agua, el plástico se fragmenta por el sol y el oleaje en pedazos cada vez más chicos. Los menores de 5 milímetros se llaman microplásticos, y se encontraron en el agua, en los sedimentos, en animales y en el agua potable. También son un problema las redes y otros aparejos de pesca perdidos o abandonados, las \"redes fantasma\", que siguen atrapando peces, tortugas y mamíferos marinos durante años."]},"solucion":{}},{"slug":"oceanos-3.s3.p4","orden":4,"grupo":"oceanos-3.s3.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada forma de plástico con su efecto.","izquierda":[{"id":"a1","texto":"Bolsas y envoltorios"},{"id":"a2","texto":"Redes fantasma"},{"id":"a3","texto":"Microplásticos"},{"id":"a4","texto":"Tapitas y fragmentos"}],"derecha":[{"id":"b1","texto":"Tortugas que los confunden con alimento"},{"id":"b2","texto":"Siguen atrapando animales durante años"},{"id":"b3","texto":"Son ingeridos por organismos pequeños"},{"id":"b4","texto":"Aves marinas que los ingieren"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada forma de plástico daña de una manera distinta."}},{"slug":"oceanos-3.s3.p5","orden":5,"grupo":"oceanos-3.s3.p5","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de una bolsa hasta convertirse en microplástico.","items":[{"id":"i1","texto":"Una bolsa se vuela de un basural"},{"id":"i2","texto":"La lluvia la arrastra a un arroyo"},{"id":"i3","texto":"El río la lleva hasta la costa"},{"id":"i4","texto":"El sol y el oleaje la rompen en pedazos"},{"id":"i5","texto":"Se forman fragmentos cada vez más chicos"},{"id":"i6","texto":"La bolsa se biodegrada por completo en una semana"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El plástico no desaparece: se rompe en pedazos cada vez más difíciles de recuperar."}},{"slug":"oceanos-3.s3.p6","orden":6,"grupo":"oceanos-3.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que dicen las playas","cuerpo":["En Argentina, organizaciones como la Fundación Vida Silvestre organizan censos de basura costera con voluntarios, que registran qué residuos se encuentran en las playas. En esos censos, la gran mayoría de los objetos suelen ser plásticos: colillas, envoltorios, botellas, tapitas, bolsas, sorbetes y restos de pesca. Contar y clasificar la basura permite saber de dónde viene y qué políticas harían falta."]},"solucion":{}},{"slug":"oceanos-3.s3.p7","orden":7,"grupo":"oceanos-3.s3.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿El origen probable de este residuo de playa es el turismo local o la actividad pesquera?","grupos":[{"id":"g1","nombre":"Turismo y consumo local"},{"id":"g2","nombre":"Actividad pesquera"}],"items":[{"id":"i1","texto":"Colillas de cigarrillo"},{"id":"i2","texto":"Fragmentos de red"},{"id":"i3","texto":"Envoltorios de golosinas"},{"id":"i4","texto":"Cabos y sogas"},{"id":"i5","texto":"Sorbetes"},{"id":"i6","texto":"Cajones de pescado"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Clasificar la basura por origen muestra a quién le toca actuar: bañistas, comercios, municipios o flotas."}},{"slug":"oceanos-3.s3.p8","orden":8,"grupo":"oceanos-3.s3.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un censo de basura costera se registraron 2.000 objetos y 1.640 eran plásticos. ¿Qué porcentaje era plástico?","unidad":"%","decimales":0,"contexto":"1640 plásticos de 2000 objetos."},"solucion":{"valor":82,"tolerancia":1,"explicacion":"1.640 ÷ 2.000 × 100 = 82 %. Datos de ejemplo, del orden de lo que suelen mostrar los censos costeros."}},{"slug":"oceanos-3.s3.p8.v2","orden":8,"grupo":"oceanos-3.s3.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un censo de basura costera se registraron 1.500 objetos y 1.260 eran plásticos. ¿Qué porcentaje era plástico?","unidad":"%","decimales":0,"contexto":"1260 plásticos de 1500 objetos."},"solucion":{"valor":84,"tolerancia":1,"explicacion":"1.260 ÷ 1.500 × 100 = 84 %. Datos de ejemplo, del orden de lo que suelen mostrar los censos costeros."}},{"slug":"oceanos-3.s3.p8.v3","orden":8,"grupo":"oceanos-3.s3.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un censo de basura costera se registraron 3.000 objetos y 2.340 eran plásticos. ¿Qué porcentaje era plástico?","unidad":"%","decimales":0,"contexto":"2340 plásticos de 3000 objetos."},"solucion":{"valor":78,"tolerancia":1,"explicacion":"2.340 ÷ 3.000 × 100 = 78 %. Datos de ejemplo, del orden de lo que suelen mostrar los censos costeros."}},{"slug":"oceanos-3.s3.p9","orden":9,"grupo":"oceanos-3.s3.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Juntar la basura de las playas resuelve el problema del plástico en el mar.","razones":[{"id":"r1","texto":"Porque el plástico sigue llegando si no se reduce en origen"},{"id":"r2","texto":"Porque limpiar playas no sirve para nada"},{"id":"r3","texto":"Porque en el mar no hay plástico"}]},"solucion":{"valor":false,"explicacion":"Las limpiezas ayudan y generan datos, pero el plástico sigue llegando si no se reduce en origen y no se gestiona bien en tierra.","clave":["r1"]}},{"slug":"oceanos-3.s3.p10","orden":10,"grupo":"oceanos-3.s3.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los ríos liberan más plástico al mar durante las crecidas?","opciones":[{"id":"o1","texto":"Arrastran lo acumulado en orillas y fondos"},{"id":"o2","texto":"Porque en las crecidas la gente tira más basura"},{"id":"o3","texto":"Porque el agua de crecida fabrica plástico"},{"id":"o4","texto":"Porque en las crecidas el mar está más lejos"}]},"solucion":{"clave":["o1"],"explicacion":"Los ríos acumulan plástico durante años y lo liberan en pulsos, sobre todo con las crecidas.","por_opcion":{"o3":"El plástico no se fabrica en el río: se acumula y se moviliza."}}},{"slug":"oceanos-3.s3.p11","orden":11,"grupo":"oceanos-3.s3.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas medidas según cuánto reducen el plástico que llega al mar, de más a menos.","items":[{"id":"i1","texto":"Reducir descartables y cerrar basurales a cielo abierto"},{"id":"i2","texto":"Mejorar la recolección y el reciclaje"},{"id":"i3","texto":"Poner barreras en arroyos para atrapar residuos"},{"id":"i4","texto":"Limpiar la playa una vez al año"}],"extremos":["Reduce más","Reduce menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo viste con la escalera de los residuos: lo más efectivo es que el residuo no exista.","valores":{"i1":"corta en origen","i2":"mucho","i3":"intercepta una parte","i4":"poco, pero genera datos"}}},{"slug":"oceanos-3.s3.p12","orden":12,"grupo":"oceanos-3.s3.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué objetos suelen aparecer entre los más frecuentes en las playas? Marcá todos.","opciones":[{"id":"o1","texto":"Colillas de cigarrillo"},{"id":"o2","texto":"Envoltorios y bolsas"},{"id":"o3","texto":"Tapitas y botellas"},{"id":"o4","texto":"Caracoles vivos"},{"id":"o5","texto":"Algas"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Los caracoles y las algas son parte de la playa, no basura."}},{"slug":"oceanos-3.s3.p13","orden":13,"grupo":"oceanos-3.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los ríos llevan plástico al mar durante años."},{"id":"s2","texto":"Los microplásticos son pedazos de más de 5 centímetros."},{"id":"s3","texto":"Las redes fantasma siguen atrapando animales."},{"id":"s4","texto":"El plástico se disuelve en el agua de mar en pocos días."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El plástico no se va: cambia de tamaño y de lugar.","por_opcion":{"s2":"Son los menores de 5 milímetros.","s4":"Se fragmenta en pedazos cada vez más chicos, pero no desaparece."}}},{"slug":"oceanos-3.s3.p14","orden":14,"grupo":"oceanos-3.s3.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los pedazos de plástico menores de 5 milímetros son {{0}}; las redes de pesca abandonadas que siguen atrapando animales se llaman redes {{1}}; y los ríos funcionan como {{2}} transportadoras de plástico.","banco":[{"id":"w1","texto":"microplásticos"},{"id":"w2","texto":"fantasma"},{"id":"w3","texto":"cintas"},{"id":"w4","texto":"megaplásticos"},{"id":"w5","texto":"doradas"},{"id":"w6","texto":"filtros"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre el plástico en el agua."}}]},{"slug":"oceanos-3.s4","orden":4,"tipo":"leccion","titulo_es":"Lo que se acumula","bajada_es":"Mercurio, metales, petróleo y químicos: contaminantes que se concentran a lo largo de la cadena alimentaria.","minutos":11,"pasos":[{"slug":"oceanos-3.s4.p1","orden":1,"grupo":"oceanos-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Bioacumulación y biomagnificación","cuerpo":["Algunos contaminantes, como el mercurio, ciertos plaguicidas antiguos y otros compuestos persistentes, no se eliminan fácilmente del cuerpo: se acumulan con el tiempo en los tejidos de un organismo. Eso es la bioacumulación. Y como cada predador come muchas presas, la concentración aumenta en cada escalón de la cadena alimentaria: es la biomagnificación. Por eso los grandes predadores, como el pez espada o algunos atunes, pueden tener más mercurio."]},"solucion":{}},{"slug":"oceanos-3.s4.p2","orden":2,"grupo":"oceanos-3.s4.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená esta cadena alimentaria según la concentración de mercurio que suele acumular cada eslabón, de menor a mayor.","items":[{"id":"i1","texto":"Fitoplancton"},{"id":"i2","texto":"Zooplancton"},{"id":"i3","texto":"Pez pequeño"},{"id":"i4","texto":"Pez mediano"},{"id":"i5","texto":"Gran predador, como el pez espada"}],"extremos":["Menos mercurio","Más mercurio"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"En cada escalón, el contaminante se concentra más: los predadores tope reciben la mayor dosis."}},{"slug":"oceanos-3.s4.p3","orden":3,"grupo":"oceanos-3.s4.p3","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Bioacumulación"},{"id":"a2","texto":"Biomagnificación"},{"id":"a3","texto":"Contaminante persistente"},{"id":"a4","texto":"Predador tope"}],"derecha":[{"id":"b1","texto":"Un contaminante se acumula en un organismo con el tiempo"},{"id":"b2","texto":"La concentración aumenta en cada escalón de la cadena"},{"id":"b3","texto":"Tarda mucho en degradarse"},{"id":"b4","texto":"El último eslabón de la cadena alimentaria"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Estos conceptos explican por qué un contaminante diluido puede volverse peligroso."}},{"slug":"oceanos-3.s4.p4","orden":4,"grupo":"oceanos-3.s4.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el mercurio en el plancton es de 0,01 mg/kg y se multiplica por 10 en cada uno de 3 escalones de la cadena, ¿cuánto hay en el predador tope, en mg/kg? Redondeá a dos decimales.","unidad":"mg/kg","decimales":2,"contexto":"0.01 mg/kg en el plancton; ×10 en 3 escalones."},"solucion":{"valor":10,"tolerancia":0.01,"explicacion":"0,01 × 10³ = 10 mg/kg. Valores de ejemplo: muestran cómo algo casi imperceptible se vuelve importante en la cima de la cadena."}},{"slug":"oceanos-3.s4.p4.v2","orden":4,"grupo":"oceanos-3.s4.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el mercurio en el plancton es de 0,02 mg/kg y se multiplica por 8 en cada uno de 3 escalones de la cadena, ¿cuánto hay en el predador tope, en mg/kg? Redondeá a dos decimales.","unidad":"mg/kg","decimales":2,"contexto":"0.02 mg/kg en el plancton; ×8 en 3 escalones."},"solucion":{"valor":10.24,"tolerancia":0.01,"explicacion":"0,02 × 8³ = 10,24 mg/kg. Valores de ejemplo: muestran cómo algo casi imperceptible se vuelve importante en la cima de la cadena."}},{"slug":"oceanos-3.s4.p4.v3","orden":4,"grupo":"oceanos-3.s4.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el mercurio en el plancton es de 0,005 mg/kg y se multiplica por 12 en cada uno de 3 escalones de la cadena, ¿cuánto hay en el predador tope, en mg/kg? Redondeá a dos decimales.","unidad":"mg/kg","decimales":2,"contexto":"0.005 mg/kg en el plancton; ×12 en 3 escalones."},"solucion":{"valor":8.64,"tolerancia":0.01,"explicacion":"0,005 × 12³ = 8,64 mg/kg. Valores de ejemplo: muestran cómo algo casi imperceptible se vuelve importante en la cima de la cadena."}},{"slug":"oceanos-3.s4.p5","orden":5,"grupo":"oceanos-3.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso Minamata","cuerpo":["En la década de 1950, en la bahía de Minamata, en Japón, una fábrica vertió mercurio al mar durante años. El mercurio se acumuló en peces y mariscos, y miles de personas que los comían sufrieron daños neurológicos graves. El caso dio nombre al Convenio de Minamata sobre el Mercurio, un tratado internacional de 2013, que Argentina ratificó, para reducir el uso y las emisiones de mercurio en el mundo."]},"solucion":{}},{"slug":"oceanos-3.s4.p6","orden":6,"grupo":"oceanos-3.s4.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena del caso Minamata.","items":[{"id":"i1","texto":"Una fábrica vierte mercurio a la bahía"},{"id":"i2","texto":"El mercurio se acumula en peces y mariscos"},{"id":"i3","texto":"La población come esos peces con frecuencia"},{"id":"i4","texto":"Muchas personas sufren daños neurológicos"},{"id":"i5","texto":"Se crea un tratado internacional sobre el mercurio"},{"id":"i6","texto":"El mercurio se evapora y desaparece del agua"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un caso trágico que cambió las reglas del mundo sobre un contaminante."}},{"slug":"oceanos-3.s4.p7","orden":7,"grupo":"oceanos-3.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Petróleo y químicos","cuerpo":["Los derrames de petróleo, en el mar o en los ríos, cubren aves y mamíferos, contaminan costas y afectan la pesca durante años. En 1999, un choque de buques frente a Magdalena, en la provincia de Buenos Aires, causó uno de los mayores derrames en el Río de la Plata. Además, las industrias y los campos pueden liberar químicos como metales pesados, solventes o plaguicidas que llegan a los ríos. Algunos, llamados disruptores endocrinos, alteran las hormonas de peces y otros animales incluso en cantidades muy pequeñas."]},"solucion":{}},{"slug":"oceanos-3.s4.p8","orden":8,"grupo":"oceanos-3.s4.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tipo de contaminante es cada uno?","grupos":[{"id":"g1","nombre":"Hidrocarburos"},{"id":"g2","nombre":"Metales pesados"},{"id":"g3","nombre":"Otros químicos"}],"items":[{"id":"i1","texto":"Petróleo derramado por un buque"},{"id":"i2","texto":"Mercurio de una fábrica"},{"id":"i3","texto":"Plaguicidas arrastrados desde los campos"},{"id":"i4","texto":"Aceite de motor tirado a un desagüe"},{"id":"i5","texto":"Cromo de una curtiembre"},{"id":"i6","texto":"Solventes industriales"},{"id":"i7","texto":"Plomo de baterías mal descartadas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g2"},"explicacion":"Cada tipo de contaminante tiene efectos y soluciones distintas."}},{"slug":"oceanos-3.s4.p9","orden":9,"grupo":"oceanos-3.s4.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene preferir pescados chicos y variados a comer con frecuencia grandes predadores como el pez espada?","opciones":[{"id":"o1","texto":"Porque acumulan menos mercurio"},{"id":"o2","texto":"Porque los peces chicos no tienen proteínas"},{"id":"o3","texto":"Porque los grandes predadores son más caros"},{"id":"o4","texto":"Porque el pez espada es siempre ilegal"}]},"solucion":{"clave":["o1"],"explicacion":"Al estar más abajo en la cadena, los peces chicos acumulan menos contaminantes persistentes.","por_opcion":{"o3":"Puede ser, pero la razón de salud es el mercurio acumulado."}}},{"slug":"oceanos-3.s4.p10","orden":10,"grupo":"oceanos-3.s4.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un contaminante muy diluido en el agua nunca puede ser peligroso.","razones":[{"id":"r1","texto":"Porque puede concentrarse a lo largo de la cadena alimentaria"},{"id":"r2","texto":"Porque la dilución elimina cualquier sustancia"},{"id":"r3","texto":"Porque los peces filtran todos los contaminantes"}]},"solucion":{"valor":false,"explicacion":"Por biomagnificación, un contaminante persistente muy diluido puede concentrarse muchísimo en los predadores tope, incluidos los humanos que los comen.","clave":["r1"]}},{"slug":"oceanos-3.s4.p11","orden":11,"grupo":"oceanos-3.s4.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El Convenio de Minamata busca reducir el uso y las emisiones de mercurio en el mundo.","razones":[{"id":"r1","texto":"Porque es un tratado internacional sobre el mercurio"},{"id":"r2","texto":"Porque promueve usar más mercurio"},{"id":"r3","texto":"Porque trata sobre el plástico"}]},"solucion":{"valor":true,"explicacion":"Es un tratado de 2013, que Argentina ratificó, para proteger la salud y el ambiente del mercurio, incluida su llegada al agua.","clave":["r1"]}},{"slug":"oceanos-3.s4.p12","orden":12,"grupo":"oceanos-3.s4.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones reducen la llegada de contaminantes persistentes al agua? Marcá todas.","opciones":[{"id":"o1","texto":"Llevar pilas y baterías a puntos de recolección"},{"id":"o2","texto":"No tirar aceite de motor ni solventes a los desagües"},{"id":"o3","texto":"Controlar los efluentes industriales"},{"id":"o4","texto":"Quemar residuos junto al arroyo"},{"id":"o5","texto":"Tirar medicamentos vencidos al inodoro"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Muchas fuentes son cotidianas: cada residuo peligroso tiene su circuito correcto."}},{"slug":"oceanos-3.s4.p13","orden":13,"grupo":"oceanos-3.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El mercurio puede acumularse en los peces."},{"id":"s2","texto":"Los peces pequeños suelen tener más mercurio que los grandes predadores."},{"id":"s3","texto":"El caso Minamata dio nombre a un tratado internacional sobre el mercurio."},{"id":"s4","texto":"El aceite de motor puede tirarse al desagüe si se diluye con agua."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los contaminantes persistentes exigen prevención: una vez en la cadena, es muy difícil sacarlos.","por_opcion":{"s2":"Es al revés, por biomagnificación.","s4":"Contamina igual; debe llevarse a un punto de recolección."}}},{"slug":"oceanos-3.s4.p14","orden":14,"grupo":"oceanos-3.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando un contaminante se acumula en un organismo con el tiempo se llama {{0}}; cuando aumenta en cada escalón de la cadena, {{1}}; y el tratado sobre el mercurio lleva el nombre de {{2}}.","banco":[{"id":"w1","texto":"bioacumulación"},{"id":"w2","texto":"biomagnificación"},{"id":"w3","texto":"Minamata"},{"id":"w4","texto":"fotosíntesis"},{"id":"w5","texto":"evaporación"},{"id":"w6","texto":"Kioto"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos clave sobre los contaminantes que se acumulan."}}]},{"slug":"oceanos-3.s5","orden":5,"tipo":"leccion","titulo_es":"Limpiar y prevenir","bajada_es":"Plantas de tratamiento, control industrial, cuencas que se recuperan y lo que todavía falta.","minutos":11,"pasos":[{"slug":"oceanos-3.s5.p1","orden":1,"grupo":"oceanos-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tratar las cloacas","cuerpo":["Una planta de tratamiento de aguas residuales tiene varias etapas. En el tratamiento primario se separan los sólidos y las grasas. En el secundario, bacterias descomponen la materia orgánica disuelta. En el terciario, se remueven nutrientes como el nitrógeno y el fósforo, o se desinfecta el agua. Cuantas más etapas, más limpia sale el agua al río. En el Área Metropolitana de Buenos Aires se construyeron grandes obras para llevar las cloacas a plantas de tratamiento y alejar las descargas de la costa."]},"solucion":{}},{"slug":"oceanos-3.s5.p2","orden":2,"grupo":"oceanos-3.s5.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas del tratamiento de aguas residuales.","items":[{"id":"i1","texto":"Separar sólidos y grasas (primario)"},{"id":"i2","texto":"Descomponer la materia orgánica con bacterias (secundario)"},{"id":"i3","texto":"Remover nutrientes y desinfectar (terciario)"},{"id":"i4","texto":"Devolver el agua tratada al río"}]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada etapa remueve un tipo distinto de contaminante."}},{"slug":"oceanos-3.s5.p3","orden":3,"grupo":"oceanos-3.s5.p3","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada etapa con lo que remueve.","izquierda":[{"id":"a1","texto":"Tratamiento primario"},{"id":"a2","texto":"Tratamiento secundario"},{"id":"a3","texto":"Tratamiento terciario"}],"derecha":[{"id":"b1","texto":"Sólidos y grasas"},{"id":"b2","texto":"Materia orgánica disuelta"},{"id":"b3","texto":"Nitrógeno, fósforo y microorganismos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Un tratamiento solo primario deja pasar buena parte de la contaminación."}},{"slug":"oceanos-3.s5.p4","orden":4,"grupo":"oceanos-3.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ríos que se recuperan","cuerpo":["Hay ríos que estuvieron muy contaminados y se recuperaron en parte. En 1986, un incendio en una planta química en Suiza derramó toneladas de sustancias tóxicas en el río Rin y mató peces a lo largo de cientos de kilómetros. Los países de la cuenca acordaron un programa conjunto: plantas de tratamiento, control industrial, monitoreo compartido y metas claras. Décadas después, especies como el salmón volvieron a remontar el río. La recuperación es posible, pero lleva tiempo, inversión y cooperación."]},"solucion":{}},{"slug":"oceanos-3.s5.p5","orden":5,"grupo":"oceanos-3.s5.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la recuperación del Rin.","items":[{"id":"i1","texto":"Un accidente industrial contamina gravemente el río"},{"id":"i2","texto":"Los países de la cuenca acuerdan un programa conjunto"},{"id":"i3","texto":"Construyen plantas de tratamiento y controlan industrias"},{"id":"i4","texto":"Monitorean el agua con metas compartidas"},{"id":"i5","texto":"Décadas después, vuelven especies que habían desaparecido"},{"id":"i6","texto":"El río se limpia solo en pocos meses sin hacer nada"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cooperación, inversión y constancia: la receta de un río que se recupera."}},{"slug":"oceanos-3.s5.p6","orden":6,"grupo":"oceanos-3.s5.p6","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hizo falta para recuperar el Rin? Marcá todo.","opciones":[{"id":"o1","texto":"Cooperación entre los países de la cuenca"},{"id":"o2","texto":"Plantas de tratamiento"},{"id":"o3","texto":"Control de las industrias"},{"id":"o4","texto":"Monitoreo compartido durante décadas"},{"id":"o5","texto":"Esperar sin hacer nada"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un río compartido necesita soluciones compartidas."}},{"slug":"oceanos-3.s5.p7","orden":7,"grupo":"oceanos-3.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Prevenir en casa y en el barrio","cuerpo":["Muchas acciones cotidianas protegen el agua: no tirar aceite de cocina por la pileta (se puede juntar en botellas y llevar a puntos de recolección), no tirar basura en la calle, llevar pilas y medicamentos vencidos a los lugares indicados, usar productos de limpieza en la dosis justa y conectar las casas a la red cloacal cuando llega al barrio."]},"solucion":{}},{"slug":"oceanos-3.s5.p8","orden":8,"grupo":"oceanos-3.s5.p8","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción protege o contamina el agua?","grupos":[{"id":"g1","nombre":"Protege"},{"id":"g2","nombre":"Contamina"}],"items":[{"id":"i1","texto":"Juntar el aceite de cocina usado en una botella"},{"id":"i2","texto":"Tirar aceite por la pileta de la cocina"},{"id":"i3","texto":"Conectar la casa a la red cloacal"},{"id":"i4","texto":"Tirar basura en la cuneta"},{"id":"i5","texto":"Llevar pilas a un punto de recolección"},{"id":"i6","texto":"Lavar el auto con detergente sobre el cordón"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Lo que se tira en casa y en la calle llega, tarde o temprano, al río."}},{"slug":"oceanos-3.s5.p9","orden":9,"grupo":"oceanos-3.s5.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio de 2.000 hogares, cada uno junta 500 mililitros de aceite de cocina usado por mes en lugar de tirarlo por la pileta. ¿Cuántos litros por año dejan de ir a las cloacas?","unidad":"litros","decimales":0,"contexto":"2000 hogares; 500 mL por mes cada uno."},"solucion":{"valor":12000,"tolerancia":240,"explicacion":"2.000 × 500 mL × 12 = 12.000 litros por año. El aceite tapa cañerías, dificulta el tratamiento y forma películas en el agua; bien recolectado, puede convertirse en biodiésel."}},{"slug":"oceanos-3.s5.p9.v2","orden":9,"grupo":"oceanos-3.s5.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio de 5.000 hogares, cada uno junta 300 mililitros de aceite de cocina usado por mes en lugar de tirarlo por la pileta. ¿Cuántos litros por año dejan de ir a las cloacas?","unidad":"litros","decimales":0,"contexto":"5000 hogares; 300 mL por mes cada uno."},"solucion":{"valor":18000,"tolerancia":360,"explicacion":"5.000 × 300 mL × 12 = 18.000 litros por año. El aceite tapa cañerías, dificulta el tratamiento y forma películas en el agua; bien recolectado, puede convertirse en biodiésel."}},{"slug":"oceanos-3.s5.p9.v3","orden":9,"grupo":"oceanos-3.s5.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un barrio de 1.200 hogares, cada uno junta 750 mililitros de aceite de cocina usado por mes en lugar de tirarlo por la pileta. ¿Cuántos litros por año dejan de ir a las cloacas?","unidad":"litros","decimales":0,"contexto":"1200 hogares; 750 mL por mes cada uno."},"solucion":{"valor":10800,"tolerancia":216,"explicacion":"1.200 × 750 mL × 12 = 10.800 litros por año. El aceite tapa cañerías, dificulta el tratamiento y forma películas en el agua; bien recolectado, puede convertirse en biodiésel."}},{"slug":"oceanos-3.s5.p10","orden":10,"grupo":"oceanos-3.s5.p10","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una vez que un río está muy contaminado, ya no se puede recuperar.","razones":[{"id":"r1","texto":"Porque hay ríos que se recuperaron con esfuerzo sostenido"},{"id":"r2","texto":"Porque los ríos se limpian solos en días"},{"id":"r3","texto":"Porque ningún río estuvo nunca contaminado"}]},"solucion":{"valor":false,"explicacion":"Hay casos, como el Rin, en que la cooperación y la inversión sostenidas lograron recuperar buena parte de la vida del río, aunque llevó décadas.","clave":["r1"]}},{"slug":"oceanos-3.s5.p11","orden":11,"grupo":"oceanos-3.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué etapa del tratamiento de cloacas es clave para evitar la eutrofización río abajo?","opciones":[{"id":"o1","texto":"El tratamiento terciario, que remueve nutrientes"},{"id":"o2","texto":"El tratamiento primario, que separa grasas"},{"id":"o3","texto":"Ninguna: la eutrofización no tiene relación con las cloacas"},{"id":"o4","texto":"Pintar de verde la planta de tratamiento"}]},"solucion":{"clave":["o1"],"explicacion":"Sacar el nitrógeno y el fósforo antes de descargar corta el alimento de las floraciones.","por_opcion":{"o3":"Las cloacas aportan mucho nitrógeno y fósforo."}}},{"slug":"oceanos-3.s5.p12","orden":12,"grupo":"oceanos-3.s5.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas medidas para un arroyo urbano contaminado, de la de mayor impacto a la de menor.","items":[{"id":"i1","texto":"Conectar los barrios a la red cloacal con tratamiento"},{"id":"i2","texto":"Controlar los vertidos de las industrias"},{"id":"i3","texto":"Recuperar las orillas con vegetación"},{"id":"i4","texto":"Pintar un mural sobre el arroyo"}],"extremos":["Mayor impacto","Menor impacto"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero se corta lo que entra; después se recupera el ambiente; lo simbólico acompaña.","valores":{"i1":"la mayor","i2":"grande","i3":"media","i4":"simbólica"}}},{"slug":"oceanos-3.s5.p13","orden":13,"grupo":"oceanos-3.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan municipal y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Construiremos una planta con tratamiento secundario y terciario."},{"id":"s2","texto":"El tratamiento primario alcanza para devolver agua limpia al río."},{"id":"s3","texto":"Controlaremos los efluentes de las industrias del parque industrial."},{"id":"s4","texto":"No hace falta monitorear después de construir la planta."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Tratar, controlar y medir: tres patas que se sostienen entre sí.","por_opcion":{"s2":"Solo separa sólidos y grasas; hacen falta más etapas.","s4":"Sin monitoreo no se sabe si la calidad del agua mejora."}}},{"slug":"oceanos-3.s5.p14","orden":14,"grupo":"oceanos-3.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La etapa que separa sólidos y grasas es el tratamiento {{0}}; la que remueve nutrientes es el {{1}}; y el río europeo que se recuperó tras un programa conjunto es el {{2}}.","banco":[{"id":"w1","texto":"primario"},{"id":"w2","texto":"terciario"},{"id":"w3","texto":"Rin"},{"id":"w4","texto":"final"},{"id":"w5","texto":"inicial"},{"id":"w6","texto":"Nilo"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas clave sobre cómo se limpia el agua."}}]},{"slug":"oceanos-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: ríos y mares contaminados","bajada_es":"Fuentes, nutrientes, plásticos, contaminantes que se acumulan y tratamiento, mezclados.","minutos":8,"pasos":[{"slug":"oceanos-3.s6.p1","orden":1,"grupo":"oceanos-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Ríos y mares contaminados». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"oceanos-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el arroyo del parque industrial","bajada_es":"Un arroyo que desemboca en un río grande recibe descargas de un parque industrial y de barrios sin cloacas. Armá el diagnóstico y el plan.","minutos":10,"pasos":[{"slug":"oceanos-3.s7.p1","orden":1,"grupo":"oceanos-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos","cuerpo":["Un municipio midió el arroyo en tres puntos: antes del parque industrial, después del parque y después de los barrios sin cloacas. Midió el oxígeno disuelto (los peces necesitan, en general, más de 5 mg/L), las bacterias fecales y la presencia de cromo, un metal que usan las curtiembres."],"datos":{"tipo":"tabla","titulo":"Mediciones en el arroyo (datos ficticios)","columnas":["Punto","Oxígeno (mg/L)","Bacterias fecales","Cromo"],"filas":[["Antes del parque","7,5","bajas","no detectado"],["Después del parque","5,0","bajas","alto"],["Después de los barrios","2,0","muy altas","alto"]],"nota":"Datos ficticios para el ejercicio."}},"solucion":{}},{"slug":"oceanos-3.s7.p2","orden":2,"grupo":"oceanos-3.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos mg/L de oxígeno se pierden entre el primer y el último punto?","unidad":"mg/L","decimales":1,"contexto":"Oxígeno disuelto de 7,5 a 2,0 mg/L."},"solucion":{"valor":5.5,"tolerancia":0.11,"explicacion":"7,5 − 2,0 = 5,5 mg/L. Con 2 mg/L, la mayoría de los peces no puede sobrevivir."}},{"slug":"oceanos-3.s7.p3","orden":3,"grupo":"oceanos-3.s7.p3","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con su fuente probable.","izquierda":[{"id":"a1","texto":"Cromo alto después del parque"},{"id":"a2","texto":"Bacterias fecales muy altas"},{"id":"a3","texto":"Oxígeno muy bajo al final"}],"derecha":[{"id":"b1","texto":"Curtiembres del parque industrial"},{"id":"b2","texto":"Barrios sin cloacas"},{"id":"b3","texto":"Materia orgánica de las cloacas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Medir en varios puntos permite saber de dónde viene cada contaminante."}},{"slug":"oceanos-3.s7.p4","orden":4,"grupo":"oceanos-3.s7.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué fue clave medir en tres puntos del arroyo?","opciones":[{"id":"o1","texto":"Para saber qué aporta cada tramo"},{"id":"o2","texto":"Porque la ley exige medir siempre tres veces"},{"id":"o3","texto":"Porque un solo punto da siempre el mismo resultado"},{"id":"o4","texto":"Para gastar el presupuesto de monitoreo"}]},"solucion":{"clave":["o1"],"explicacion":"Comparar antes y después de cada fuente es la forma de atribuir responsabilidades.","por_opcion":{"o3":"Un solo punto no permite distinguir las fuentes."}}},{"slug":"oceanos-3.s7.p5","orden":5,"grupo":"oceanos-3.s7.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería incluir el plan? Marcá todo.","opciones":[{"id":"o1","texto":"Exigir tratamiento de efluentes a las curtiembres"},{"id":"o2","texto":"Extender la red cloacal a los barrios"},{"id":"o3","texto":"Monitoreo periódico y público en los tres puntos"},{"id":"o4","texto":"Tapar el arroyo con un entubado para no verlo"},{"id":"o5","texto":"Culpar solo a los vecinos de los barrios"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Cada fuente tiene su responsable y su solución; esconder el arroyo no lo limpia."}},{"slug":"oceanos-3.s7.p6","orden":6,"grupo":"oceanos-3.s7.p6","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas por urgencia sanitaria, de mayor a menor.","items":[{"id":"i1","texto":"Cloacas para los barrios con bacterias fecales muy altas"},{"id":"i2","texto":"Control del cromo de las curtiembres"},{"id":"i3","texto":"Recuperar las orillas con vegetación nativa"},{"id":"i4","texto":"Carteles de educación ambiental"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero lo que enferma a las personas; después lo que se acumula; y lo de fondo acompaña.","valores":{"i1":"riesgo directo para la salud","i2":"metal tóxico y persistente","i3":"mejora de fondo","i4":"complementaria"}}},{"slug":"oceanos-3.s7.p7","orden":7,"grupo":"oceanos-3.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el arroyo desemboca en un río grande, la contaminación se diluye y deja de ser un problema.","razones":[{"id":"r1","texto":"Porque los metales persisten y las bacterias afectan río abajo"},{"id":"r2","texto":"Porque los ríos grandes no reciben arroyos"},{"id":"r3","texto":"Porque el cromo se evapora"}]},"solucion":{"valor":false,"explicacion":"La dilución no elimina metales persistentes como el cromo, que pueden acumularse, y las bacterias afectan a quienes usan el agua río abajo.","clave":["r1"]}},{"slug":"oceanos-3.s7.p8","orden":8,"grupo":"oceanos-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El municipio redacta el informe. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"El cromo aparece después del parque industrial."},{"id":"s2","texto":"Las bacterias fecales vienen de las curtiembres."},{"id":"s3","texto":"El oxígeno cae a niveles peligrosos para los peces."},{"id":"s4","texto":"No publicaremos los datos para no alarmar a la población."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen diagnóstico lee bien los datos y los comparte.","por_opcion":{"s2":"Aparecen después de los barrios sin cloacas.","s4":"La información ambiental es pública y ayuda a exigir soluciones."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"oceanos-4","rama":"agua_azul","orden":4,"nivel":2,"titulo_es":"Áreas protegidas del mar y la costa","bajada_es":"Del Banco Burdwood a Península Valdés: por qué se protege el mar, qué hace que una reserva funcione de verdad y cómo se cuidan las costas con la gente que vive de ellas.","objetivos_es":["Explicar qué es un área marina protegida y sus niveles de protección","Conocer las áreas marinas protegidas de Argentina y su marco legal","Identificar las características que hacen efectiva una reserva marina","Reconocer los servicios que brindan las costas, las marismas y las dunas","Proponer formas de gestión participativa y de control"],"repasa":["oceanos-1","oceanos-2","animales-4","oceanos-3"],"requiere_tronco":2,"fuentes":["cdb-meta-3","mpatlas","mci-10-3","edgar-2014-neoli","ley-27490-amp","parques-nacionales","ramsar","pampa-azul"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"oceanos-4.s1","orden":1,"tipo":"leccion","titulo_es":"Por qué proteger el mar","bajada_es":"Qué es un área marina protegida, cuánto océano está protegido de verdad y la meta del 30 % para 2030.","minutos":11,"pasos":[{"slug":"oceanos-4.s1.p1","orden":1,"grupo":"oceanos-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Áreas marinas protegidas","cuerpo":["Un área marina protegida es una zona del mar con reglas especiales para conservar su biodiversidad: puede prohibir la pesca, limitar ciertos métodos, regular el turismo o la navegación. No todas protegen igual. En algunas no se puede extraer nada (áreas de protección total); en otras se permiten actividades controladas; y otras existen en los papeles pero casi no tienen reglas ni control."]},"solucion":{}},{"slug":"oceanos-4.s1.p2","orden":2,"grupo":"oceanos-4.s1.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué nivel de protección tiene cada zona?","grupos":[{"id":"g1","nombre":"Protección total"},{"id":"g2","nombre":"Protección parcial"},{"id":"g3","nombre":"Protección en los papeles"}],"items":[{"id":"i1","texto":"Zona donde no se puede pescar ni extraer nada"},{"id":"i2","texto":"Zona donde se permite pesca artesanal con reglas"},{"id":"i3","texto":"Área declarada, sin reglas ni controles en el agua"},{"id":"i4","texto":"Reserva estricta solo para investigación"},{"id":"i5","texto":"Área con turismo regulado y pesca limitada"},{"id":"i6","texto":"Reserva donde se sigue pescando igual que antes"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"El nombre \"área protegida\" no dice cuánto protege: hay que mirar las reglas y si se cumplen."}},{"slug":"oceanos-4.s1.p3","orden":3,"grupo":"oceanos-4.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto está protegido","cuerpo":["En 2022, casi todos los países acordaron en el Marco Mundial de Biodiversidad la meta de conservar al menos el 30 % de las zonas terrestres y marinas para 2030. En 2026, alrededor del 10 % del océano estaba dentro de áreas marinas protegidas, pero según el Atlas de Protección Marina solo algo más del 3 % tenía protección total o alta. La diferencia muestra cuántas áreas permiten actividades dañinas o existen solo en los papeles."],"datos":{"tipo":"barras","titulo":"Océano protegido (aproximado, 2026)","unidad":"%","filas":[{"etiqueta":"Meta 2030","valor":30},{"etiqueta":"En áreas marinas protegidas","valor":10},{"etiqueta":"Con protección total o alta","valor":3.3}],"nota":"Marco Mundial de Biodiversidad; Marine Protection Atlas."}},"solucion":{}},{"slug":"oceanos-4.s1.p4","orden":4,"grupo":"oceanos-4.s1.p4","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje del océano tenía protección total o alta en 2026, según el Atlas de Protección Marina.","min":0,"max":50,"paso":0.1,"unidad":"%","escala":"lineal"},"solucion":{"valor":3.3,"banda":"lineal","explicacion":"Algo más del 3 %. Aunque cerca del 10 % está en áreas protegidas, la mayor parte permite actividades que dañan los ecosistemas."}},{"slug":"oceanos-4.s1.p5","orden":5,"grupo":"oceanos-4.s1.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la meta es proteger el 30 % del océano para 2030 y hoy se protege el 10 %, ¿cuántos puntos porcentuales faltan?","unidad":"puntos porcentuales","decimales":1,"contexto":"Meta 30 %; hoy 10 %."},"solucion":{"valor":20,"tolerancia":0.1,"explicacion":"30 − 10 = 20 puntos. Y no alcanza con declarar áreas: tienen que proteger de verdad."}},{"slug":"oceanos-4.s1.p5.v2","orden":5,"grupo":"oceanos-4.s1.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la meta es proteger el 30 % del océano para 2030 y hoy se protege el 3,3 %, ¿cuántos puntos porcentuales faltan?","unidad":"puntos porcentuales","decimales":1,"contexto":"Meta 30 %; hoy 3.3 %."},"solucion":{"valor":26.7,"tolerancia":0.1,"explicacion":"30 − 3,3 = 26,7 puntos. Y no alcanza con declarar áreas: tienen que proteger de verdad."}},{"slug":"oceanos-4.s1.p5.v3","orden":5,"grupo":"oceanos-4.s1.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la meta es proteger el 30 % del océano para 2030 y hoy se protege el 12 %, ¿cuántos puntos porcentuales faltan?","unidad":"puntos porcentuales","decimales":1,"contexto":"Meta 30 %; hoy 12 %."},"solucion":{"valor":18,"tolerancia":0.1,"explicacion":"30 − 12 = 18 puntos. Y no alcanza con declarar áreas: tienen que proteger de verdad."}},{"slug":"oceanos-4.s1.p6","orden":6,"grupo":"oceanos-4.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Para qué sirven","cuerpo":["Las áreas marinas protegidas bien diseñadas permiten que las poblaciones de peces se recuperen, que los ejemplares crezcan más grandes y pongan más huevos, que se regeneren hábitats como los bosques de algas o los corales de agua fría, y que las especies amenazadas tengan refugio. También sirven como \"línea de base\": lugares para comparar y entender cómo cambia el mar fuera de ellas."]},"solucion":{}},{"slug":"oceanos-4.s1.p7","orden":7,"grupo":"oceanos-4.s1.p7","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Para qué sirve un área marina protegida bien diseñada? Marcá todo.","opciones":[{"id":"o1","texto":"Recuperar poblaciones de peces"},{"id":"o2","texto":"Dar refugio a especies amenazadas"},{"id":"o3","texto":"Regenerar hábitats del fondo marino"},{"id":"o4","texto":"Servir de comparación para la ciencia"},{"id":"o5","texto":"Aumentar la pesca de arrastre dentro del área"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Las áreas protegidas son a la vez refugio, criadero y laboratorio."}},{"slug":"oceanos-4.s1.p8","orden":8,"grupo":"oceanos-4.s1.p8","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué significa la meta \"30 × 30\"?","opciones":[{"id":"o1","texto":"Conservar el 30 % de tierras y mares para 2030"},{"id":"o2","texto":"Pescar un 30 % más para el año 2030"},{"id":"o3","texto":"Proteger 30 especies en 30 países"},{"id":"o4","texto":"Plantar 30 árboles por persona para 2030"}]},"solucion":{"clave":["o1"],"explicacion":"Es la meta central del Marco Mundial de Biodiversidad acordado en 2022.","por_opcion":{"o3":"Se trata de porcentaje de superficie, no de especies."}}},{"slug":"oceanos-4.s1.p9","orden":9,"grupo":"oceanos-4.s1.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un país declara muchas áreas marinas protegidas, seguro está protegiendo bien su mar.","razones":[{"id":"r1","texto":"Porque importan las reglas y el control, no solo la declaración"},{"id":"r2","texto":"Porque las áreas protegidas nunca funcionan"},{"id":"r3","texto":"Porque el mar no se puede proteger"}]},"solucion":{"valor":false,"explicacion":"Depende de las reglas y de que se cumplan. Muchas áreas permiten actividades dañinas o no tienen control: son \"parques de papel\".","clave":["r1"]}},{"slug":"oceanos-4.s1.p10","orden":10,"grupo":"oceanos-4.s1.p10","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Área marina protegida"},{"id":"a2","texto":"Protección total"},{"id":"a3","texto":"Parque de papel"},{"id":"a4","texto":"Meta 30 × 30"}],"derecha":[{"id":"b1","texto":"Zona del mar con reglas para conservar la biodiversidad"},{"id":"b2","texto":"No se permite extraer nada"},{"id":"b3","texto":"Área declarada que no protege en la práctica"},{"id":"b4","texto":"Conservar el 30 % para 2030"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Vocabulario básico de la conservación marina."}},{"slug":"oceanos-4.s1.p11","orden":11,"grupo":"oceanos-4.s1.p11","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo proteger a los predadores puede recuperar un bosque de algas.","items":[{"id":"i1","texto":"Se prohíbe pescar a los predadores de los erizos de mar"},{"id":"i2","texto":"Los predadores se recuperan y comen más erizos"},{"id":"i3","texto":"Los erizos dejan de arrasar las algas"},{"id":"i4","texto":"El bosque de algas vuelve a crecer"},{"id":"i5","texto":"Regresan los peces que se crían entre las algas"},{"id":"i6","texto":"Los erizos protegen a las algas de los peces"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Proteger un eslabón de la cadena puede recuperar todo el ecosistema."}},{"slug":"oceanos-4.s1.p12","orden":12,"grupo":"oceanos-4.s1.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Toda área marina protegida prohíbe la pesca en toda su superficie.","razones":[{"id":"r1","texto":"Porque muchas áreas combinan zonas con reglas distintas"},{"id":"r2","texto":"Porque ninguna área prohíbe la pesca"},{"id":"r3","texto":"Porque las áreas protegidas no tienen reglas"}]},"solucion":{"valor":false,"explicacion":"Solo las zonas de protección total prohíben toda extracción. Muchas áreas combinan zonas estrictas con zonas de uso regulado.","clave":["r1"]}},{"slug":"oceanos-4.s1.p13","orden":13,"grupo":"oceanos-4.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La meta mundial es conservar el 30 % de los mares para 2030."},{"id":"s2","texto":"Ya se protege de forma total el 30 % del océano."},{"id":"s3","texto":"No todas las áreas marinas protegidas protegen igual."},{"id":"s4","texto":"En cualquier área protegida está prohibido todo tipo de actividad."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Leer bien los números evita celebrar metas que todavía no se cumplieron.","por_opcion":{"s2":"Solo algo más del 3 % tiene protección total o alta.","s4":"Muchas permiten actividades reguladas; solo algunas son de protección total."}}},{"slug":"oceanos-4.s1.p14","orden":14,"grupo":"oceanos-4.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La meta mundial es conservar el {{0}} % de los mares para 2030; con protección total o alta está algo más del {{1}} %; y un área que no protege en la práctica es un parque de {{2}}.","banco":[{"id":"w1","texto":"30"},{"id":"w2","texto":"3"},{"id":"w3","texto":"papel"},{"id":"w4","texto":"50"},{"id":"w5","texto":"15"},{"id":"w6","texto":"cristal"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos clave sobre la protección del océano."}}]},{"slug":"oceanos-4.s2","orden":2,"tipo":"leccion","titulo_es":"El mar protegido de Argentina","bajada_es":"Namuncurá-Banco Burdwood, Yaganes y el Sistema Nacional de Áreas Marinas Protegidas.","minutos":11,"pasos":[{"slug":"oceanos-4.s2.p1","orden":1,"grupo":"oceanos-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un sistema nacional","cuerpo":["En 2013, Argentina creó su primera área marina protegida en alta mar: Namuncurá-Banco Burdwood, una meseta submarina al sur de la Isla de los Estados, con corales de agua fría, esponjas y una enorme diversidad de invertebrados, que funciona como criadero de muchas especies. En 2014, la Ley 27.037 creó el Sistema Nacional de Áreas Marinas Protegidas, con distintas categorías de manejo. Y en 2018, la Ley 27.490 creó dos áreas más: Yaganes, de unos 69.000 km², y Namuncurá-Banco Burdwood II, de unos 32.000 km²."]},"solucion":{}},{"slug":"oceanos-4.s2.p2","orden":2,"grupo":"oceanos-4.s2.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estos hitos del mar protegido argentino.","items":[{"id":"i1","texto":"Se crea el área Namuncurá-Banco Burdwood"},{"id":"i2","texto":"La Ley 27.037 crea el Sistema Nacional de Áreas Marinas Protegidas"},{"id":"i3","texto":"La Ley 27.490 crea Yaganes y Namuncurá-Banco Burdwood II"}],"extremos":["Más antiguo","Más reciente"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"2013, 2014 y 2018: en pocos años, Argentina armó un sistema de áreas marinas protegidas."}},{"slug":"oceanos-4.s2.p3","orden":3,"grupo":"oceanos-4.s2.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Yaganes tiene unos 69.000 km² y Namuncurá-Banco Burdwood II unos 32.000 km². ¿Cuántos km² suman las dos áreas?","unidad":"km²","decimales":0,"contexto":"69000 km² más 32000 km²."},"solucion":{"valor":101000,"tolerancia":1,"explicacion":"69.000 + 32.000 = 101.000 km²: más de 100.000 km² de mar protegido, una superficie mayor que la de muchas provincias."}},{"slug":"oceanos-4.s2.p3.v2","orden":3,"grupo":"oceanos-4.s2.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según la ley, Yaganes tiene 68.834 km² y Namuncurá-Banco Burdwood II 32.336 km². ¿Cuánto suman? Redondeá al entero.","unidad":"km²","decimales":0,"contexto":"68834 km² más 32336 km²."},"solucion":{"valor":101170,"tolerancia":1,"explicacion":"68.834 + 32.336 = 101.170 km²: más de 100.000 km² de mar protegido, una superficie mayor que la de muchas provincias."}},{"slug":"oceanos-4.s2.p3.v3","orden":3,"grupo":"oceanos-4.s2.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Yaganes mide unos 69.000 km² y Burdwood II unos 32.000 km², ¿cuántos km² agregó la ley de 2018?","unidad":"km²","decimales":0,"contexto":"69000 km² más 32000 km²."},"solucion":{"valor":101000,"tolerancia":1,"explicacion":"69.000 + 32.000 = 101.000 km²: más de 100.000 km² de mar protegido, una superficie mayor que la de muchas provincias."}},{"slug":"oceanos-4.s2.p4","orden":4,"grupo":"oceanos-4.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Categorías","cuerpo":["Dentro de las áreas marinas hay zonas con distintas reglas. En una reserva nacional marina estricta solo se permite investigación científica: no se pesca ni se extrae nada. En un parque nacional marino se protege la biodiversidad y se permiten actividades como la investigación y un turismo muy regulado. En una reserva nacional marina se permiten algunas actividades controladas, compatibles con la conservación."]},"solucion":{}},{"slug":"oceanos-4.s2.p5","orden":5,"grupo":"oceanos-4.s2.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada categoría con lo que permite.","izquierda":[{"id":"a1","texto":"Reserva nacional marina estricta"},{"id":"a2","texto":"Parque nacional marino"},{"id":"a3","texto":"Reserva nacional marina"}],"derecha":[{"id":"b1","texto":"Solo investigación científica"},{"id":"b2","texto":"Conservación con visitas muy reguladas"},{"id":"b3","texto":"Algunas actividades controladas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Combinar categorías permite proteger estrictamente lo más frágil y regular lo demás."}},{"slug":"oceanos-4.s2.p6","orden":6,"grupo":"oceanos-4.s2.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el Banco Burdwood es un lugar valioso para proteger?","opciones":[{"id":"o1","texto":"Tiene corales de agua fría y funciona como criadero"},{"id":"o2","texto":"Porque allí hay playas turísticas muy visitadas"},{"id":"o3","texto":"Porque es una zona de pesca industrial muy intensa"},{"id":"o4","texto":"Porque no tiene vida marina"}]},"solucion":{"clave":["o1"],"explicacion":"Los fondos con corales y esponjas crecen muy lento: si se dañan, tardan décadas en recuperarse.","por_opcion":{"o3":"Protegerlo es justamente limitar la presión sobre sus fondos."}}},{"slug":"oceanos-4.s2.p7","orden":7,"grupo":"oceanos-4.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En el Mar Argentino, las áreas marinas protegidas prohíben siempre todo tipo de actividad en toda su superficie.","razones":[{"id":"r1","texto":"Porque combinan zonas con reglas distintas"},{"id":"r2","texto":"Porque en ellas se permite pescar sin límites"},{"id":"r3","texto":"Porque no tienen ninguna regla"}]},"solucion":{"valor":false,"explicacion":"Combinan zonas: algunas estrictas, donde solo se investiga, y otras donde se permiten actividades controladas.","clave":["r1"]}},{"slug":"oceanos-4.s2.p8","orden":8,"grupo":"oceanos-4.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Controlar lo que está lejos","cuerpo":["Proteger áreas en alta mar plantea un desafío: están lejos de la costa y son enormes. El control combina patrullajes de la Prefectura Naval y la Armada, seguimiento satelital de los buques pesqueros y campañas científicas. Pampa Azul, una iniciativa del Estado para la investigación del Mar Argentino, organiza campañas en estas áreas para conocer su biodiversidad y evaluar si la protección funciona."]},"solucion":{}},{"slug":"oceanos-4.s2.p9","orden":9,"grupo":"oceanos-4.s2.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué herramientas sirven para controlar un área marina lejana? Marcá todas.","opciones":[{"id":"o1","texto":"Seguimiento satelital de buques"},{"id":"o2","texto":"Patrullajes navales"},{"id":"o3","texto":"Campañas científicas periódicas"},{"id":"o4","texto":"Carteles en la playa más cercana"},{"id":"o5","texto":"Confiar en que nadie entre"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La tecnología satelital cambió la posibilidad de controlar el mar abierto."}},{"slug":"oceanos-4.s2.p10","orden":10,"grupo":"oceanos-4.s2.p10","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo se crea un área marina protegida.","items":[{"id":"i1","texto":"Los científicos identifican una zona de alto valor ecológico"},{"id":"i2","texto":"Se propone un área con zonas y reglas"},{"id":"i3","texto":"El Congreso sanciona una ley que la crea"},{"id":"i4","texto":"Se arma un plan de manejo y control"},{"id":"i5","texto":"Se monitorea si la biodiversidad se recupera"},{"id":"i6","texto":"Se declara el área y nunca más se vuelve a medir"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Crear un área es el comienzo: sin plan de manejo y monitoreo, queda en los papeles."}},{"slug":"oceanos-4.s2.p11","orden":11,"grupo":"oceanos-4.s2.p11","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos km² de mar protegido sumaron las dos áreas creadas por la Ley 27.490 en 2018.","min":1000,"max":10000000,"paso":1,"unidad":"km²","escala":"log"},"solucion":{"valor":101000,"banda":"log","explicacion":"Unos 101.000 km²: Yaganes, con unos 69.000, y Namuncurá-Banco Burdwood II, con unos 32.000."}},{"slug":"oceanos-4.s2.p12","orden":12,"grupo":"oceanos-4.s2.p12","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué permite el seguimiento satelital de los buques pesqueros?","opciones":[{"id":"o1","texto":"Ver en qué zonas navegan y pescan"},{"id":"o2","texto":"Pescar más rápido dentro de las reservas"},{"id":"o3","texto":"Cambiar el clima en alta mar"},{"id":"o4","texto":"Evitar que los barcos usen combustible"}]},"solucion":{"clave":["o1"],"explicacion":"Los datos satelitales permiten detectar si un buque entra a una zona protegida.","por_opcion":{"o3":"Los satélites observan; no modifican el clima."}}},{"slug":"oceanos-4.s2.p13","orden":13,"grupo":"oceanos-4.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Namuncurá-Banco Burdwood está al sur de la Isla de los Estados."},{"id":"s2","texto":"La Ley 27.490 creó las áreas Yaganes y Namuncurá-Banco Burdwood II."},{"id":"s3","texto":"Las áreas marinas en alta mar no necesitan control porque están lejos."},{"id":"s4","texto":"En una reserva estricta se permite la pesca de arrastre."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Conocer las áreas del propio país es el primer paso para defenderlas.","por_opcion":{"s3":"Justamente por estar lejos necesitan control satelital y patrullajes.","s4":"En una reserva estricta solo se permite la investigación."}}},{"slug":"oceanos-4.s2.p14","orden":14,"grupo":"oceanos-4.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La primera área marina protegida de alta mar de Argentina es Namuncurá-Banco {{0}}; el sistema nacional lo creó la Ley {{1}}; y en una reserva marina {{2}} solo se permite investigación.","banco":[{"id":"w1","texto":"Burdwood"},{"id":"w2","texto":"27.037"},{"id":"w3","texto":"estricta"},{"id":"w4","texto":"Valdés"},{"id":"w5","texto":"26.331"},{"id":"w6","texto":"turística"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos clave sobre el mar protegido argentino."}}]},{"slug":"oceanos-4.s3","orden":3,"tipo":"leccion","titulo_es":"Qué hace que funcionen","bajada_es":"Sin extracción, controladas, antiguas, grandes y aisladas: las cinco características de una reserva marina efectiva.","minutos":11,"pasos":[{"slug":"oceanos-4.s3.p1","orden":1,"grupo":"oceanos-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cinco características","cuerpo":["Un estudio publicado en la revista Nature en 2014 comparó 87 áreas marinas protegidas de todo el mundo. Encontró que su efectividad dependía de cinco características: que no se permita la extracción (sin pesca), que se controle bien el cumplimiento, que tengan más de 10 años, que sean grandes (más de 100 km²) y que estén aisladas por aguas profundas o arena. Las áreas con cuatro o cinco de esas características tenían mucha más biomasa de peces que las áreas con una o ninguna, que casi no se diferenciaban de las zonas sin protección."],"lista":["Sin extracción","Control efectivo","Antigüedad de más de 10 años","Gran tamaño, más de 100 km²","Aislamiento natural"]},"solucion":{}},{"slug":"oceanos-4.s3.p2","orden":2,"grupo":"oceanos-4.s3.p2","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué características hacen efectiva una reserva marina, según el estudio de 2014? Marcá todas.","opciones":[{"id":"o1","texto":"No permitir la extracción"},{"id":"o2","texto":"Control efectivo del cumplimiento"},{"id":"o3","texto":"Tener más de 10 años"},{"id":"o4","texto":"Ser grande"},{"id":"o5","texto":"Estar pintada en un mapa aunque nadie la controle"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Declarar no alcanza: hacen falta reglas fuertes, control, tiempo y tamaño."}},{"slug":"oceanos-4.s3.p3","orden":3,"grupo":"oceanos-4.s3.p3","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas reservas de la más a la menos efectiva, según las cinco características.","items":[{"id":"i1","texto":"Sin pesca, controlada, de 20 años, grande y aislada"},{"id":"i2","texto":"Sin pesca, controlada, de 12 años y grande"},{"id":"i3","texto":"Sin pesca, pero sin control y de 2 años"},{"id":"i4","texto":"Con pesca permitida, sin control y recién creada"}],"extremos":["Más efectiva","Menos efectiva"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La efectividad se acumula: cada característica suma.","valores":{"i1":"5 de 5","i2":"4 de 5","i3":"1 de 5","i4":"0 de 5"}}},{"slug":"oceanos-4.s3.p4","orden":4,"grupo":"oceanos-4.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El derrame de peces","cuerpo":["Una reserva sin pesca bien protegida no solo beneficia a lo que está adentro. Los peces crecen, se reproducen más y algunos adultos y muchas larvas salen de la reserva hacia las zonas vecinas, donde pueden pescarse. Se lo llama efecto derrame. Por eso, en muchos lugares, los pescadores que al principio se oponían terminan defendiendo las reservas."]},"solucion":{}},{"slug":"oceanos-4.s3.p5","orden":5,"grupo":"oceanos-4.s3.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena del efecto derrame.","items":[{"id":"i1","texto":"Se prohíbe pescar en una zona"},{"id":"i2","texto":"Los peces viven más y crecen más grandes"},{"id":"i3","texto":"Los peces grandes producen muchos más huevos"},{"id":"i4","texto":"Larvas y adultos salen hacia las zonas vecinas"},{"id":"i5","texto":"Mejora la pesca alrededor de la reserva"},{"id":"i6","texto":"Los peces se quedan encerrados para siempre dentro de la reserva"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Proteger una parte puede mejorar el conjunto."}},{"slug":"oceanos-4.s3.p6","orden":6,"grupo":"oceanos-4.s3.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué un pez grande aporta tanto a la población?","opciones":[{"id":"o1","texto":"Produce muchísimos más huevos que uno chico"},{"id":"o2","texto":"Porque come a todos los peces chicos"},{"id":"o3","texto":"Porque vive menos tiempo que los chicos"},{"id":"o4","texto":"Porque no necesita alimentarse"}]},"solucion":{"clave":["o1"],"explicacion":"En muchas especies, la producción de huevos crece mucho más rápido que el tamaño.","por_opcion":{"o3":"Suele vivir más; y cuanto más grande, más huevos."}}},{"slug":"oceanos-4.s3.p7","orden":7,"grupo":"oceanos-4.s3.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fuera de una reserva hay 20 kg de peces por hectárea y dentro 80 kg. ¿Cuántas veces más biomasa hay dentro?","unidad":"veces","decimales":1,"contexto":"20 kg/ha fuera; 80 kg/ha dentro."},"solucion":{"valor":4,"tolerancia":0.1,"explicacion":"80 ÷ 20 = 4 veces. Datos de ejemplo: en reservas bien protegidas, diferencias de varias veces son comunes."}},{"slug":"oceanos-4.s3.p7.v2","orden":7,"grupo":"oceanos-4.s3.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fuera de una reserva hay 15 kg de peces por hectárea y dentro 60 kg. ¿Cuántas veces más biomasa hay dentro?","unidad":"veces","decimales":1,"contexto":"15 kg/ha fuera; 60 kg/ha dentro."},"solucion":{"valor":4,"tolerancia":0.1,"explicacion":"60 ÷ 15 = 4 veces. Datos de ejemplo: en reservas bien protegidas, diferencias de varias veces son comunes."}},{"slug":"oceanos-4.s3.p7.v3","orden":7,"grupo":"oceanos-4.s3.p7","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fuera de una reserva hay 30 kg de peces por hectárea y dentro 75 kg. ¿Cuántas veces más biomasa hay dentro?","unidad":"veces","decimales":1,"contexto":"30 kg/ha fuera; 75 kg/ha dentro."},"solucion":{"valor":2.5,"tolerancia":0.1,"explicacion":"75 ÷ 30 = 2,5 veces. Datos de ejemplo: en reservas bien protegidas, diferencias de varias veces son comunes."}},{"slug":"oceanos-4.s3.p8","orden":8,"grupo":"oceanos-4.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Parques de papel","cuerpo":["Un \"parque de papel\" es un área protegida que existe en la ley pero no en el agua: no tiene plan de manejo, ni presupuesto, ni control, o permite las mismas actividades que antes. Son un riesgo doble: no protegen, y dan la falsa impresión de que el problema está resuelto."]},"solucion":{}},{"slug":"oceanos-4.s3.p9","orden":9,"grupo":"oceanos-4.s3.p9","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una señal de área efectiva o de parque de papel?","grupos":[{"id":"g1","nombre":"Área efectiva"},{"id":"g2","nombre":"Parque de papel"}],"items":[{"id":"i1","texto":"Plan de manejo aprobado y en marcha"},{"id":"i2","texto":"Sin presupuesto desde su creación"},{"id":"i3","texto":"Guardaparques y control satelital"},{"id":"i4","texto":"Se sigue pescando igual que antes"},{"id":"i5","texto":"Monitoreo científico periódico"},{"id":"i6","texto":"Nadie sabe dónde están sus límites"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las señales de efectividad se ven en el agua, no en el decreto."}},{"slug":"oceanos-4.s3.p10","orden":10,"grupo":"oceanos-4.s3.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una reserva marina recién creada ya muestra todos sus beneficios en el primer año.","razones":[{"id":"r1","texto":"Porque los peces necesitan años para crecer y reproducirse"},{"id":"r2","texto":"Porque las reservas nunca muestran beneficios"},{"id":"r3","texto":"Porque los beneficios desaparecen con el tiempo"}]},"solucion":{"valor":false,"explicacion":"Los beneficios crecen con los años: los peces necesitan tiempo para crecer y reproducirse. El estudio de 2014 destacó la antigüedad de más de 10 años.","clave":["r1"]}},{"slug":"oceanos-4.s3.p11","orden":11,"grupo":"oceanos-4.s3.p11","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada característica con por qué importa.","izquierda":[{"id":"a1","texto":"Sin extracción"},{"id":"a2","texto":"Control efectivo"},{"id":"a3","texto":"Antigüedad"},{"id":"a4","texto":"Tamaño grande"},{"id":"a5","texto":"Aislamiento"}],"derecha":[{"id":"b1","texto":"Los peces pueden crecer y reproducirse"},{"id":"b2","texto":"Las reglas se cumplen en el agua"},{"id":"b3","texto":"Los ecosistemas tardan en recuperarse"},{"id":"b4","texto":"Protege especies que se mueven mucho"},{"id":"b5","texto":"Dificulta la entrada ilegal"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Cada característica atiende una forma distinta en que una reserva puede fallar."}},{"slug":"oceanos-4.s3.p12","orden":12,"grupo":"oceanos-4.s3.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una reserva grande pero sin control funciona tan bien como una controlada.","razones":[{"id":"r1","texto":"Porque sin control las reglas no se cumplen"},{"id":"r2","texto":"Porque el tamaño es lo único que importa"},{"id":"r3","texto":"Porque el control empeora las reservas"}]},"solucion":{"valor":false,"explicacion":"El control es una de las cinco características clave: sin él, las reglas no se cumplen y la reserva se parece a una zona sin protección.","clave":["r1"]}},{"slug":"oceanos-4.s3.p13","orden":13,"grupo":"oceanos-4.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Las reservas sin pesca pueden mejorar la pesca en las zonas vecinas."},{"id":"s2","texto":"Una reserva chica, nueva y sin control protege tanto como una grande y antigua."},{"id":"s3","texto":"Un parque de papel da la falsa impresión de que el mar está protegido."},{"id":"s4","texto":"Los peces grandes aportan menos huevos que los chicos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La ciencia de las reservas marinas ayuda a diseñar áreas que funcionen.","por_opcion":{"s2":"La efectividad depende del tamaño, la antigüedad y el control.","s4":"Suelen aportar muchos más."}}},{"slug":"oceanos-4.s3.p14","orden":14,"grupo":"oceanos-4.s3.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando los peces de una reserva salen hacia las zonas vecinas se habla del efecto {{0}}; un área que existe solo en la ley es un parque de {{1}}; y las reservas más efectivas tienen más de {{2}} años.","banco":[{"id":"w1","texto":"derrame"},{"id":"w2","texto":"papel"},{"id":"w3","texto":"10"},{"id":"w4","texto":"rebote"},{"id":"w5","texto":"agua"},{"id":"w6","texto":"100"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas clave sobre la efectividad de las reservas marinas."}}]},{"slug":"oceanos-4.s4","orden":4,"tipo":"leccion","titulo_es":"Costas que nos protegen","bajada_es":"Marismas, dunas y humedales costeros: ecosistemas que frenan tormentas, guardan carbono y crían vida.","minutos":11,"pasos":[{"slug":"oceanos-4.s4.p1","orden":1,"grupo":"oceanos-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Barreras naturales","cuerpo":["Las costas no son solo playas para veranear. Las dunas amortiguan el oleaje y guardan arena que la playa recupera después de las tormentas. Las marismas —pastizales inundables en los bordes de estuarios y bahías— frenan las crecidas, filtran el agua y son criaderos de peces, cangrejos y aves. Cuando se urbanizan o se destruyen, las costas quedan más expuestas a la erosión, sobre todo con un mar que sube."]},"solucion":{}},{"slug":"oceanos-4.s4.p2","orden":2,"grupo":"oceanos-4.s4.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ecosistema costero con un servicio que brinda.","izquierda":[{"id":"a1","texto":"Dunas"},{"id":"a2","texto":"Marismas"},{"id":"a3","texto":"Humedales costeros"},{"id":"a4","texto":"Praderas submarinas"}],"derecha":[{"id":"b1","texto":"Amortiguan el oleaje y reservan arena"},{"id":"b2","texto":"Frenan crecidas y crían peces y cangrejos"},{"id":"b3","texto":"Filtran el agua y albergan aves"},{"id":"b4","texto":"Guardan carbono en el fondo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Los ecosistemas costeros son infraestructura natural."}},{"slug":"oceanos-4.s4.p3","orden":3,"grupo":"oceanos-4.s4.p3","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué urbanizar las dunas aumenta la erosión.","items":[{"id":"i1","texto":"Se construyen edificios sobre las dunas"},{"id":"i2","texto":"Las dunas ya no pueden moverse ni reponer arena"},{"id":"i3","texto":"Las tormentas se llevan la arena de la playa"},{"id":"i4","texto":"La playa no se recupera después de cada tormenta"},{"id":"i5","texto":"La costa retrocede y amenaza las construcciones"},{"id":"i6","texto":"Los edificios fabrican arena nueva"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Destruir la barrera natural deja a la costa, y a las construcciones, más expuestas."}},{"slug":"oceanos-4.s4.p4","orden":4,"grupo":"oceanos-4.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Casos argentinos","cuerpo":["La Bahía de Samborombón, en la provincia de Buenos Aires, es un sitio Ramsar desde 1997: sus marismas albergan aves migratorias y una de las últimas poblaciones de venado de las pampas. Península Valdés, en Chubut, es Patrimonio Mundial desde 1999: allí se reproducen la ballena franca austral, elefantes y lobos marinos, y el avistaje de ballenas está regulado. Muchas localidades de la costa atlántica tienen problemas de erosión por haber urbanizado sus dunas."]},"solucion":{}},{"slug":"oceanos-4.s4.p5","orden":5,"grupo":"oceanos-4.s4.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué valor principal tiene cada lugar?","grupos":[{"id":"g1","nombre":"Bahía de Samborombón"},{"id":"g2","nombre":"Península Valdés"}],"items":[{"id":"i1","texto":"Marismas con aves migratorias"},{"id":"i2","texto":"Reproducción de la ballena franca austral"},{"id":"i3","texto":"Refugio del venado de las pampas"},{"id":"i4","texto":"Colonias de elefantes marinos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Dos joyas de la costa argentina, protegidas por distintos reconocimientos internacionales."}},{"slug":"oceanos-4.s4.p6","orden":6,"grupo":"oceanos-4.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Carbono azul","cuerpo":["Las marismas y las praderas submarinas guardan carbono en sus suelos inundados, donde se descompone muy lentamente, durante siglos. A ese carbono se lo llama carbono azul. Cuando estos ecosistemas se destruyen, parte de ese carbono puede liberarse. Protegerlos es a la vez conservación, adaptación al cambio climático y mitigación."]},"solucion":{}},{"slug":"oceanos-4.s4.p7","orden":7,"grupo":"oceanos-4.s4.p7","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las marismas guardan tanto carbono?","opciones":[{"id":"o1","texto":"El suelo inundado frena la descomposición"},{"id":"o2","texto":"Porque tienen árboles muy altos y muy viejos"},{"id":"o3","texto":"Porque el agua salada fabrica carbono nuevo"},{"id":"o4","texto":"Porque están cubiertas de cemento y asfalto"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste con el suelo: menos oxígeno, descomposición más lenta, más carbono guardado.","por_opcion":{"o3":"El carbono viene de las plantas; el agua frena su descomposición."}}},{"slug":"oceanos-4.s4.p8","orden":8,"grupo":"oceanos-4.s4.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Proteger una marisma puede ser a la vez conservación, adaptación y mitigación del cambio climático.","razones":[{"id":"r1","texto":"Porque conserva, amortigua crecidas y guarda carbono"},{"id":"r2","texto":"Porque las marismas aumentan las inundaciones"},{"id":"r3","texto":"Porque no tienen relación con el clima"}]},"solucion":{"valor":true,"explicacion":"Conserva biodiversidad, frena crecidas y tormentas (adaptación) y guarda carbono (mitigación). Es una solución basada en la naturaleza.","clave":["r1"]}},{"slug":"oceanos-4.s4.p9","orden":9,"grupo":"oceanos-4.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una marisma de 1.000 hectáreas guarda en su suelo unas 200 toneladas de carbono por hectárea, ¿cuántas toneladas de carbono guarda en total?","unidad":"t de carbono","decimales":0,"contexto":"1000 ha; 200 t de carbono por hectárea."},"solucion":{"valor":200000,"tolerancia":4000,"explicacion":"1.000 × 200 = 200.000 toneladas de carbono. Valores de ejemplo: destruir la marisma podría liberar parte de ese carbono."}},{"slug":"oceanos-4.s4.p9.v2","orden":9,"grupo":"oceanos-4.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una marisma de 5.000 hectáreas guarda en su suelo unas 150 toneladas de carbono por hectárea, ¿cuántas toneladas de carbono guarda en total?","unidad":"t de carbono","decimales":0,"contexto":"5000 ha; 150 t de carbono por hectárea."},"solucion":{"valor":750000,"tolerancia":15000,"explicacion":"5.000 × 150 = 750.000 toneladas de carbono. Valores de ejemplo: destruir la marisma podría liberar parte de ese carbono."}},{"slug":"oceanos-4.s4.p9.v3","orden":9,"grupo":"oceanos-4.s4.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una marisma de 2.500 hectáreas guarda en su suelo unas 250 toneladas de carbono por hectárea, ¿cuántas toneladas de carbono guarda en total?","unidad":"t de carbono","decimales":0,"contexto":"2500 ha; 250 t de carbono por hectárea."},"solucion":{"valor":625000,"tolerancia":12500,"explicacion":"2.500 × 250 = 625.000 toneladas de carbono. Valores de ejemplo: destruir la marisma podría liberar parte de ese carbono."}},{"slug":"oceanos-4.s4.p10","orden":10,"grupo":"oceanos-4.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones protegen las costas? Marcá todas.","opciones":[{"id":"o1","texto":"Conservar las dunas y no construir sobre ellas"},{"id":"o2","texto":"Usar pasarelas para cruzar las dunas"},{"id":"o3","texto":"Proteger las marismas de los rellenos"},{"id":"o4","texto":"Circular con vehículos por las dunas"},{"id":"o5","texto":"Sacar arena de la playa para 